window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[2]={"203":{"example:203:exzh":"Safety comes first.","example:203:exzh2":"Is this road safe?","example:203:exzh3":"Please evacuate to a safe place.","example:203:exzh4":"We need to strengthen safety measures.","example:203:exzh5":"Be careful about safety when you walk at night.","grammar:203:ex:trans":"Safety is the most important thing.","grammar:203:ex:structure":"〜が第一です","grammar:203:ex:explain":"「安全が第一」 is a fixed idiomatic expression meaning safety first. Using 「が」 rather than 「は」 here treats 「安全」 as the subject being highlighted and singled out, carrying the nuance of (precisely) safety comes first. 「第一（だいいち）」 is used as a noun meaning top priority, ranked number one. The sentence-ending 「です」 is the polite copula. The 「〜が第一」 pattern can be applied to other things too — for example 「健康が第一」 — to declare what matters most.","grammar:203:ex:words:0:zh":"safe","grammar:203:ex:words:0:note":"あんぜん","grammar:203:ex:words:0:pos":"noun","grammar:203:ex:words:1:zh":"(nominative)","grammar:203:ex:words:1:pos":"particle","grammar:203:ex:words:2:zh":"first","grammar:203:ex:words:2:note":"だいいち","grammar:203:ex:words:2:pos":"noun","grammar:203:ex:words:3:zh":"(polite form)","grammar:203:ex:words:3:pos":"copula","grammar:203:ex:points:0":"安全が第一: safety first (idiomatic).","grammar:203:ex:points:1":"第一（だいいち）: first, top priority.","grammar:203:ex2:trans":"Is this road safe?","grammar:203:ex2:structure":"〜は安全ですか","grammar:203:ex2:words:0:zh":"this","grammar:203:ex2:words:0:pos":"pre-noun adjectival","grammar:203:ex2:words:1:zh":"road","grammar:203:ex2:words:1:note":"みち","grammar:203:ex2:words:1:pos":"noun","grammar:203:ex2:words:2:zh":"(topic)","grammar:203:ex2:words:2:pos":"particle","grammar:203:ex2:words:3:zh":"safe","grammar:203:ex2:words:3:note":"あんぜん","grammar:203:ex2:words:3:pos":"na-adjective","grammar:203:ex2:words:4:zh":"(polite form)","grammar:203:ex2:words:4:pos":"copula","grammar:203:ex2:words:5:zh":"(question)","grammar:203:ex2:words:5:pos":"particle","grammar:203:ex2:points:0":"安全: safe (na-adjective).","grammar:203:ex2:points:1":"〜ですか: question.","grammar:203:ex3:trans":"Please evacuate to a safe place.","grammar:203:ex3:structure":"〜な〜に〜てください","grammar:203:ex3:words:0:zh":"safe","grammar:203:ex3:words:0:note":"あんぜん","grammar:203:ex3:words:0:pos":"na-adjective","grammar:203:ex3:words:1:zh":"(attributive form)","grammar:203:ex3:words:1:pos":"auxiliary verb","grammar:203:ex3:words:2:zh":"place","grammar:203:ex3:words:2:note":"ばしょ","grammar:203:ex3:words:2:pos":"noun","grammar:203:ex3:words:3:zh":"(destination)","grammar:203:ex3:words:3:pos":"particle","grammar:203:ex3:words:4:zh":"evacuation","grammar:203:ex3:words:4:note":"ひなんして","grammar:203:ex3:words:4:pos":"verb","grammar:203:ex3:words:5:zh":"please","grammar:203:ex3:words:5:pos":"auxiliary verb","grammar:203:ex3:points:0":"安全な場所: a safe place (な + noun).","grammar:203:ex3:points:1":"避難する→避難して＋ください。","grammar:203:ex4:trans":"It is necessary to strengthen safety measures.","grammar:203:ex4:structure":"〜必要があります","grammar:203:ex4:words:0:zh":"safety measures","grammar:203:ex4:words:0:note":"あんぜんたいさく","grammar:203:ex4:words:0:pos":"noun","grammar:203:ex4:words:1:zh":"(object marker)","grammar:203:ex4:words:1:pos":"particle","grammar:203:ex4:words:2:zh":"strengthen","grammar:203:ex4:words:2:note":"きょうかする","grammar:203:ex4:words:2:pos":"verb","grammar:203:ex4:words:3:zh":"necessary","grammar:203:ex4:words:3:note":"ひつよう","grammar:203:ex4:words:3:pos":"noun","grammar:203:ex4:words:4:zh":"(nominative)","grammar:203:ex4:words:4:pos":"particle","grammar:203:ex4:words:5:zh":"there is / are","grammar:203:ex4:words:5:pos":"verb","grammar:203:ex4:points:0":"〜必要があります：it is necessary to…","grammar:203:ex4:points:1":"強化する: to strengthen.","grammar:203:ex5:trans":"When walking at night, be careful about safety.","grammar:203:ex5:structure":"〜ときは、〜に気をつけて","grammar:203:ex5:words:0:zh":"night road","grammar:203:ex5:words:0:note":"よみち","grammar:203:ex5:words:0:pos":"noun","grammar:203:ex5:words:1:zh":"(path)","grammar:203:ex5:words:1:pos":"particle","grammar:203:ex5:words:2:zh":"walk","grammar:203:ex5:words:2:note":"あるく","grammar:203:ex5:words:2:pos":"verb","grammar:203:ex5:words:3:zh":"time","grammar:203:ex5:words:3:note":"とき","grammar:203:ex5:words:3:pos":"noun","grammar:203:ex5:words:4:zh":"(contrast)","grammar:203:ex5:words:4:pos":"particle","grammar:203:ex5:words:5:zh":"safe","grammar:203:ex5:words:5:note":"あんぜん","grammar:203:ex5:words:5:pos":"na-adjective","grammar:203:ex5:words:6:zh":"(made adverbial)","grammar:203:ex5:words:6:pos":"particle","grammar:203:ex5:words:7:zh":"be careful","grammar:203:ex5:words:7:note":"きをつけて","grammar:203:ex5:words:7:pos":"set phrase","grammar:203:ex5:points:0":"〜ときは: when ….","grammar:203:ex5:points:1":"安全に気をつける: to be careful about safety (気をつける is idiomatic)."},"204":{"example:204:exzh":"I have an urgent errand, so I have to go right away.","example:204:exzh2":"Something urgent came up.","example:204:exzh3":"It suddenly started to rain.","example:204:exzh4":"When work comes up suddenly, mistakes can happen.","example:204:exzh5":"A quick response is needed.","grammar:204:ex:trans":"Because something urgent came up, I have to go right away.","grammar:204:ex:structure":"〜で、すぐに〜なければなりません","grammar:204:ex:explain":"「急」 is a na-adjective, so it takes 「な」 when it modifies 「用事」; 「急な用事」 means an urgent errand. In 「用事で」, 「で」 states the reason you have to go. 「すぐに」 modifies the action that follows, meaning right away. The negative form of 「行く」 is 「行かない」; changed to 「行かなければなりません」, it literally says if I don't go, it won't do, but actually means I must go, in a polite tone.","grammar:204:ex:words:0:zh":"urgent","grammar:204:ex:words:0:note":"きゅう","grammar:204:ex:words:0:pos":"na-adjective","grammar:204:ex:words:1:zh":"(links an adjective and a noun)","grammar:204:ex:words:1:pos":"auxiliary verb","grammar:204:ex:words:2:zh":"errand","grammar:204:ex:words:2:note":"ようじ","grammar:204:ex:words:2:pos":"noun","grammar:204:ex:words:3:zh":"(cause)","grammar:204:ex:words:3:pos":"particle","grammar:204:ex:words:4:zh":"soon","grammar:204:ex:words:4:pos":"adverb","grammar:204:ex:words:5:zh":"go","grammar:204:ex:words:5:note":"いか","grammar:204:ex:words:5:pos":"verb","grammar:204:ex:words:6:zh":"not (negative conditional connecting form)","grammar:204:ex:words:6:pos":"auxiliary verb","grammar:204:ex:words:7:zh":"(hypothetical condition)","grammar:204:ex:words:7:pos":"particle","grammar:204:ex:words:8:zh":"to work out, to be acceptable (used with a negative here)","grammar:204:ex:words:8:pos":"verb","grammar:204:ex:words:9:zh":"(negative connecting form of the polite ending)","grammar:204:ex:words:9:pos":"auxiliary verb","grammar:204:ex:words:10:zh":"(negative)","grammar:204:ex:words:10:pos":"auxiliary verb","grammar:204:ex:points:0":"「急な＋noun」 indicates something urgent or something that suddenly arises.","grammar:204:ex:points:1":"「で」 after a noun can indicate the cause of the situation that follows.","grammar:204:ex:points:2":"「verb nai-form minus ない ＋ なければなりません」 means must do ….","grammar:204:ex2:trans":"An urgent errand came up.","grammar:204:ex2:structure":"急な〜が入った","grammar:204:ex2:words:0:zh":"urgent","grammar:204:ex2:words:0:note":"きゅう","grammar:204:ex2:words:0:pos":"na-adjective","grammar:204:ex2:words:1:zh":"(attributive form)","grammar:204:ex2:words:1:pos":"auxiliary verb","grammar:204:ex2:words:2:zh":"thing / matter","grammar:204:ex2:words:2:note":"ようじ","grammar:204:ex2:words:2:pos":"noun","grammar:204:ex2:words:3:zh":"(nominative)","grammar:204:ex2:words:3:pos":"particle","grammar:204:ex2:words:4:zh":"came up","grammar:204:ex2:words:4:note":"はいった","grammar:204:ex2:words:4:pos":"verb","grammar:204:ex2:points:0":"急な用事: an urgent errand (な + noun).","grammar:204:ex2:points:1":"用事が入る: to have something come up (a last-minute arrangement).","grammar:204:ex3:trans":"It suddenly started to rain.","grammar:204:ex3:structure":"急に〜出した","grammar:204:ex3:words:0:zh":"suddenly","grammar:204:ex3:words:0:note":"きゅうに","grammar:204:ex3:words:0:pos":"adverb","grammar:204:ex3:words:1:zh":"rain","grammar:204:ex3:words:1:note":"あめ","grammar:204:ex3:words:1:pos":"noun","grammar:204:ex3:words:2:zh":"(nominative)","grammar:204:ex3:words:2:pos":"particle","grammar:204:ex3:words:3:zh":"started to fall","grammar:204:ex3:words:3:note":"ふりだした","grammar:204:ex3:words:3:pos":"verb","grammar:204:ex3:points:0":"急に: suddenly (adverb).","grammar:204:ex3:points:1":"〜出す: to start …ing (降り出す = to start falling).","grammar:204:ex4:trans":"In urgent work, mistakes sometimes happen.","grammar:204:ex4:structure":"〜では、verb dictionary form ＋ ことがあります","grammar:204:ex4:explain":"「急な仕事」 means urgent work, with 「な」 linking the na-adjective 「急」 to the noun 「仕事」. In 「仕事では」, 「で」 marks the situation and 「は」 brings that situation up as the topic. 「ミスをする」 means to make a mistake, with 「を」 marking the object. 「することがあります」 nominalizes the action with 「こと」 to say that it sometimes happens; if you changed it to 「したことがあります」, it would become the experience expression have made a mistake before.","grammar:204:ex4:words:0:zh":"urgent","grammar:204:ex4:words:0:note":"きゅう","grammar:204:ex4:words:0:pos":"na-adjective","grammar:204:ex4:words:1:zh":"(links an adjective and a noun)","grammar:204:ex4:words:1:pos":"auxiliary verb","grammar:204:ex4:words:2:zh":"work","grammar:204:ex4:words:2:note":"しごと","grammar:204:ex4:words:2:pos":"noun","grammar:204:ex4:words:3:zh":"(the situation in which something happens)","grammar:204:ex4:words:3:pos":"particle","grammar:204:ex4:words:4:zh":"(presents the situation as the topic)","grammar:204:ex4:words:4:pos":"particle","grammar:204:ex4:words:5:zh":"mistake","grammar:204:ex4:words:5:pos":"noun","grammar:204:ex4:words:6:zh":"(object)","grammar:204:ex4:words:6:pos":"particle","grammar:204:ex4:words:7:zh":"to make, to do","grammar:204:ex4:words:7:pos":"verb","grammar:204:ex4:words:8:zh":"(nominalizes the action)","grammar:204:ex4:words:8:pos":"noun","grammar:204:ex4:words:9:zh":"(nominative)","grammar:204:ex4:words:9:pos":"particle","grammar:204:ex4:words:10:zh":"to exist, to happen","grammar:204:ex4:words:10:pos":"verb","grammar:204:ex4:words:11:zh":"(polite ending)","grammar:204:ex4:words:11:pos":"auxiliary verb","grammar:204:ex4:points:0":"「では」 can bring up a certain situation, meaning in the case of ….","grammar:204:ex4:points:1":"「ミスをする」 is a common collocation meaning to make a mistake.","grammar:204:ex4:points:2":"「verb dictionary form ＋ ことがある」 means that something sometimes happens.","grammar:204:ex5:trans":"A quick response is needed.","grammar:204:ex5:structure":"急な〜が必要です","grammar:204:ex5:words:0:zh":"urgent","grammar:204:ex5:words:0:note":"きゅう","grammar:204:ex5:words:0:pos":"na-adjective","grammar:204:ex5:words:1:zh":"(attributive form)","grammar:204:ex5:words:1:pos":"auxiliary verb","grammar:204:ex5:words:2:zh":"response","grammar:204:ex5:words:2:note":"たいおう","grammar:204:ex5:words:2:pos":"noun","grammar:204:ex5:words:3:zh":"(object)","grammar:204:ex5:words:3:pos":"particle","grammar:204:ex5:words:4:zh":"necessary","grammar:204:ex5:words:4:note":"ひつよう","grammar:204:ex5:words:4:pos":"na-adjective","grammar:204:ex5:words:5:zh":"(polite form)","grammar:204:ex5:words:5:pos":"copula","grammar:204:ex5:points:0":"急な対応: a quick response (な + noun).","grammar:204:ex5:points:1":"「〜が必要です」: need …"},"205":{"example:205:exzh":"I bought a new car.","example:205:exzh2":"I put on new clothes.","example:205:exzh3":"I made a new friend.","example:205:exzh4":"I started reading a new book.","example:205:exzh5":"I came up with a new idea.","grammar:205:ex:trans":"Bought a new car.","grammar:205:ex:structure":"新しい〜を買った","grammar:205:ex:explain":"「新しい」 is an i-adjective and modifies the noun 「車」 directly, with no particle in between. 「を」 marks what was bought. 「買った」 is the plain past form (ta-form) of the godan verb 「買う」: 「買う」 takes the geminate sound change to 「買って」, and the past is 「買った」. Using the plain form (without です・ます) gives a more casual tone, as when talking to yourself or to someone close; for politeness you'd say 「買いました」. The whole sentence is (I) bought a new car.","grammar:205:ex:words:0:zh":"new","grammar:205:ex:words:0:note":"あたらしい","grammar:205:ex:words:0:pos":"adjective","grammar:205:ex:words:1:zh":"car","grammar:205:ex:words:1:note":"くるま","grammar:205:ex:words:1:pos":"noun","grammar:205:ex:words:2:zh":"(object marker)","grammar:205:ex:words:2:pos":"particle","grammar:205:ex:words:3:zh":"bought","grammar:205:ex:words:3:note":"かった","grammar:205:ex:words:3:pos":"verb","grammar:205:ex:points:0":"新しい車: a new car (i-adjective + noun).","grammar:205:ex:points:1":"買う→買った (past plain form).","grammar:205:ex2:trans":"Put on new clothes.","grammar:205:ex2:structure":"新しい〜を着た","grammar:205:ex2:words:0:zh":"new","grammar:205:ex2:words:0:note":"あたらしい","grammar:205:ex2:words:0:pos":"adjective","grammar:205:ex2:words:1:zh":"clothes","grammar:205:ex2:words:1:note":"ふく","grammar:205:ex2:words:1:pos":"noun","grammar:205:ex2:words:2:zh":"(object marker)","grammar:205:ex2:words:2:pos":"particle","grammar:205:ex2:words:3:zh":"put on","grammar:205:ex2:words:3:note":"きた","grammar:205:ex2:words:3:pos":"verb","grammar:205:ex2:points:0":"服を着る: to put on clothes.","grammar:205:ex2:points:1":"着る→着た (past plain form).","grammar:205:ex3:trans":"Made a new friend.","grammar:205:ex3:structure":"新しい〜ができた","grammar:205:ex3:words:0:zh":"new","grammar:205:ex3:words:0:note":"あたらしい","grammar:205:ex3:words:0:pos":"adjective","grammar:205:ex3:words:1:zh":"friend","grammar:205:ex3:words:1:note":"ともだち","grammar:205:ex3:words:1:pos":"noun","grammar:205:ex3:words:2:zh":"(nominative)","grammar:205:ex3:words:2:pos":"particle","grammar:205:ex3:words:3:zh":"came to have","grammar:205:ex3:words:3:pos":"verb","grammar:205:ex3:points:0":"❓友達ができる: to make a friend (できる expresses coming into being; the subject takes が).","grammar:205:ex3:points:1":"できる→できた。","grammar:205:ex4:trans":"Started reading a new book.","grammar:205:ex4:structure":"新しい〜を〜始めた","grammar:205:ex4:words:0:zh":"new","grammar:205:ex4:words:0:note":"あたらしい","grammar:205:ex4:words:0:pos":"adjective","grammar:205:ex4:words:1:zh":"book","grammar:205:ex4:words:1:note":"ほん","grammar:205:ex4:words:1:pos":"noun","grammar:205:ex4:words:2:zh":"(object marker)","grammar:205:ex4:words:2:pos":"particle","grammar:205:ex4:words:3:zh":"started reading","grammar:205:ex4:words:3:note":"よみはじめた","grammar:205:ex4:words:3:pos":"verb","grammar:205:ex4:points:0":"〜始める: to start …ing (読み ＋ 始める).","grammar:205:ex4:points:1":"読み始める→読み始めた。","grammar:205:ex5:trans":"Came up with a new idea.","grammar:205:ex5:structure":"〜を考えました","grammar:205:ex5:words:0:zh":"new","grammar:205:ex5:words:0:note":"あたらしい","grammar:205:ex5:words:0:pos":"adjective","grammar:205:ex5:words:1:zh":"idea","grammar:205:ex5:words:1:note":"loanword","grammar:205:ex5:words:1:pos":"noun","grammar:205:ex5:words:2:zh":"(object marker)","grammar:205:ex5:words:2:pos":"particle","grammar:205:ex5:words:3:zh":"thought up","grammar:205:ex5:words:3:note":"かんがえました","grammar:205:ex5:words:3:pos":"verb","grammar:205:ex5:points:0":"新しいアイデア: a new idea.","grammar:205:ex5:points:1":"考える→考えました。","exam:205:zh":"This is a new shop that just opened yesterday.","exam:205:why":"「できたばかり」 means it was just established, so 「新しい」 fits. 「古い」 means old, the opposite of just established."},"206":{"example:206:exzh":"The original plan changed.","example:206:exzh2":"At first it didn't go well.","example:206:exzh3":"He took the first step.","example:206:exzh4":"Treasure that first impression.","example:206:exzh5":"Please remember your original goal.","grammar:206:ex:trans":"The original plan changed.","grammar:206:ex:structure":"最初の〜が変わった","grammar:206:ex:explain":"「最初の予定」 links two nouns with 「の」, meaning the original plan. The key is the verb 「変わる」, an intransitive verb meaning something changes on its own; the thing that changes is marked with 「が」, hence 「予定が変わった」. It pairs with the transitive verb 「変える」 (to change something), which takes an object with 「を」. 「変わった」 is the plain past, showing the plan has already changed. To decide which to use, ask whether it changed by itself or someone changed it.","grammar:206:ex:words:0:zh":"first","grammar:206:ex:words:0:note":"さいしょ","grammar:206:ex:words:0:pos":"noun","grammar:206:ex:words:1:zh":"'s","grammar:206:ex:words:1:pos":"particle","grammar:206:ex:words:2:zh":"plan","grammar:206:ex:words:2:note":"よてい","grammar:206:ex:words:2:pos":"noun","grammar:206:ex:words:3:zh":"(nominative)","grammar:206:ex:words:3:pos":"particle","grammar:206:ex:words:4:zh":"changed","grammar:206:ex:words:4:note":"かわった","grammar:206:ex:words:4:pos":"verb","grammar:206:ex:points:0":"最初の予定: the original plan.","grammar:206:ex:points:1":"変わる: to change (intransitive verb; the subject takes が).","grammar:206:ex2:trans":"At first it didn't go well.","grammar:206:ex2:structure":"最初は〜なかった","grammar:206:ex2:words:0:zh":"first","grammar:206:ex2:words:0:note":"さいしょ","grammar:206:ex2:words:0:pos":"noun","grammar:206:ex2:words:1:zh":"(contrast)","grammar:206:ex2:words:1:pos":"particle","grammar:206:ex2:words:2:zh":"well","grammar:206:ex2:words:2:pos":"adverb","grammar:206:ex2:words:3:zh":"(past) didn't go smoothly","grammar:206:ex2:words:3:note":"いかなかった","grammar:206:ex2:words:3:pos":"verb","grammar:206:ex2:points:0":"うまくいく: to go well (idiomatic).","grammar:206:ex2:points:1":"最初は: at first (は marks contrast).","grammar:206:ex3:trans":"He took the first step.","grammar:206:ex3:structure":"〜を踏み出した","grammar:206:ex3:words:0:zh":"he","grammar:206:ex3:words:0:note":"かれ","grammar:206:ex3:words:0:pos":"pronoun","grammar:206:ex3:words:1:zh":"(topic)","grammar:206:ex3:words:1:pos":"particle","grammar:206:ex3:words:2:zh":"first","grammar:206:ex3:words:2:note":"さいしょ","grammar:206:ex3:words:2:pos":"noun","grammar:206:ex3:words:3:zh":"'s","grammar:206:ex3:words:3:pos":"particle","grammar:206:ex3:words:4:zh":"one step","grammar:206:ex3:words:4:note":"いっぽ","grammar:206:ex3:words:4:pos":"noun","grammar:206:ex3:words:5:zh":"(object marker)","grammar:206:ex3:words:5:pos":"particle","grammar:206:ex3:words:6:zh":"took a step","grammar:206:ex3:words:6:note":"ふみだした","grammar:206:ex3:words:6:pos":"verb","grammar:206:ex3:points:0":"最初の一歩: the first step.","grammar:206:ex3:points:1":"踏み出す: to step out, to take (a step).","grammar:206:ex4:trans":"Value the first impression.","grammar:206:ex4:structure":"〜を大切に","grammar:206:ex4:words:0:zh":"first","grammar:206:ex4:words:0:note":"さいしょ","grammar:206:ex4:words:0:pos":"noun","grammar:206:ex4:words:1:zh":"'s","grammar:206:ex4:words:1:pos":"particle","grammar:206:ex4:words:2:zh":"impression","grammar:206:ex4:words:2:note":"いんしょう","grammar:206:ex4:words:2:pos":"noun","grammar:206:ex4:words:3:zh":"(object marker)","grammar:206:ex4:words:3:pos":"particle","grammar:206:ex4:words:4:zh":"with care","grammar:206:ex4:words:4:note":"たいせつに","grammar:206:ex4:words:4:pos":"adverb","grammar:206:ex4:points:0":"最初の印象: the first impression.","grammar:206:ex4:points:1":"〜を大切に（する）: to value ….","grammar:206:ex5:trans":"Please recall the original goal.","grammar:206:ex5:structure":"〜を思い出してください","grammar:206:ex5:words:0:zh":"first","grammar:206:ex5:words:0:note":"さいしょ","grammar:206:ex5:words:0:pos":"noun","grammar:206:ex5:words:1:zh":"'s","grammar:206:ex5:words:1:pos":"particle","grammar:206:ex5:words:2:zh":"goal","grammar:206:ex5:words:2:note":"もくひょう","grammar:206:ex5:words:2:pos":"noun","grammar:206:ex5:words:3:zh":"(object marker)","grammar:206:ex5:words:3:pos":"particle","grammar:206:ex5:words:4:zh":"recall","grammar:206:ex5:words:4:note":"おもいだして","grammar:206:ex5:words:4:pos":"verb","grammar:206:ex5:words:5:zh":"please","grammar:206:ex5:words:5:pos":"auxiliary verb","grammar:206:ex5:points:0":"思い出す: to recall, to remember.","grammar:206:ex5:points:1":"最初の目標: the original goal."},"207":{"example:207:exzh":"Make preparations just in case.","example:207:exzh2":"There are ten thousand books.","example:207:exzh3":"Ten thousand people live in this city.","example:207:exzh4":"One person chosen from ten thousand.","example:207:exzh5":"A one-in-ten-thousand possibility.","grammar:207:ex:trans":"Make preparations in case something unexpected happens.","grammar:207:ex:structure":"万が一のための〜をする","grammar:207:ex:explain":"At the core is the idiomatic expression 「万が一（まんがいち）」, literally a one-in-ten-thousand chance, extended to mean just in case, if something unexpected happens. The following 「〜のための」 means for the sake of …, and the two 「の」 link 「万が一」 with 「準備」, giving preparations made just in case. In 「準備をする」, 「を」 marks the object: to make preparations. The whole sentence is about preparing ahead and guarding against a possible accident.","grammar:207:ex:words:0:zh":"just in case","grammar:207:ex:words:0:note":"まんがいち","grammar:207:ex:words:0:pos":"noun","grammar:207:ex:words:1:zh":"'s","grammar:207:ex:words:1:pos":"particle","grammar:207:ex:words:2:zh":"for the sake of","grammar:207:ex:words:2:pos":"noun","grammar:207:ex:words:3:zh":"'s","grammar:207:ex:words:3:pos":"particle","grammar:207:ex:words:4:zh":"prepare","grammar:207:ex:words:4:note":"じゅんび","grammar:207:ex:words:4:pos":"noun","grammar:207:ex:words:5:zh":"(object marker)","grammar:207:ex:words:5:pos":"particle","grammar:207:ex:words:6:zh":"do","grammar:207:ex:words:6:pos":"verb","grammar:207:ex:points:0":"万が一: just in case (idiomatic; literally a one-in-ten-thousand chance).","grammar:207:ex:points:1":"〜のための: for the sake of ….","grammar:207:ex2:trans":"There are ten thousand books.","grammar:207:ex2:structure":"一万冊の本＋が＋あります","grammar:207:ex2:words:0:zh":"ten thousand","grammar:207:ex2:words:0:note":"いちまん; how the number is read","grammar:207:ex2:words:0:pos":"numeral","grammar:207:ex2:words:1:zh":"books","grammar:207:ex2:words:1:note":"さつ; the counter for books","grammar:207:ex2:words:1:pos":"numeral with counter","grammar:207:ex2:words:2:zh":"'s","grammar:207:ex2:words:2:pos":"particle","grammar:207:ex2:words:3:zh":"book","grammar:207:ex2:words:3:note":"ほん; book","grammar:207:ex2:words:3:pos":"noun","grammar:207:ex2:words:4:zh":"subject marker","grammar:207:ex2:words:4:pos":"particle","grammar:207:ex2:words:5:zh":"there is / are","grammar:207:ex2:words:5:pos":"verb","grammar:207:ex2:points:0":"「万」 is the numeric unit for ten thousand; with 「一」 in front it becomes 「一万（いちまん）」, meaning ten thousand, while 「万」 on its own is read 「まん」.","grammar:207:ex2:points:1":"「冊」 is the counter for books; 「一万冊の本」 means ten thousand books, following counter ＋ 「の」 ＋ noun.","grammar:207:ex3:trans":"Ten thousand people live in this city.","grammar:207:ex3:structure":"〜には〜が住んでいる","grammar:207:ex3:words:0:zh":"this","grammar:207:ex3:words:0:pos":"pre-noun adjectival","grammar:207:ex3:words:1:zh":"city","grammar:207:ex3:words:1:note":"まち","grammar:207:ex3:words:1:pos":"noun","grammar:207:ex3:words:2:zh":"(location of existence)","grammar:207:ex3:words:2:pos":"particle","grammar:207:ex3:words:3:zh":"(contrast)","grammar:207:ex3:words:3:pos":"particle","grammar:207:ex3:words:4:zh":"ten thousand","grammar:207:ex3:words:4:note":"まん","grammar:207:ex3:words:4:pos":"noun","grammar:207:ex3:words:5:zh":"'s","grammar:207:ex3:words:5:pos":"particle","grammar:207:ex3:words:6:zh":"person","grammar:207:ex3:words:6:note":"ひと","grammar:207:ex3:words:6:pos":"noun","grammar:207:ex3:words:7:zh":"(nominative)","grammar:207:ex3:words:7:pos":"particle","grammar:207:ex3:words:8:zh":"live (there)","grammar:207:ex3:words:8:note":"すんでいる","grammar:207:ex3:words:8:pos":"verb","grammar:207:ex3:points:1":"〜に住んでいる: to live in ….","grammar:207:ex4:trans":"The one person chosen from among ten thousand.","grammar:207:ex4:structure":"〜の中から選ばれた〜","grammar:207:ex4:words:0:zh":"ten thousand","grammar:207:ex4:words:0:note":"まん","grammar:207:ex4:words:0:pos":"noun","grammar:207:ex4:words:1:zh":"'s","grammar:207:ex4:words:1:pos":"particle","grammar:207:ex4:words:2:zh":"inside","grammar:207:ex4:words:2:note":"なか","grammar:207:ex4:words:2:pos":"noun","grammar:207:ex4:words:3:zh":"from","grammar:207:ex4:words:3:pos":"particle","grammar:207:ex4:words:4:zh":"was chosen","grammar:207:ex4:words:4:note":"えらばれた (passive form)","grammar:207:ex4:words:4:pos":"verb","grammar:207:ex4:words:5:zh":"one person","grammar:207:ex4:words:5:note":"ひとり","grammar:207:ex4:words:5:pos":"noun","grammar:207:ex4:points:0":"〜の中から: from among ….","grammar:207:ex4:points:1":"選ばれる: to be chosen (passive form; 選ぶ→選ばれる).","grammar:207:ex5:trans":"A one-in-ten-thousand possibility.","grammar:207:ex5:structure":"万に一つの〜","grammar:207:ex5:words:0:zh":"ten thousand","grammar:207:ex5:words:0:note":"まん","grammar:207:ex5:words:0:pos":"noun","grammar:207:ex5:words:1:zh":"(ratio)","grammar:207:ex5:words:1:pos":"particle","grammar:207:ex5:words:2:zh":"one","grammar:207:ex5:words:2:note":"ひとつ","grammar:207:ex5:words:2:pos":"noun","grammar:207:ex5:words:3:zh":"'s","grammar:207:ex5:words:3:pos":"particle","grammar:207:ex5:words:4:zh":"possibility","grammar:207:ex5:words:4:note":"かのうせい","grammar:207:ex5:words:4:pos":"noun","grammar:207:ex5:points:0":"万に一つ: one in ten thousand (an extremely small chance; idiomatic).","grammar:207:ex5:points:1":"可能性: possibility.","exam:207:zh":"There are ten 1,000-yen bills, so the total is 10,000 yen.","exam:207:why":"1,000 times 10 is 10,000, so 「万」 is the answer. 「千」 is only 1,000, which doesn't match the total of ten bills."},"208":{"example:208:exzh":"I made a promise with him.","example:208:exzh2":"Keeping promises is important.","example:208:exzh3":"I wasn't late for the time we agreed on.","example:208:exzh4":"Making a promise means responsibility.","example:208:exzh5":"Don't forget your promise.","grammar:208:ex:trans":"Made a promise with him.","grammar:208:ex:structure":"〜と約束をした","grammar:208:ex:explain":"「約束をする」 means the same as simply 「約束する」 — to promise — except that here 「約束」 is treated as a noun marked with 「を」, with 「する」 as the action verb. The key particle is 「と」, which marks the partner in a mutual action you do together, so 「彼と」 is with him, agreeing with each other. 「した」 is the plain past of 「する」, showing the promise has been made. The whole sentence is Made a promise with him.","grammar:208:ex:words:0:zh":"he","grammar:208:ex:words:0:note":"かれ","grammar:208:ex:words:0:pos":"pronoun","grammar:208:ex:words:1:zh":"with","grammar:208:ex:words:1:pos":"particle","grammar:208:ex:words:2:zh":"appointment","grammar:208:ex:words:2:note":"やくそく","grammar:208:ex:words:2:pos":"noun","grammar:208:ex:words:3:zh":"(object marker)","grammar:208:ex:words:3:pos":"particle","grammar:208:ex:words:4:zh":"did","grammar:208:ex:words:4:pos":"verb","grammar:208:ex:points:0":"約束をする: to promise (= 約束する).","grammar:208:ex:points:1":"〜と約束をする: to promise with ….","grammar:208:ex2:trans":"Keeping promises is important.","grammar:208:ex2:structure":"〜ことが大事です","grammar:208:ex2:words:0:zh":"appointment","grammar:208:ex2:words:0:note":"やくそく","grammar:208:ex2:words:0:pos":"noun","grammar:208:ex2:words:1:zh":"(object marker)","grammar:208:ex2:words:1:pos":"particle","grammar:208:ex2:words:2:zh":"obey","grammar:208:ex2:words:2:note":"まもる","grammar:208:ex2:words:2:pos":"verb","grammar:208:ex2:words:3:zh":"(nominalizer)","grammar:208:ex2:words:3:pos":"noun","grammar:208:ex2:words:4:zh":"(nominative)","grammar:208:ex2:words:4:pos":"particle","grammar:208:ex2:words:5:zh":"important","grammar:208:ex2:words:5:note":"だいじ","grammar:208:ex2:words:5:pos":"na-adjective","grammar:208:ex2:words:6:zh":"(polite form)","grammar:208:ex2:words:6:pos":"copula","grammar:208:ex2:points:0":"約束を守る: to keep a promise (idiomatic).","grammar:208:ex2:points:1":"verb ＋ こと: nominalizes the phrase so it can act as the subject.","grammar:208:ex3:trans":"Wasn't late for the agreed time.","grammar:208:ex3:structure":"〜に遅れませんでした","grammar:208:ex3:words:0:zh":"appointment","grammar:208:ex3:words:0:note":"やくそく","grammar:208:ex3:words:0:pos":"noun","grammar:208:ex3:words:1:zh":"'s","grammar:208:ex3:words:1:pos":"particle","grammar:208:ex3:words:2:zh":"time","grammar:208:ex3:words:2:note":"じかん","grammar:208:ex3:words:2:pos":"noun","grammar:208:ex3:words:3:zh":"(point in time)","grammar:208:ex3:words:3:pos":"particle","grammar:208:ex3:words:4:zh":"(past) wasn't late","grammar:208:ex3:words:4:note":"おくれませんでした","grammar:208:ex3:words:4:pos":"verb","grammar:208:ex3:points:0":"約束の時間: the agreed time.","grammar:208:ex3:points:1":"遅れませんでした: wasn't late (polite past negative).","grammar:208:ex4:trans":"Making a promise is a responsibility.","grammar:208:ex4:structure":"〜ということは〜です","grammar:208:ex4:words:0:zh":"appointment","grammar:208:ex4:words:0:note":"やくそく","grammar:208:ex4:words:0:pos":"noun","grammar:208:ex4:words:1:zh":"(object marker)","grammar:208:ex4:words:1:pos":"particle","grammar:208:ex4:words:2:zh":"do","grammar:208:ex4:words:2:pos":"verb","grammar:208:ex4:words:3:zh":"the matter of …","grammar:208:ex4:words:3:pos":"set phrase","grammar:208:ex4:words:4:zh":"(topic)","grammar:208:ex4:words:4:pos":"particle","grammar:208:ex4:words:5:zh":"responsibility","grammar:208:ex4:words:5:note":"せきにん","grammar:208:ex4:words:5:pos":"noun","grammar:208:ex4:words:6:zh":"is","grammar:208:ex4:words:6:pos":"copula","grammar:208:ex4:points:0":"〜ということは: what … means is … (definition / explanation).","grammar:208:ex4:points:1":"約束をする: to make a promise.","grammar:208:ex5:trans":"Please don't forget the promise.","grammar:208:ex5:structure":"〜を忘れないように","grammar:208:ex5:words:0:zh":"appointment","grammar:208:ex5:words:0:note":"やくそく","grammar:208:ex5:words:0:pos":"noun","grammar:208:ex5:words:1:zh":"(object marker)","grammar:208:ex5:words:1:pos":"particle","grammar:208:ex5:words:2:zh":"don't forget","grammar:208:ex5:words:2:note":"わすれないように","grammar:208:ex5:words:2:pos":"verb","grammar:208:ex5:points:0":"〜ないように: so as not to … / don't … (a gentle reminder).","grammar:208:ex5:points:1":"忘れる→忘れない＋ように。"},"209":{"example:209:exzh":"The dollar has gone up.","example:209:exzh2":"How many yen is one dollar?","example:209:exzh3":"I'll pay in dollars.","example:209:exzh4":"He's saving dollars.","example:209:exzh5":"The dollar keeps weakening.","grammar:209:ex:trans":"The dollar has gone up.","grammar:209:ex:structure":"〜が高くなりました","grammar:209:ex:explain":"The key is the change pattern 「adjective ku-form ＋ なる」: the i-adjective 「高い」 drops い and becomes 「高く」, and with 「なる」 (to become) it expresses a natural change of state — to get expensive, to get high. 「ドルが」 uses 「が」 to point out what changes. The ending 「なりました」 is the polite past of 「なる」, so the sentence means the dollar has gone up. This 「〜くなる」 is the basic, very useful pattern for saying getting more … or becoming ….","grammar:209:ex:words:0:zh":"dollar","grammar:209:ex:words:0:note":"loanword","grammar:209:ex:words:0:pos":"noun","grammar:209:ex:words:1:zh":"(nominative)","grammar:209:ex:words:1:pos":"particle","grammar:209:ex:words:2:zh":"high ground","grammar:209:ex:words:2:note":"たかく","grammar:209:ex:words:2:pos":"adverb","grammar:209:ex:words:3:zh":"become","grammar:209:ex:words:3:pos":"verb","grammar:209:ex:points:0":"高くなる: to get expensive / to get high (i-adjective く + なる).","grammar:209:ex:points:1":"高い → 高く + なりました.","grammar:209:ex2:trans":"How many yen is one dollar?","grammar:209:ex2:structure":"〜は何円ですか","grammar:209:ex2:words:0:zh":"one dollar","grammar:209:ex2:words:0:note":"いちドル","grammar:209:ex2:words:0:pos":"noun","grammar:209:ex2:words:1:zh":"(topic)","grammar:209:ex2:words:1:pos":"particle","grammar:209:ex2:words:2:zh":"how many yen","grammar:209:ex2:words:2:note":"なんえん","grammar:209:ex2:words:2:pos":"question word","grammar:209:ex2:words:3:zh":"is","grammar:209:ex2:words:3:pos":"copula","grammar:209:ex2:words:4:zh":"(question)","grammar:209:ex2:words:4:pos":"particle","grammar:209:ex2:points:0":"何円: how many yen.","grammar:209:ex2:points:1":"一ドル: one dollar.","grammar:209:ex3:trans":"I'll pay in dollars.","grammar:209:ex3:structure":"〜で支払います","grammar:209:ex3:words:0:zh":"dollar","grammar:209:ex3:words:0:note":"loanword","grammar:209:ex3:words:0:pos":"noun","grammar:209:ex3:words:1:zh":"(means)","grammar:209:ex3:words:1:pos":"particle","grammar:209:ex3:words:2:zh":"pay","grammar:209:ex3:words:2:note":"しはらいます","grammar:209:ex3:words:2:pos":"verb","grammar:209:ex3:points:0":"❓で: marks the means (in dollars).","grammar:209:ex3:points:1":"支払う: to pay.","grammar:209:ex4:trans":"He's saving dollars.","grammar:209:ex4:structure":"〜を貯めています","grammar:209:ex4:words:0:zh":"he","grammar:209:ex4:words:0:note":"かれ","grammar:209:ex4:words:0:pos":"pronoun","grammar:209:ex4:words:1:zh":"(topic)","grammar:209:ex4:words:1:pos":"particle","grammar:209:ex4:words:2:zh":"dollar","grammar:209:ex4:words:2:note":"loanword","grammar:209:ex4:words:2:pos":"noun","grammar:209:ex4:words:3:zh":"(object marker)","grammar:209:ex4:words:3:pos":"particle","grammar:209:ex4:words:4:zh":"saving up","grammar:209:ex4:words:4:note":"ためています","grammar:209:ex4:words:4:pos":"verb","grammar:209:ex4:points:0":"貯める: to save, to put aside.","grammar:209:ex4:points:1":"〜ている: ongoing action.","grammar:209:ex5:trans":"The dollar keeps weakening.","grammar:209:ex5:structure":"〜が続いています","grammar:209:ex5:words:0:zh":"a weak dollar","grammar:209:ex5:words:0:note":"ドルやす","grammar:209:ex5:words:0:pos":"noun","grammar:209:ex5:words:1:zh":"(nominative)","grammar:209:ex5:words:1:pos":"particle","grammar:209:ex5:words:2:zh":"continues","grammar:209:ex5:words:2:note":"つづいています","grammar:209:ex5:words:2:pos":"verb","grammar:209:ex5:points:0":"ドル安: a weak dollar (安 = cheap / losing value).","grammar:209:ex5:points:1":"続く: to continue (intransitive verb; the subject takes が).","exam:209:zh":"The money used in America is the dollar.","exam:209:why":"The money used in America is 「ドル」. 「円」 is the Japanese yen, so it can't be the answer for America's currency."},"210":{"example:210:exzh":"He's married.","example:210:exzh2":"When is the wedding?","example:210:exzh3":"I want to get married.","example:210:exzh4":"Married life is tough.","example:210:exzh5":"I'm preparing for the wedding.","grammar:210:ex:trans":"He's married.","grammar:210:ex:structure":"〜は結婚しています","grammar:210:ex:explain":"This is the sentence people misread most easily. Here 「結婚する＋ている」 does not mean \"in the middle of getting married\"; it describes the continuing state of being married. With verbs that express an instantaneous change, like 「結婚する」, 「住む」, and 「知る」, adding 「〜ている」 usually points to the state left behind after the change, not an action in progress. So 「結婚しています」 means \"(to be in the state of) already being married\". To ask someone whether they are married, say 「結婚していますか」.","grammar:210:ex:words:0:zh":"he","grammar:210:ex:words:0:note":"かれ","grammar:210:ex:words:0:pos":"pronoun","grammar:210:ex:words:1:zh":"(topic)","grammar:210:ex:words:1:pos":"particle","grammar:210:ex:words:2:zh":"(already) married","grammar:210:ex:words:2:note":"けっこんしています","grammar:210:ex:words:2:pos":"verb","grammar:210:ex:points:0":"❗結婚している: (in) the state of being married (not in the middle of getting married).","grammar:210:ex:points:1":"結婚する＋ている: expresses a state.","grammar:210:ex2:trans":"When is the wedding?","grammar:210:ex2:structure":"〜はいつですか","grammar:210:ex2:words:0:zh":"wedding","grammar:210:ex2:words:0:note":"けっこんしき","grammar:210:ex2:words:0:pos":"noun","grammar:210:ex2:words:1:zh":"(topic)","grammar:210:ex2:words:1:pos":"particle","grammar:210:ex2:words:2:zh":"when","grammar:210:ex2:words:2:pos":"question word","grammar:210:ex2:words:3:zh":"is","grammar:210:ex2:words:3:pos":"copula","grammar:210:ex2:words:4:zh":"(question)","grammar:210:ex2:words:4:pos":"particle","grammar:210:ex2:points:0":"結婚式: wedding.","grammar:210:ex2:points:1":"いつ: when.","grammar:210:ex3:trans":"I want to get married.","grammar:210:ex3:structure":"〜たいと思っています","grammar:210:ex3:words:0:zh":"want to get married","grammar:210:ex3:words:0:note":"けっこんしたい","grammar:210:ex3:words:0:pos":"verb","grammar:210:ex3:words:1:zh":"(quotation)","grammar:210:ex3:words:1:pos":"particle","grammar:210:ex3:words:2:zh":"thinking","grammar:210:ex3:words:2:note":"おもっています","grammar:210:ex3:words:2:pos":"verb","grammar:210:ex3:points:0":"〜たいと思っています: (I) want to… (a gentle, indirect way to express a wish).","grammar:210:ex3:points:1":"結婚する → 結婚したい.","grammar:210:ex4:trans":"Married life is hard.","grammar:210:ex4:structure":"〜は大変です","grammar:210:ex4:words:0:zh":"married life","grammar:210:ex4:words:0:note":"けっこんせいかつ","grammar:210:ex4:words:0:pos":"noun","grammar:210:ex4:words:1:zh":"(topic)","grammar:210:ex4:words:1:pos":"particle","grammar:210:ex4:words:2:zh":"tough","grammar:210:ex4:words:2:note":"たいへん","grammar:210:ex4:words:2:pos":"na-adjective","grammar:210:ex4:words:3:zh":"(polite form)","grammar:210:ex4:words:3:pos":"copula","grammar:210:ex4:points:0":"結婚生活: married life.","grammar:210:ex4:points:1":"大変: tough, not easy (na-adjective).","grammar:210:ex5:trans":"I'm preparing for the wedding.","grammar:210:ex5:structure":"〜の準備をしています","grammar:210:ex5:words:0:zh":"marriage","grammar:210:ex5:words:0:note":"けっこん","grammar:210:ex5:words:0:pos":"noun","grammar:210:ex5:words:1:zh":"'s","grammar:210:ex5:words:1:pos":"particle","grammar:210:ex5:words:2:zh":"prepare","grammar:210:ex5:words:2:note":"じゅんび","grammar:210:ex5:words:2:pos":"noun","grammar:210:ex5:words:3:zh":"(object marker)","grammar:210:ex5:words:3:pos":"particle","grammar:210:ex5:words:4:zh":"is doing","grammar:210:ex5:words:4:pos":"verb","grammar:210:ex5:points:0":"結婚の準備: wedding preparations.","grammar:210:ex5:points:1":"準備をする: to make preparations."},"211":{"example:211:exzh":"I drink tea.","example:211:exzh2":"I want to drink tea.","example:211:exzh3":"I like drinking beer.","example:211:exzh4":"I drink juice every morning.","example:211:exzh5":"Please take this medicine.","grammar:211:ex:trans":"I drink tea.","grammar:211:ex:structure":"〜を飲みます","grammar:211:ex:explain":"This is the most basic \"object + を + verb\" sentence. The 「お」 in 「お茶」 is a beautifying prefix that makes the word sound polite and soft. 「を」 marks what is being drunk. 「飲みます」 is the polite form of the godan verb 「飲む」: change 「飲む」 to its stem 「飲み」 and add 「ます」. The masu-form is polite and suits talking to outsiders or formal settings; in casual settings you can use the plain form 「飲む」. The whole sentence simply means \"drink tea\".","grammar:211:ex:words:0:zh":"tea","grammar:211:ex:words:0:note":"おちゃ","grammar:211:ex:words:0:pos":"noun","grammar:211:ex:words:1:zh":"(object marker)","grammar:211:ex:words:1:pos":"particle","grammar:211:ex:words:2:zh":"to drink","grammar:211:ex:words:2:note":"のみます","grammar:211:ex:words:2:pos":"verb","grammar:211:ex:points:0":"お茶を飲む: to drink tea.","grammar:211:ex:points:1":"飲む → 飲みます.","grammar:211:ex2:trans":"I want to drink tea.","grammar:211:ex2:structure":"〜を飲みたいです","grammar:211:ex2:words:0:zh":"tea","grammar:211:ex2:words:0:note":"おちゃ","grammar:211:ex2:words:0:pos":"noun","grammar:211:ex2:words:1:zh":"(object marker)","grammar:211:ex2:words:1:pos":"particle","grammar:211:ex2:words:2:zh":"want to drink","grammar:211:ex2:words:2:note":"のみたい","grammar:211:ex2:words:2:pos":"verb","grammar:211:ex2:words:3:zh":"(polite form)","grammar:211:ex2:words:3:pos":"copula","grammar:211:ex2:points:0":"飲む → 飲みたい (〜たい marks a wish).","grammar:211:ex2:points:1":"お茶を飲みたい: to want to drink tea.","grammar:211:ex3:trans":"I like drinking beer.","grammar:211:ex3:structure":"〜のが好きです","grammar:211:ex3:words:0:zh":"beer","grammar:211:ex3:words:0:note":"loanword","grammar:211:ex3:words:0:pos":"noun","grammar:211:ex3:words:1:zh":"(object marker)","grammar:211:ex3:words:1:pos":"particle","grammar:211:ex3:words:2:zh":"to drink","grammar:211:ex3:words:2:note":"のむ","grammar:211:ex3:words:2:pos":"verb","grammar:211:ex3:words:3:zh":"(nominalizer)","grammar:211:ex3:words:3:pos":"particle","grammar:211:ex3:words:4:zh":"(object)","grammar:211:ex3:words:4:pos":"particle","grammar:211:ex3:words:5:zh":"to like","grammar:211:ex3:words:5:note":"すき","grammar:211:ex3:words:5:pos":"na-adjective","grammar:211:ex3:words:6:zh":"(polite form)","grammar:211:ex3:words:6:pos":"copula","grammar:211:ex3:points:0":"〜のが好き: to like doing…","grammar:211:ex3:points:1":"ビールを飲む: to drink beer.","grammar:211:ex4:trans":"I drink juice every morning.","grammar:211:ex4:structure":"毎朝〜を飲みます","grammar:211:ex4:words:0:zh":"every morning","grammar:211:ex4:words:0:note":"まいあさ","grammar:211:ex4:words:0:pos":"adverb","grammar:211:ex4:words:1:zh":"juice","grammar:211:ex4:words:1:note":"loanword","grammar:211:ex4:words:1:pos":"noun","grammar:211:ex4:words:2:zh":"(object marker)","grammar:211:ex4:words:2:pos":"particle","grammar:211:ex4:words:3:zh":"to drink","grammar:211:ex4:words:3:note":"のみます","grammar:211:ex4:words:3:pos":"verb","grammar:211:ex4:points:0":"毎朝: every morning.","grammar:211:ex4:points:1":"ジュースを飲む: to drink juice.","grammar:211:ex5:trans":"Please take this medicine.","grammar:211:ex5:structure":"〜を飲んでください","grammar:211:ex5:words:0:zh":"this","grammar:211:ex5:words:0:pos":"pre-noun adjectival","grammar:211:ex5:words:1:zh":"medicine","grammar:211:ex5:words:1:note":"くすり","grammar:211:ex5:words:1:pos":"noun","grammar:211:ex5:words:2:zh":"(object marker)","grammar:211:ex5:words:2:pos":"particle","grammar:211:ex5:words:3:zh":"take (medicine)","grammar:211:ex5:words:3:note":"のんで","grammar:211:ex5:words:3:pos":"verb","grammar:211:ex5:words:4:zh":"please","grammar:211:ex5:words:4:pos":"auxiliary verb","grammar:211:ex5:points:0":"❗薬を飲む: to take medicine (in Japanese you use 飲む for medicine, not 食べる).","grammar:211:ex5:points:1":"飲む → 飲んで + ください.","exam:211:zh":"This glass of water tastes better if you drink it while it's still cold.","exam:211:why":"Getting water into your mouth is 「飲む」. 「食べる」 is for food and can't be used for drinking water."},"212":{"example:212:exzh":"There's a cat under the desk.","example:212:exzh2":"I'm going down to the floor below.","example:212:exzh3":"Please go down.","example:212:exzh4":"Please leave it down there.","example:212:exzh5":"I'll draw a small picture below.","grammar:212:ex:trans":"There's a cat under the desk.","grammar:212:ex:structure":"〜の下に〜がいます","grammar:212:ex:explain":"This is the existential sentence 「〜に〜がいます」. The location 「机の下」 takes 「に」 to mark where something exists, and 「猫が」 takes 「が」 to pick out what exists. The key is the difference between 「いる」 and 「ある」: living, moving things (people, animals) take 「いる／います」, while inanimate things take 「ある／あります」. A cat is an animal, so 「います」 is used. The 「の」 in 「机の下」 links 「机」 with the directional word 「下」, giving \"under the desk\".","grammar:212:ex:words:0:zh":"desk","grammar:212:ex:words:0:note":"つくえ","grammar:212:ex:words:0:pos":"noun","grammar:212:ex:words:1:zh":"'s","grammar:212:ex:words:1:pos":"particle","grammar:212:ex:words:2:zh":"under","grammar:212:ex:words:2:note":"した","grammar:212:ex:words:2:pos":"noun","grammar:212:ex:words:3:zh":"(location of existence)","grammar:212:ex:words:3:pos":"particle","grammar:212:ex:words:4:zh":"cat","grammar:212:ex:words:4:note":"ねこ","grammar:212:ex:words:4:pos":"noun","grammar:212:ex:words:5:zh":"(nominative)","grammar:212:ex:words:5:pos":"particle","grammar:212:ex:words:6:zh":"there is / are","grammar:212:ex:words:6:pos":"verb","grammar:212:ex:points:0":"机の下に: under the desk.","grammar:212:ex:points:1":"❓猫 → います (living thing).","grammar:212:ex2:trans":"I'm going downstairs.","grammar:212:ex2:structure":"〜の階に行きます","grammar:212:ex2:words:0:zh":"down","grammar:212:ex2:words:0:note":"した","grammar:212:ex2:words:0:pos":"noun","grammar:212:ex2:words:1:zh":"'s","grammar:212:ex2:words:1:pos":"particle","grammar:212:ex2:words:2:zh":"floor","grammar:212:ex2:words:2:note":"かい","grammar:212:ex2:words:2:pos":"noun","grammar:212:ex2:words:3:zh":"(destination)","grammar:212:ex2:words:3:pos":"particle","grammar:212:ex2:words:4:zh":"go","grammar:212:ex2:words:4:pos":"verb","grammar:212:ex2:points:0":"下の階: the floor below (下 + の + 階).","grammar:212:ex2:points:1":"に：destination of movement.","grammar:212:ex3:trans":"Please go down.","grammar:212:ex3:structure":"下に降りてください","grammar:212:ex3:words:0:zh":"down","grammar:212:ex3:words:0:note":"した","grammar:212:ex3:words:0:pos":"noun","grammar:212:ex3:words:1:zh":"(direction)","grammar:212:ex3:words:1:pos":"particle","grammar:212:ex3:words:2:zh":"go down","grammar:212:ex3:words:2:note":"おりて","grammar:212:ex3:words:2:pos":"verb","grammar:212:ex3:words:3:zh":"please","grammar:212:ex3:words:3:pos":"auxiliary verb","grammar:212:ex3:points:0":"下に降りる: to go down / to go downstairs.","grammar:212:ex3:points:1":"降りる → 降りて + ください.","grammar:212:ex4:trans":"Please put it down below.","grammar:212:ex4:structure":"〜に〜ておいてください","grammar:212:ex4:words:0:zh":"down","grammar:212:ex4:words:0:note":"した","grammar:212:ex4:words:0:pos":"noun","grammar:212:ex4:words:1:zh":"(the destination point)","grammar:212:ex4:words:1:pos":"particle","grammar:212:ex4:words:2:zh":"put","grammar:212:ex4:words:2:note":"おいて","grammar:212:ex4:words:2:pos":"verb","grammar:212:ex4:words:3:zh":"(leave it there)","grammar:212:ex4:words:3:pos":"auxiliary verb","grammar:212:ex4:words:4:zh":"please","grammar:212:ex4:words:4:pos":"auxiliary verb","grammar:212:ex4:points:0":"〜ておく: to do something in advance and leave it that way.","grammar:212:ex4:points:1":"置いておく: to put something in place (置く + ておく).","grammar:212:ex5:trans":"I'll draw a small picture at the bottom.","grammar:212:ex5:structure":"場所に小さな絵を描きます","grammar:212:ex5:explain":"「下に」 shows that the picture goes in the lower position, such as the bottom of a sheet of paper or a layout; to mark the place where the drawing activity happens, you would normally use 「で」. 「小さな」 modifies 「絵」 directly and means a small picture. 「絵を描く」 is the usual collocation for drawing a picture, and here 「描く」 is read 「かく」.","grammar:212:ex5:words:0:zh":"under","grammar:212:ex5:words:0:note":"した","grammar:212:ex5:words:0:pos":"noun","grammar:212:ex5:words:1:zh":"(the position where the drawing goes)","grammar:212:ex5:words:1:pos":"particle","grammar:212:ex5:words:2:zh":"small","grammar:212:ex5:words:2:note":"ちいさな","grammar:212:ex5:words:2:pos":"pre-noun adjectival","grammar:212:ex5:words:3:zh":"picture","grammar:212:ex5:words:3:note":"え","grammar:212:ex5:words:3:pos":"noun","grammar:212:ex5:words:4:zh":"(object)","grammar:212:ex5:words:4:pos":"particle","grammar:212:ex5:words:5:zh":"picture","grammar:212:ex5:words:5:note":"かき","grammar:212:ex5:words:5:pos":"verb","grammar:212:ex5:words:6:zh":"(polite tone)","grammar:212:ex5:words:6:pos":"auxiliary verb","grammar:212:ex5:points:0":"「小さな」 is a pre-noun adjectival: it modifies nouns directly and cannot stand alone as the predicate at the end of a sentence.","grammar:212:ex5:points:1":"The 「に」 in 「下に」 marks the position where the picture is to be drawn.","exam:212:zh":"The cat is under the table, looking this way from between the table legs.","exam:212:why":"The cat looks over from between the table legs, so it is 「下」 (under) the table. 「上」 means on top, which doesn't fit a position between the legs."},"213":{"example:213:exzh":"I'm trying a new method.","example:213:exzh2":"I think this method is good.","example:213:exzh3":"I'm looking for an efficient method.","example:213:exzh4":"Finding a way to solve this problem is difficult.","example:213:exzh5":"There are several methods.","grammar:213:ex:trans":"I'm trying a new method.","grammar:213:ex:structure":"〜を試しています","grammar:213:ex:explain":"「試す」 is a transitive verb meaning \"to try, to test\"; its object 「方法」 takes 「を」, and 「新しい」 is an i-adjective modifying it directly. The key point is 「〜ている」: attached after the te-form, it shows an action in progress, so 「試しています」 means \"am trying\". The te-form of 「試す」 is 「試して」, followed by 「います」 (the polite form). If you said 「試しました」, it would become \"tried\" — a completed past action. The whole sentence is \"am trying a new method\".","grammar:213:ex:words:0:zh":"new","grammar:213:ex:words:0:note":"あたらしい","grammar:213:ex:words:0:pos":"adjective","grammar:213:ex:words:1:zh":"way, method","grammar:213:ex:words:1:note":"ほうほう","grammar:213:ex:words:1:pos":"noun","grammar:213:ex:words:2:zh":"(object marker)","grammar:213:ex:words:2:pos":"particle","grammar:213:ex:words:3:zh":"trying","grammar:213:ex:words:3:note":"ためしています","grammar:213:ex:words:3:pos":"verb","grammar:213:ex:points:0":"方法を試す: to try a method.","grammar:213:ex:points:1":"〜ている: ongoing action.","grammar:213:ex2:trans":"I think this method is good.","grammar:213:ex2:structure":"〜は〜と思います","grammar:213:ex2:words:0:zh":"this","grammar:213:ex2:words:0:pos":"pre-noun adjectival","grammar:213:ex2:words:1:zh":"way, method","grammar:213:ex2:words:1:note":"ほうほう","grammar:213:ex2:words:1:pos":"noun","grammar:213:ex2:words:2:zh":"(topic)","grammar:213:ex2:words:2:pos":"particle","grammar:213:ex2:words:3:zh":"good","grammar:213:ex2:words:3:note":"いい","grammar:213:ex2:words:3:pos":"adjective","grammar:213:ex2:words:4:zh":"(quotation)","grammar:213:ex2:words:4:pos":"particle","grammar:213:ex2:words:5:zh":"think","grammar:213:ex2:words:5:note":"おもいます","grammar:213:ex2:words:5:pos":"verb","grammar:213:ex2:points:0":"〜と思います: I think … (quotation).","grammar:213:ex2:points:1":"良い (いい): good.","grammar:213:ex3:trans":"I'm looking for an efficient method.","grammar:213:ex3:structure":"〜な〜を探しています","grammar:213:ex3:words:0:zh":"efficient","grammar:213:ex3:words:0:note":"こうりつてき","grammar:213:ex3:words:0:pos":"na-adjective","grammar:213:ex3:words:1:zh":"(attributive form)","grammar:213:ex3:words:1:pos":"auxiliary verb","grammar:213:ex3:words:2:zh":"way, method","grammar:213:ex3:words:2:note":"ほうほう","grammar:213:ex3:words:2:pos":"noun","grammar:213:ex3:words:3:zh":"(object marker)","grammar:213:ex3:words:3:pos":"particle","grammar:213:ex3:words:4:zh":"am looking for","grammar:213:ex3:words:4:note":"さがしています","grammar:213:ex3:words:4:pos":"verb","grammar:213:ex3:points:0":"効率的な方法: an efficient method (na-adjective + な + noun).","grammar:213:ex3:points:1":"探す: to look for.","grammar:213:ex4:trans":"The solution to this problem is difficult.","grammar:213:ex4:structure":"〜の〜方法は〜です","grammar:213:ex4:words:0:zh":"this","grammar:213:ex4:words:0:pos":"pre-noun adjectival","grammar:213:ex4:words:1:zh":"problem","grammar:213:ex4:words:1:note":"もんだい","grammar:213:ex4:words:1:pos":"noun","grammar:213:ex4:words:2:zh":"'s","grammar:213:ex4:words:2:pos":"particle","grammar:213:ex4:words:3:zh":"solution","grammar:213:ex4:words:3:note":"かいけつほうほう","grammar:213:ex4:words:3:pos":"noun","grammar:213:ex4:words:4:zh":"(topic)","grammar:213:ex4:words:4:pos":"particle","grammar:213:ex4:words:5:zh":"difficult","grammar:213:ex4:words:5:note":"むずかしい","grammar:213:ex4:words:5:pos":"adjective","grammar:213:ex4:words:6:zh":"(polite form)","grammar:213:ex4:words:6:pos":"copula","grammar:213:ex4:points:0":"解決方法: solution.","grammar:213:ex4:points:1":"この問題の: of this problem.","grammar:213:ex5:trans":"There are several methods.","grammar:213:ex5:structure":"いくつかの〜があります","grammar:213:ex5:words:0:zh":"a few","grammar:213:ex5:words:0:pos":"noun","grammar:213:ex5:words:1:zh":"'s","grammar:213:ex5:words:1:pos":"particle","grammar:213:ex5:words:2:zh":"way, method","grammar:213:ex5:words:2:note":"ほうほう","grammar:213:ex5:words:2:pos":"noun","grammar:213:ex5:words:3:zh":"(nominative)","grammar:213:ex5:words:3:pos":"particle","grammar:213:ex5:words:4:zh":"there is / are","grammar:213:ex5:words:4:pos":"verb","grammar:213:ex5:points:0":"いくつかの: several.","grammar:213:ex5:points:1":"〜があります: there is / there are…"},"214":{"example:214:exzh":"I gained new knowledge.","example:214:exzh2":"I'll do my best to get good results.","example:214:exzh3":"I was able to gain a lot of experience.","example:214:exzh4":"Making money is hard.","example:214:exzh5":"He gained trust."},"215":{"example:215:exzh":"Let's have tea on the second floor.","example:215:exzh2":"I've been studying Japanese for two years.","example:215:exzh3":"The two of us will go.","example:215:exzh4":"It's the second time.","example:215:exzh5":"Please wait two hours.","grammar:215:ex:trans":"Let's have tea on the second floor.","grammar:215:ex:structure":"〜階で〜を飲みましょう","grammar:215:ex:explain":"「二」 is read 「に」 and is the most basic number \"two\". In this sentence, 「二階」 is 「二」 plus 「階」, which means floor, so it means the second floor. The counter that follows a number can change its reading: 「二つ（ふたつ）」, 「二人（ふたり）」, and 「二日（ふつか）」 are not read 「に」, so learn them separately. The sentence uses 「〜で〜を飲みましょう」 to mean \"let's drink something together somewhere\".","grammar:215:ex:words:0:zh":"two","grammar:215:ex:words:0:note":"に","grammar:215:ex:words:0:pos":"numeral","grammar:215:ex:words:1:zh":"floor (storey)","grammar:215:ex:words:1:note":"かい","grammar:215:ex:words:1:pos":"suffix","grammar:215:ex:words:2:zh":"at / in (place of action)","grammar:215:ex:words:2:pos":"particle","grammar:215:ex:words:3:zh":"tea","grammar:215:ex:words:3:note":"おちゃ","grammar:215:ex:words:3:pos":"noun","grammar:215:ex:words:4:zh":"(object marker)","grammar:215:ex:words:4:pos":"particle","grammar:215:ex:words:5:zh":"let's drink","grammar:215:ex:words:5:note":"のみましょう; the volitional form built on the masu-form of 飲む.","grammar:215:ex:words:5:pos":"verb","grammar:215:ex:points:0":"❗二階（にかい）: 「二」 is read 「に」, and with the floor counter 「階」 it means the second floor; the third floor is 「三階（さんがい）」, so watch out for rendaku (sequential voicing).","grammar:215:ex:points:1":"The 「で」 in 「二階で」 marks where the action takes place: drinking tea on the second floor.","grammar:215:ex:points:2":"「飲みましょう」 is 「飲みます」 changed to 「〜ましょう」, used to invite someone: \"let's … together\".","grammar:215:ex2:trans":"I've been studying Japanese for two years.","grammar:215:ex2:structure":"〜間〜ています","grammar:215:ex2:words:0:zh":"I","grammar:215:ex2:words:0:note":"わたし","grammar:215:ex2:words:0:pos":"pronoun","grammar:215:ex2:words:1:zh":"(topic)","grammar:215:ex2:words:1:pos":"particle","grammar:215:ex2:words:2:zh":"two years","grammar:215:ex2:words:2:note":"にねんかん","grammar:215:ex2:words:2:pos":"noun","grammar:215:ex2:words:3:zh":"Japanese","grammar:215:ex2:words:3:note":"にほんご","grammar:215:ex2:words:3:pos":"noun","grammar:215:ex2:words:4:zh":"(object marker)","grammar:215:ex2:words:4:pos":"particle","grammar:215:ex2:words:5:zh":"am studying","grammar:215:ex2:words:5:note":"べんきょうしています","grammar:215:ex2:words:5:pos":"verb","grammar:215:ex2:points:0":"二年間: two years (a duration: 年 + 間).","grammar:215:ex2:points:1":"〜ている: (continuing up to now).","grammar:215:ex3:trans":"We'll go, just the two of us.","grammar:215:ex3:structure":"二人で行きます","grammar:215:ex3:words:0:zh":"two people","grammar:215:ex3:words:0:note":"ふたり","grammar:215:ex3:words:0:pos":"noun","grammar:215:ex3:words:1:zh":"(the whole group)","grammar:215:ex3:words:1:pos":"particle","grammar:215:ex3:words:2:zh":"go","grammar:215:ex3:words:2:pos":"verb","grammar:215:ex3:points:0":"二人（ふたり）: two people.","grammar:215:ex3:points:1":"〜人で: (that many people) together (で marks the manner).","grammar:215:ex4:trans":"It's the second time.","grammar:215:ex4:structure":"〜回目です","grammar:215:ex4:words:0:zh":"the second time","grammar:215:ex4:words:0:note":"にかいめ","grammar:215:ex4:words:0:pos":"noun","grammar:215:ex4:words:1:zh":"is","grammar:215:ex4:words:1:pos":"copula","grammar:215:ex4:points:0":"〜回目: the …th time (回 + 目 forms an ordinal).","grammar:215:ex4:points:1":"二回目: the second time.","grammar:215:ex5:trans":"Please wait two hours.","grammar:215:ex5:structure":"〜時間〜てください","grammar:215:ex5:words:0:zh":"two hours","grammar:215:ex5:words:0:note":"にじかん","grammar:215:ex5:words:0:pos":"noun","grammar:215:ex5:words:1:zh":"wait","grammar:215:ex5:words:1:note":"まって","grammar:215:ex5:words:1:pos":"verb","grammar:215:ex5:words:2:zh":"please","grammar:215:ex5:words:2:pos":"auxiliary verb","grammar:215:ex5:points:0":"二時間: two hours (時間 means \"… hours\").","grammar:215:ex5:points:1":"待つ→待って＋ください。","exam:215:zh":"One plus one makes two.","exam:215:why":"One plus one equals two, so the answer is 「二」. 「三」 means three, which doesn't match the numbers in the sentence."},"216":{"example:216:exzh":"There's a reason for that.","example:216:exzh2":"There's a reason he can't come.","example:216:exzh3":"Please tell me the reason.","example:216:exzh4":"I want to know the reason.","example:216:exzh5":"A clear reason is needed."},"217":{"example:217:exzh":"He's my friend.","example:217:exzh2":"I'm going out to have fun with friends.","example:217:exzh3":"I want to make lots of friends.","example:217:exzh4":"I watched a movie with friends.","example:217:exzh5":"She's my best friend.","grammar:217:ex:trans":"He's my friend.","grammar:217:ex:structure":"〜は〜の友達です","grammar:217:ex:explain":"This is a noun-predicate sentence: 「〜は〜の友達です」. 「彼は」 uses 「は」 to set the topic (him), and the rest explains who he is. 「私の友達」 uses 「の」 to show belonging: \"my friend\". The sentence-final 「です」 is the polite copula, equivalent to \"is\". This is the most basic 「A は B です」 (A is B) pattern, used to introduce or explain who someone is. 「友達」 is the everyday word for \"friend\", and the whole sentence means \"he is my friend\".","grammar:217:ex:words:0:zh":"he","grammar:217:ex:words:0:note":"かれ","grammar:217:ex:words:0:pos":"pronoun","grammar:217:ex:words:1:zh":"(topic)","grammar:217:ex:words:1:pos":"particle","grammar:217:ex:words:2:zh":"I","grammar:217:ex:words:2:note":"わたし","grammar:217:ex:words:2:pos":"pronoun","grammar:217:ex:words:3:zh":"'s","grammar:217:ex:words:3:pos":"particle","grammar:217:ex:words:4:zh":"friend","grammar:217:ex:words:4:note":"ともだち","grammar:217:ex:words:4:pos":"noun","grammar:217:ex:words:5:zh":"is","grammar:217:ex:words:5:pos":"copula","grammar:217:ex:points:0":"私の友達: my friend.","grammar:217:ex:points:1":"noun predicate＋です.","grammar:217:ex2:trans":"I'm going out with friends.","grammar:217:ex2:structure":"〜と遊びに行きます","grammar:217:ex2:words:0:zh":"friend","grammar:217:ex2:words:0:note":"ともだち","grammar:217:ex2:words:0:pos":"noun","grammar:217:ex2:words:1:zh":"with","grammar:217:ex2:words:1:pos":"particle","grammar:217:ex2:words:2:zh":"hang out","grammar:217:ex2:words:2:note":"あそび","grammar:217:ex2:words:2:pos":"noun","grammar:217:ex2:words:3:zh":"(purpose)","grammar:217:ex2:words:3:pos":"particle","grammar:217:ex2:words:4:zh":"go","grammar:217:ex2:words:4:pos":"verb","grammar:217:ex2:points:0":"〜と遊びに行く: to go out and have fun with…","grammar:217:ex2:points:1":"と marks the person you go with.","grammar:217:ex3:trans":"I want to make a lot of friends.","grammar:217:ex3:structure":"〜を作りたいです","grammar:217:ex3:words:0:zh":"a lot","grammar:217:ex3:words:0:note":"おおく","grammar:217:ex3:words:0:pos":"noun","grammar:217:ex3:words:1:zh":"'s","grammar:217:ex3:words:1:pos":"particle","grammar:217:ex3:words:2:zh":"friend","grammar:217:ex3:words:2:note":"ともだち","grammar:217:ex3:words:2:pos":"noun","grammar:217:ex3:words:3:zh":"(object marker)","grammar:217:ex3:words:3:pos":"particle","grammar:217:ex3:words:4:zh":"want to make","grammar:217:ex3:words:4:note":"つくりたい","grammar:217:ex3:words:4:pos":"verb","grammar:217:ex3:words:5:zh":"(polite form)","grammar:217:ex3:words:5:pos":"copula","grammar:217:ex3:points:0":"「友達を作る」: to make friends.","grammar:217:ex3:points:1":"作る → 作りたい (〜たい).","grammar:217:ex4:trans":"I watched a movie with a friend.","grammar:217:ex4:structure":"〜と〜を見ました","grammar:217:ex4:words:0:zh":"friend","grammar:217:ex4:words:0:note":"ともだち","grammar:217:ex4:words:0:pos":"noun","grammar:217:ex4:words:1:zh":"with","grammar:217:ex4:words:1:pos":"particle","grammar:217:ex4:words:2:zh":"movie","grammar:217:ex4:words:2:note":"えいが","grammar:217:ex4:words:2:pos":"noun","grammar:217:ex4:words:3:zh":"(object marker)","grammar:217:ex4:words:3:pos":"particle","grammar:217:ex4:words:4:zh":"watched","grammar:217:ex4:words:4:note":"みました","grammar:217:ex4:words:4:pos":"verb","grammar:217:ex4:points:0":"〜と〜を見る: to watch … with …","grammar:217:ex4:points:1":"見る→見ました (past).","grammar:217:ex5:trans":"She's my best friend.","grammar:217:ex5:structure":"〜は一番の友達です","grammar:217:ex5:words:0:zh":"she","grammar:217:ex5:words:0:note":"かのじょ","grammar:217:ex5:words:0:pos":"pronoun","grammar:217:ex5:words:1:zh":"(topic)","grammar:217:ex5:words:1:pos":"particle","grammar:217:ex5:words:2:zh":"I","grammar:217:ex5:words:2:note":"わたし","grammar:217:ex5:words:2:pos":"pronoun","grammar:217:ex5:words:3:zh":"'s","grammar:217:ex5:words:3:pos":"particle","grammar:217:ex5:words:4:zh":"the most","grammar:217:ex5:words:4:note":"いちばん","grammar:217:ex5:words:4:pos":"noun","grammar:217:ex5:words:5:zh":"'s","grammar:217:ex5:words:5:pos":"particle","grammar:217:ex5:words:6:zh":"friend","grammar:217:ex5:words:6:note":"ともだち","grammar:217:ex5:words:6:pos":"noun","grammar:217:ex5:words:7:zh":"is","grammar:217:ex5:words:7:pos":"copula","grammar:217:ex5:points:0":"一番の友達: best friend (一番 + の).","grammar:217:ex5:points:1":"私の一番の友達: my best friend.","exam:217:zh":"Ken and I aren't family — we're friends who often play together.","exam:217:why":"Not being family yet often playing together fits 「友達」. 「兄弟」 means siblings, which is family."},"218":{"example:218:exzh":"Is that possible?","example:218:exzh2":"I think there's a possibility.","example:218:exzh3":"Not everything is possible.","example:218:exzh4":"Let's talk about the potential of new technology.","example:218:exzh5":"With that, a lot of things become possible."},"219":{"example:219:exzh":"I can hear music.","example:219:exzh2":"I can't hear his voice.","example:219:exzh3":"Can you hear the birds from here?","example:219:exzh4":"I can hear the birds chirping.","example:219:exzh5":"Don't worry, it comes through clearly.","grammar:219:ex:trans":"I can hear music.","grammar:219:ex:structure":"〜が聞こえます","grammar:219:ex:explain":"「聞こえる」 is an intransitive verb meaning that a sound \"reaches your ears naturally, is audible,\" emphasizing that it is not deliberate but happens on its own; the thing heard is marked with 「が」. This differs from the transitive 「聞く」 (to listen actively): 「音楽を聞く」 is listening to music yourself, while 「音楽が聞こえる」 is music coming to you and being audible. So this sentence means \"(naturally) I can hear music.\" The similar 「見える」 (to be visible) is also this kind of spontaneous sensory intransitive verb.","grammar:219:ex:words:0:zh":"music","grammar:219:ex:words:0:note":"おんがく","grammar:219:ex:words:0:pos":"noun","grammar:219:ex:words:1:zh":"(nominative)","grammar:219:ex:words:1:pos":"particle","grammar:219:ex:words:2:zh":"can hear","grammar:219:ex:words:2:note":"きこえます","grammar:219:ex:words:2:pos":"verb","grammar:219:ex:points:0":"❗聞こえる: (naturally) audible (intransitive verb, takes が).","grammar:219:ex:points:1":"音楽が聞こえる: to hear music.","grammar:219:ex2:trans":"I can't hear his voice.","grammar:219:ex2:structure":"〜が聞こえない","grammar:219:ex2:words:0:zh":"he","grammar:219:ex2:words:0:note":"かれ","grammar:219:ex2:words:0:pos":"pronoun","grammar:219:ex2:words:1:zh":"'s","grammar:219:ex2:words:1:pos":"particle","grammar:219:ex2:words:2:zh":"voice","grammar:219:ex2:words:2:note":"こえ","grammar:219:ex2:words:2:pos":"noun","grammar:219:ex2:words:3:zh":"(nominative)","grammar:219:ex2:words:3:pos":"particle","grammar:219:ex2:words:4:zh":"can't hear","grammar:219:ex2:words:4:note":"きこえない","grammar:219:ex2:words:4:pos":"verb","grammar:219:ex2:points:0":"聞こえない: can't hear.","grammar:219:ex2:points:1":"彼の声: his voice.","grammar:219:ex3:trans":"Can you hear birds singing from here?","grammar:219:ex3:structure":"〜から、〜が聞こえますか","grammar:219:ex3:explain":"「ここから」 specifies the listening location, meaning \"from here.\" 「鳥の声」 links two nouns with 「の」, meaning the birds' calls. 「声が聞こえる」 marks the audible sound with 「が」. 「聞こえる」 focuses on sound reaching your ears naturally, which differs from 「聞ける」, which means being able to listen (ability or conditions). The sentence-final 「ますか」 makes the whole sentence a polite question.","grammar:219:ex3:words:0:zh":"here","grammar:219:ex3:words:0:pos":"pronoun","grammar:219:ex3:words:1:zh":"(the starting point of listening)","grammar:219:ex3:words:1:pos":"particle","grammar:219:ex3:words:2:zh":"bird","grammar:219:ex3:words:2:note":"とり","grammar:219:ex3:words:2:pos":"noun","grammar:219:ex3:words:3:zh":"(links nouns, showing the source of the sound)","grammar:219:ex3:words:3:pos":"particle","grammar:219:ex3:words:4:zh":"cries","grammar:219:ex3:words:4:note":"こえ","grammar:219:ex3:words:4:pos":"noun","grammar:219:ex3:words:5:zh":"(nominative)","grammar:219:ex3:words:5:pos":"particle","grammar:219:ex3:words:6:zh":"can be heard","grammar:219:ex3:words:6:note":"きこえ","grammar:219:ex3:words:6:pos":"verb","grammar:219:ex3:words:7:zh":"(polite ending)","grammar:219:ex3:words:7:pos":"auxiliary verb","grammar:219:ex3:words:8:zh":"(question)","grammar:219:ex3:words:8:pos":"particle","grammar:219:ex3:points:0":"「聞こえる」 means sound can reach your ears; the sound heard is usually marked with 「が」.","grammar:219:ex3:points:1":"「ここから」 means listening from this position; it doesn't mean the bird calls come from here.","grammar:219:ex3:points:2":"「ますか」 is the polite question ending.","grammar:219:ex4:trans":"I hear birds chirping.","grammar:219:ex4:structure":"〜が聞こえる","grammar:219:ex4:words:0:zh":"bird","grammar:219:ex4:words:0:note":"とり","grammar:219:ex4:words:0:pos":"noun","grammar:219:ex4:words:1:zh":"'s","grammar:219:ex4:words:1:pos":"particle","grammar:219:ex4:words:2:zh":"chirping","grammar:219:ex4:words:2:pos":"noun","grammar:219:ex4:words:3:zh":"(nominative)","grammar:219:ex4:words:3:pos":"particle","grammar:219:ex4:words:4:zh":"can hear","grammar:219:ex4:words:4:note":"きこえる","grammar:219:ex4:words:4:pos":"verb","grammar:219:ex4:points:0":"❗さえずり: (bird) chirping, song.","grammar:219:ex4:points:1":"鳥のさえずりが聞こえる: to hear birds chirping.","grammar:219:ex5:trans":"Don't worry, I can hear you clearly.","grammar:219:ex5:structure":"よく聞こえてます","grammar:219:ex5:words:0:zh":"don't worry","grammar:219:ex5:words:0:note":"しんぱいしないで","grammar:219:ex5:words:0:pos":"verb","grammar:219:ex5:words:1:zh":"clearly","grammar:219:ex5:words:1:pos":"adverb","grammar:219:ex5:words:2:zh":"can hear","grammar:219:ex5:words:2:note":"きこえてます","grammar:219:ex5:words:2:pos":"verb","grammar:219:ex5:points:0":"よく聞こえる: to hear clearly.","grammar:219:ex5:points:1":"心配しないで: don't worry."},"220":{"example:220:exzh":"The stars are beautiful at night.","example:220:exzh2":"I woke up in the middle of the night.","example:220:exzh3":"Lately the nights have gotten long.","example:220:exzh4":"Let's go have dinner.","example:220:exzh5":"The night has become quiet.","grammar:220:ex:trans":"The stars are beautiful at night.","grammar:220:ex:structure":"〜は〜がきれいです","grammar:220:ex:explain":"This is a typical double-subject sentence: a big topic plus a smaller subject. 「夜は」 uses 「は」 to set the broad topic (as for night), and 「星が」 uses 「が」 to pick out what is actually being described (the stars). 「きれい」 is a na-adjective meaning pretty or clean, and with 「です」 it serves as the polite predicate. The whole sentence is \"at night, the stars are beautiful\". The 「〜は〜が + adjective」 shape is very common in Japanese: first frame the topic, then bring in the focus.","grammar:220:ex:words:0:zh":"night","grammar:220:ex:words:0:note":"よる","grammar:220:ex:words:0:pos":"noun","grammar:220:ex:words:1:zh":"(topic)","grammar:220:ex:words:1:pos":"particle","grammar:220:ex:words:2:zh":"star","grammar:220:ex:words:2:note":"ほし","grammar:220:ex:words:2:pos":"noun","grammar:220:ex:words:3:zh":"(nominative)","grammar:220:ex:words:3:pos":"particle","grammar:220:ex:words:4:zh":"beautiful","grammar:220:ex:words:4:pos":"na-adjective","grammar:220:ex:words:5:zh":"(polite form)","grammar:220:ex:words:5:pos":"copula","grammar:220:ex:points:0":"夜は: night (the topic).","grammar:220:ex:points:1":"星がきれい: the stars are beautiful (the subject takes が).","grammar:220:ex2:trans":"I woke up in the middle of the night.","grammar:220:ex2:structure":"〜に起きました","grammar:220:ex2:words:0:zh":"the middle of the night","grammar:220:ex2:words:0:note":"よなか","grammar:220:ex2:words:0:pos":"noun","grammar:220:ex2:words:1:zh":"(point in time)","grammar:220:ex2:words:1:pos":"particle","grammar:220:ex2:words:2:zh":"woke up","grammar:220:ex2:words:2:note":"おきました","grammar:220:ex2:words:2:pos":"verb","grammar:220:ex2:points:0":"夜中（よなか）: the middle of the night, late at night.","grammar:220:ex2:points:1":"起きる → 起きました (past).","grammar:220:ex3:trans":"Lately the nights have gotten longer.","grammar:220:ex3:structure":"〜が長いです","grammar:220:ex3:words:0:zh":"lately","grammar:220:ex3:words:0:note":"さいきん","grammar:220:ex3:words:0:pos":"adverb","grammar:220:ex3:words:1:zh":"night","grammar:220:ex3:words:1:note":"よる","grammar:220:ex3:words:1:pos":"noun","grammar:220:ex3:words:2:zh":"(nominative)","grammar:220:ex3:words:2:pos":"particle","grammar:220:ex3:words:3:zh":"long","grammar:220:ex3:words:3:note":"ながい","grammar:220:ex3:words:3:pos":"adjective","grammar:220:ex3:words:4:zh":"(polite form)","grammar:220:ex3:words:4:pos":"copula","grammar:220:ex3:points:0":"「最近」: recently.","grammar:220:ex3:points:1":"「夜が長い」: the nights are long (the subject takes が).","grammar:220:ex4:trans":"Let's go eat dinner.","grammar:220:ex4:structure":"〜を食べに行きましょう","grammar:220:ex4:words:0:zh":"dinner","grammar:220:ex4:words:0:note":"よるごはん","grammar:220:ex4:words:0:pos":"noun","grammar:220:ex4:words:1:zh":"(object marker)","grammar:220:ex4:words:1:pos":"particle","grammar:220:ex4:words:2:zh":"eat","grammar:220:ex4:words:2:note":"たべ","grammar:220:ex4:words:2:pos":"noun","grammar:220:ex4:words:3:zh":"(purpose)","grammar:220:ex4:words:3:pos":"particle","grammar:220:ex4:words:4:zh":"let's go","grammar:220:ex4:words:4:pos":"verb","grammar:220:ex4:points:0":"「夜ご飯」: dinner.","grammar:220:ex4:points:1":"「〜に行く」: go to do … (「食べに行く」 = go eat).","grammar:220:ex5:trans":"The night became quiet.","grammar:220:ex5:structure":"〜は〜になりました","grammar:220:ex5:words:0:zh":"night","grammar:220:ex5:words:0:note":"よる","grammar:220:ex5:words:0:pos":"noun","grammar:220:ex5:words:1:zh":"(topic)","grammar:220:ex5:words:1:pos":"particle","grammar:220:ex5:words:2:zh":"quiet","grammar:220:ex5:words:2:note":"しずか","grammar:220:ex5:words:2:pos":"na-adjective","grammar:220:ex5:words:3:zh":"(result)","grammar:220:ex5:words:3:pos":"particle","grammar:220:ex5:words:4:zh":"become","grammar:220:ex5:words:4:pos":"verb","grammar:220:ex5:points:0":"「静かになる」: become quiet (na-adjective + に + なる).","grammar:220:ex5:points:1":"なる→なりました (past).","exam:220:zh":"I was busy yesterday, and I finally ate dinner at eleven at night.","exam:220:why":"Eleven at night falls under 「夜」. 「夕方」 means early evening, so it doesn't fit eleven at night."},"221":{"example:221:exzh":"I hung out with a friend.","example:221:exzh2":"He's my friend.","example:221:exzh3":"I'm going to see a friend.","example:221:exzh4":"A friend helped me.","example:221:exzh5":"She's a good friend."},"222":{"example:222:exzh":"The culprit hasn't been caught yet.","example:222:exzh2":"The police are chasing the culprit.","example:222:exzh3":"Who is the culprit in that case?","example:222:exzh4":"The culprit was arrested.","example:222:exzh5":"The culprit's motive is unknown."},"223":{"example:223:exzh":"Safety is very important.","example:223:exzh2":"Personality differs from person to person.","example:223:exzh3":"There are issues related to sex.","example:223:exzh4":"Her sex is female.","example:223:exzh5":"An understanding of sex is needed."},"225":{"example:225:exzh":"I'm making a plan for a trip.","example:225:exzh2":"The plan is going smoothly.","example:225:exzh3":"She changed the plan.","example:225:exzh4":"Let's check the work plan.","example:225:exzh5":"I'll propose a new plan."},"226":{"example:226:exzh":"That's impossible.","example:226:exzh2":"Please don't push yourself too hard.","example:226:exzh3":"He was forcing a smile.","example:226:exzh4":"Don't make unreasonable demands.","example:226:exzh5":"It's impossible to finish in such a short time.","grammar:226:ex:trans":"That's impossible.","grammar:226:ex:structure":"〜は無理です","grammar:226:ex:explain":"「無理（むり）」 is a na-adjective meaning impossible, can't be done, or too much to handle, and it takes 「です」 directly as a predicate. 「それは」 uses 「は」 to present the topic. This is a very common way to turn something down or say you can't do it, and it sounds more decisive than 「できません」. To say something is possible, use 「可能です」. Note that 「無理をする」 means to push yourself too hard, which is a different usage. The whole sentence means that's impossible.","grammar:226:ex:words:0:zh":"that","grammar:226:ex:words:0:pos":"pronoun","grammar:226:ex:words:1:zh":"(topic)","grammar:226:ex:words:1:pos":"particle","grammar:226:ex:words:2:zh":"impossible","grammar:226:ex:words:2:note":"むり","grammar:226:ex:words:2:pos":"na-adjective","grammar:226:ex:words:3:zh":"(polite form)","grammar:226:ex:words:3:pos":"copula","grammar:226:ex:points:0":"「無理」: impossible, can't be done (na-adjective).","grammar:226:ex:points:1":"「それは無理です」: that can't be done.","grammar:226:ex2:trans":"Please don't push yourself.","grammar:226:ex2:structure":"〜をしないでください","grammar:226:ex2:words:0:zh":"pushing yourself too hard","grammar:226:ex2:words:0:note":"むり","grammar:226:ex2:words:0:pos":"noun","grammar:226:ex2:words:1:zh":"(object marker)","grammar:226:ex2:words:1:pos":"particle","grammar:226:ex2:words:2:zh":"don't do (it)","grammar:226:ex2:words:2:pos":"verb","grammar:226:ex2:words:3:zh":"please","grammar:226:ex2:words:3:pos":"auxiliary verb","grammar:226:ex2:points:0":"「無理をする」: push yourself too hard, force yourself (idiomatic).","grammar:226:ex2:points:1":"「〜ないでください」: please don't …","grammar:226:ex3:trans":"He was smiling with effort.","grammar:226:ex3:structure":"無理に〜ていた","grammar:226:ex3:words:0:zh":"he","grammar:226:ex3:words:0:note":"かれ","grammar:226:ex3:words:0:pos":"pronoun","grammar:226:ex3:words:1:zh":"(topic)","grammar:226:ex3:words:1:pos":"particle","grammar:226:ex3:words:2:zh":"with effort","grammar:226:ex3:words:2:note":"むりに","grammar:226:ex3:words:2:pos":"adverb","grammar:226:ex3:words:3:zh":"was smiling","grammar:226:ex3:words:3:note":"わらっていた","grammar:226:ex3:words:3:pos":"verb","grammar:226:ex3:points:0":"「無理に」: forcibly, with effort (adverb).","grammar:226:ex3:points:1":"「〜ていた」: was …ing (past).","grammar:226:ex4:trans":"Please don't make unreasonable demands.","grammar:226:ex4:structure":"〜な〜はしないように","grammar:226:ex4:words:0:zh":"unreasonable","grammar:226:ex4:words:0:note":"むり","grammar:226:ex4:words:0:pos":"na-adjective","grammar:226:ex4:words:1:zh":"(attributive form)","grammar:226:ex4:words:1:pos":"auxiliary verb","grammar:226:ex4:words:2:zh":"demand","grammar:226:ex4:words:2:note":"ようきゅう","grammar:226:ex4:words:2:pos":"noun","grammar:226:ex4:words:3:zh":"(contrast)","grammar:226:ex4:words:3:pos":"particle","grammar:226:ex4:words:4:zh":"don't do (it)","grammar:226:ex4:words:4:pos":"verb","grammar:226:ex4:points:0":"「無理な要求」: an unreasonable demand (na-adjective + noun).","grammar:226:ex4:points:1":"「〜ないように」: don't … (a reminder)","grammar:226:ex5:trans":"Finishing in such a short time is impossible.","grammar:226:ex5:structure":"〜のは無理だ","grammar:226:ex5:words:0:zh":"such a","grammar:226:ex5:words:0:pos":"pre-noun adjectival","grammar:226:ex5:words:1:zh":"short time","grammar:226:ex5:words:1:note":"たんじかん","grammar:226:ex5:words:1:pos":"noun","grammar:226:ex5:words:2:zh":"(scope)","grammar:226:ex5:words:2:pos":"particle","grammar:226:ex5:words:3:zh":"to finish (something)","grammar:226:ex5:words:3:note":"おわらせる","grammar:226:ex5:words:3:pos":"verb","grammar:226:ex5:words:4:zh":"(nominalizer)","grammar:226:ex5:words:4:pos":"particle","grammar:226:ex5:words:5:zh":"(topic)","grammar:226:ex5:words:5:pos":"particle","grammar:226:ex5:words:6:zh":"impossible","grammar:226:ex5:words:6:note":"むり","grammar:226:ex5:words:6:pos":"na-adjective","grammar:226:ex5:words:7:zh":"is (plain form)","grammar:226:ex5:words:7:pos":"copula","grammar:226:ex5:points:0":"「終わらせる」: bring … to an end (causative/transitive of 「終わる」).","grammar:226:ex5:points:1":"「〜のは無理だ」: doing … is impossible."},"227":{"example:227:exzh":"Today is a lot of fun.","example:227:exzh2":"Hanging out with him is fun.","example:227:exzh3":"I had a really good time.","example:227:exzh4":"Let's make happy memories together.","example:227:exzh5":"It was a fun trip.","grammar:227:ex:trans":"Today is a lot of fun.","grammar:227:ex:structure":"〜はとても〜です","grammar:227:ex:explain":"「楽しい」 is an i-adjective meaning fun or enjoyable, describing the pleasure you feel while doing something. 「今日は」 uses 「は」 to present the topic (today), and 「とても」 is the adverb very, modifying the adjective that follows. When an i-adjective is a polite predicate, you simply add 「です」 after 「楽しい」, unlike na-adjectives or nouns, which need a copula. The whole sentence means today is a lot of fun. Note that 「楽しい」 is about your own enjoyment, slightly different in feel from 「面白い」 (interesting).","grammar:227:ex:words:0:zh":"today","grammar:227:ex:words:0:note":"きょう","grammar:227:ex:words:0:pos":"noun","grammar:227:ex:words:1:zh":"(topic)","grammar:227:ex:words:1:pos":"particle","grammar:227:ex:words:2:zh":"extremely","grammar:227:ex:words:2:pos":"adverb","grammar:227:ex:words:3:zh":"fun","grammar:227:ex:words:3:note":"たのしい","grammar:227:ex:words:3:pos":"adjective","grammar:227:ex:words:4:zh":"(polite form)","grammar:227:ex:words:4:pos":"copula","grammar:227:ex:points:0":"「楽しい」: fun, enjoyable (i-adjective).","grammar:227:ex:points:1":"「とても」: very.","grammar:227:ex2:trans":"Playing with him is fun.","grammar:227:ex2:structure":"〜のは楽しい","grammar:227:ex2:words:0:zh":"he","grammar:227:ex2:words:0:note":"かれ","grammar:227:ex2:words:0:pos":"pronoun","grammar:227:ex2:words:1:zh":"with","grammar:227:ex2:words:1:pos":"particle","grammar:227:ex2:words:2:zh":"hang out","grammar:227:ex2:words:2:note":"あそぶ","grammar:227:ex2:words:2:pos":"verb","grammar:227:ex2:words:3:zh":"(nominalizer)","grammar:227:ex2:words:3:pos":"particle","grammar:227:ex2:words:4:zh":"(topic)","grammar:227:ex2:words:4:pos":"particle","grammar:227:ex2:words:5:zh":"fun","grammar:227:ex2:words:5:note":"たのしい","grammar:227:ex2:words:5:pos":"adjective","grammar:227:ex2:points:0":"「〜のは楽しい」: doing … is fun (「の」 nominalizes the phrase).","grammar:227:ex2:points:1":"「彼と遊ぶ」: play with him.","grammar:227:ex3:trans":"I had a fun time.","grammar:227:ex3:structure":"〜を過ごしました","grammar:227:ex3:words:0:zh":"fun","grammar:227:ex3:words:0:note":"たのしい","grammar:227:ex3:words:0:pos":"adjective","grammar:227:ex3:words:1:zh":"time","grammar:227:ex3:words:1:note":"じかん","grammar:227:ex3:words:1:pos":"noun","grammar:227:ex3:words:2:zh":"(object marker)","grammar:227:ex3:words:2:pos":"particle","grammar:227:ex3:words:3:zh":"spent","grammar:227:ex3:words:3:note":"すごしました","grammar:227:ex3:words:3:pos":"verb","grammar:227:ex3:points:0":"「時間を過ごす」: spend time.","grammar:227:ex3:points:1":"過ごす→過ごしました。","grammar:227:ex4:trans":"Let's make fun memories together.","grammar:227:ex4:structure":"〜を作りましょう","grammar:227:ex4:words:0:zh":"fun","grammar:227:ex4:words:0:note":"たのしい","grammar:227:ex4:words:0:pos":"adjective","grammar:227:ex4:words:1:zh":"memories","grammar:227:ex4:words:1:note":"おもいで","grammar:227:ex4:words:1:pos":"noun","grammar:227:ex4:words:2:zh":"(object marker)","grammar:227:ex4:words:2:pos":"particle","grammar:227:ex4:words:3:zh":"let's make","grammar:227:ex4:words:3:note":"つくりましょう","grammar:227:ex4:words:3:pos":"verb","grammar:227:ex4:points:0":"「思い出を作る」: make memories.","grammar:227:ex4:points:1":"作る→作りましょう (a suggestion)","grammar:227:ex5:trans":"It was a fun trip.","grammar:227:ex5:structure":"〜でした","grammar:227:ex5:words:0:zh":"fun","grammar:227:ex5:words:0:note":"たのしい","grammar:227:ex5:words:0:pos":"adjective","grammar:227:ex5:words:1:zh":"travel / trip","grammar:227:ex5:words:1:note":"りょこう","grammar:227:ex5:words:1:pos":"noun","grammar:227:ex5:words:2:zh":"(past) was","grammar:227:ex5:words:2:pos":"copula","grammar:227:ex5:points:0":"「楽しい旅行」: a fun trip (i-adjective + noun).","grammar:227:ex5:points:1":"「でした」: was (past).","exam:227:zh":"We all played together laughing, and had a really happy time.","exam:227:why":"Everyone laughing and playing together matches the happy feeling of 「楽しい」. 「つまらない」 means boring, which doesn't fit here."},"228":{"example:228:exzh":"She has a gentle face.","example:228:exzh2":"Your face is red, isn't it?","example:228:exzh3":"A smiling face is lovely.","example:228:exzh4":"His face stays in memory.","example:228:exzh5":"I'm going to wash my face.","grammar:228:ex:trans":"She has a gentle face.","grammar:228:ex:structure":"〜顔をしている","grammar:228:ex:explain":"This is the idiomatic expression 「〜顔をしている」: literally to be making a … face, it actually means to have a … expression, to have a … face. 「優しい顔」 is a gentle expression, marked with 「を」, and the verb 「する」 in its 「〜ている」 form shows an ongoing state. So 「優しい顔をしている」 means having a kind face, looking gentle. This 「〜をしている」 can also describe appearance, as in 「青い目をしている」 (having blue eyes).","grammar:228:ex:words:0:zh":"she","grammar:228:ex:words:0:note":"かのじょ","grammar:228:ex:words:0:pos":"pronoun","grammar:228:ex:words:1:zh":"(topic)","grammar:228:ex:words:1:pos":"particle","grammar:228:ex:words:2:zh":"gentle","grammar:228:ex:words:2:note":"やさしい","grammar:228:ex:words:2:pos":"adjective","grammar:228:ex:words:3:zh":"face","grammar:228:ex:words:3:note":"かお","grammar:228:ex:words:3:pos":"noun","grammar:228:ex:words:4:zh":"(object marker)","grammar:228:ex:words:4:pos":"particle","grammar:228:ex:words:5:zh":"(showing)","grammar:228:ex:words:5:pos":"verb","grammar:228:ex:points:0":"「〜顔をしている」: have a … expression (idiomatic).","grammar:228:ex:points:1":"「優しい顔」: a gentle face.","grammar:228:ex2:trans":"Your face is red, isn't it?","grammar:228:ex2:structure":"顔が〜ですね","grammar:228:ex2:words:0:zh":"face","grammar:228:ex2:words:0:note":"かお","grammar:228:ex2:words:0:pos":"noun","grammar:228:ex2:words:1:zh":"(nominative)","grammar:228:ex2:words:1:pos":"particle","grammar:228:ex2:words:2:zh":"red","grammar:228:ex2:words:2:note":"あかい","grammar:228:ex2:words:2:pos":"adjective","grammar:228:ex2:words:3:zh":"(polite form)","grammar:228:ex2:words:3:pos":"copula","grammar:228:ex2:words:4:zh":"right?","grammar:228:ex2:words:4:pos":"particle","grammar:228:ex2:points:0":"「顔が赤い」: the face is red (the subject takes が).","grammar:228:ex2:points:1":"「赤い」: red (i-adjective).","grammar:228:ex3:trans":"A smiling face is lovely.","grammar:228:ex3:structure":"［笑っている］顔が素敵です","grammar:228:ex3:explain":"「笑っている」 shows the state of smiling, and the whole phrase comes before 「顔」 to form a smiling face. 「が」 marks the subject that is described as lovely. 「素敵」 is a na-adjective that can take 「です」 at the end of a sentence; before a noun you say 「素敵な顔」.","grammar:228:ex3:words:0:zh":"smile","grammar:228:ex3:words:0:note":"わらっ","grammar:228:ex3:words:0:pos":"verb","grammar:228:ex3:words:1:zh":"(links to the verb that follows)","grammar:228:ex3:words:1:pos":"particle","grammar:228:ex3:words:2:zh":"(the action is ongoing)","grammar:228:ex3:words:2:pos":"verb","grammar:228:ex3:words:3:zh":"face","grammar:228:ex3:words:3:note":"かお","grammar:228:ex3:words:3:pos":"noun","grammar:228:ex3:words:4:zh":"(nominative)","grammar:228:ex3:words:4:pos":"particle","grammar:228:ex3:words:5:zh":"lovely, charming","grammar:228:ex3:words:5:note":"すてき","grammar:228:ex3:words:5:pos":"na-adjective","grammar:228:ex3:words:6:zh":"(polite statement)","grammar:228:ex3:words:6:pos":"auxiliary verb","grammar:228:ex3:points:0":"The te-form of 「笑う」 is 「笑って」, and with 「いる」 it means is smiling.","grammar:228:ex3:points:1":"「笑っている」 modifies 「顔」 directly, with no 「の」 in between.","grammar:228:ex4:trans":"His face is hard to forget.","grammar:228:ex4:structure":"〜に残ります","grammar:228:ex4:words:0:zh":"he","grammar:228:ex4:words:0:note":"かれ","grammar:228:ex4:words:0:pos":"pronoun","grammar:228:ex4:words:1:zh":"'s","grammar:228:ex4:words:1:pos":"particle","grammar:228:ex4:words:2:zh":"face","grammar:228:ex4:words:2:note":"かお","grammar:228:ex4:words:2:pos":"noun","grammar:228:ex4:words:3:zh":"(topic)","grammar:228:ex4:words:3:pos":"particle","grammar:228:ex4:words:4:zh":"memory","grammar:228:ex4:words:4:note":"きおく","grammar:228:ex4:words:4:pos":"noun","grammar:228:ex4:words:5:zh":"(the destination point)","grammar:228:ex4:words:5:pos":"particle","grammar:228:ex4:words:6:zh":"remain","grammar:228:ex4:words:6:note":"のこります","grammar:228:ex4:words:6:pos":"verb","grammar:228:ex4:points:0":"「記憶に残る」: stay in one's memory, be unforgettable (idiomatic).","grammar:228:ex4:points:1":"「残る」: remain (intransitive verb).","grammar:228:ex5:trans":"I'll go wash my face.","grammar:228:ex5:structure":"〜てきます","grammar:228:ex5:words:0:zh":"face","grammar:228:ex5:words:0:note":"かお","grammar:228:ex5:words:0:pos":"noun","grammar:228:ex5:words:1:zh":"(object marker)","grammar:228:ex5:words:1:pos":"particle","grammar:228:ex5:words:2:zh":"wash","grammar:228:ex5:words:2:note":"あらって","grammar:228:ex5:words:2:pos":"verb","grammar:228:ex5:words:3:zh":"(go do it and come back)","grammar:228:ex5:words:3:pos":"auxiliary verb","grammar:228:ex5:points:0":"「〜てくる」: go (do) … and come back (「洗ってくる」 = go wash one's face).","grammar:228:ex5:points:1":"「顔を洗う」: wash one's face.","exam:228:zh":"In the morning, I look in the mirror as I wash my face, including around my eyes and nose.","exam:228:why":"The part that includes the eyes and the area around the nose is the 「顔」. You can wash your 「手」 too, but hands don't include the eyes and nose."},"229":{"example:229:exzh":"I'll do my best together with my friends.","example:229:exzh2":"He's an important friend.","example:229:exzh3":"Friends gather.","example:229:exzh4":"I have a good time with my friends.","example:229:exzh5":"We are good friends."},"230":{"example:230:exzh":"See a friend off.","example:230:exzh2":"I'll send the package.","example:230:exzh3":"I saw her home.","example:230:exzh4":"I'll send a birthday present.","example:230:exzh5":"I'll take you to the station.","grammar:230:ex:trans":"To see a friend off.","grammar:230:ex:structure":"〜を送る","grammar:230:ex:explain":"「送る（おくる）」 has two common meanings: one is \"to send (a thing),\" the other is \"to see (a person) off,\" i.e. to walk partway with someone or see them off. Here 「友達を送る」 is the latter: \"to see a friend off.\" The object is marked with 「を」. Note that it is homophonous with 「贈る」 (to give a gift) and related to 「送迎」 (picking up and dropping off); whether it means sending a thing or seeing a person off depends on the object it takes. The whole sentence is \"to see a friend off.\"","grammar:230:ex:words:0:zh":"friend","grammar:230:ex:words:0:note":"ともだち","grammar:230:ex:words:0:pos":"noun","grammar:230:ex:words:1:zh":"(object marker)","grammar:230:ex:words:1:pos":"particle","grammar:230:ex:words:2:zh":"to see off","grammar:230:ex:words:2:note":"おくる","grammar:230:ex:words:2:pos":"verb","grammar:230:ex:points:0":"❗送る（おくる）: to see (a person) off, to send (a thing).","grammar:230:ex:points:1":"友達を送る: to see a friend off.","grammar:230:ex2:trans":"To send a package.","grammar:230:ex2:structure":"〜を送ります","grammar:230:ex2:words:0:zh":"package","grammar:230:ex2:words:0:note":"にもつ","grammar:230:ex2:words:0:pos":"noun","grammar:230:ex2:words:1:zh":"(object marker)","grammar:230:ex2:words:1:pos":"particle","grammar:230:ex2:words:2:zh":"to send","grammar:230:ex2:words:2:note":"おくります","grammar:230:ex2:words:2:pos":"verb","grammar:230:ex2:points:0":"荷物を送る: to send luggage / a package.","grammar:230:ex2:points:1":"送る→送ります。","grammar:230:ex3:trans":"I walked her home.","grammar:230:ex3:structure":"〜を〜まで送った","grammar:230:ex3:words:0:zh":"she","grammar:230:ex3:words:0:note":"かのじょ","grammar:230:ex3:words:0:pos":"pronoun","grammar:230:ex3:words:1:zh":"(object marker)","grammar:230:ex3:words:1:pos":"particle","grammar:230:ex3:words:2:zh":"house","grammar:230:ex3:words:2:note":"いえ","grammar:230:ex3:words:2:pos":"noun","grammar:230:ex3:words:3:zh":"until","grammar:230:ex3:words:3:pos":"particle","grammar:230:ex3:words:4:zh":"saw off","grammar:230:ex3:words:4:note":"おくった","grammar:230:ex3:words:4:pos":"verb","grammar:230:ex3:points:0":"❗〜まで送る: to see someone off as far as … (まで = endpoint).","grammar:230:ex3:points:1":"家まで送る: to see someone home.","grammar:230:ex4:trans":"To send a birthday present.","grammar:230:ex4:structure":"〜を送ります","grammar:230:ex4:words:0:zh":"birthday","grammar:230:ex4:words:0:note":"たんじょうび","grammar:230:ex4:words:0:pos":"noun","grammar:230:ex4:words:1:zh":"present","grammar:230:ex4:words:1:note":"loanword","grammar:230:ex4:words:1:pos":"noun","grammar:230:ex4:words:2:zh":"(object marker)","grammar:230:ex4:words:2:pos":"particle","grammar:230:ex4:words:3:zh":"to see off","grammar:230:ex4:words:3:note":"おくります","grammar:230:ex4:words:3:pos":"verb","grammar:230:ex4:points:0":"プレゼントを送る: to send a present.","grammar:230:ex4:points:1":"誕生日プレゼント: birthday present.","grammar:230:ex5:trans":"I'll walk you to the station.","grammar:230:ex5:structure":"〜を〜まで送るよ","grammar:230:ex5:words:0:zh":"you","grammar:230:ex5:words:0:note":"きみ","grammar:230:ex5:words:0:pos":"pronoun","grammar:230:ex5:words:1:zh":"(object marker)","grammar:230:ex5:words:1:pos":"particle","grammar:230:ex5:words:2:zh":"station","grammar:230:ex5:words:2:note":"えき","grammar:230:ex5:words:2:pos":"noun","grammar:230:ex5:words:3:zh":"until","grammar:230:ex5:words:3:pos":"particle","grammar:230:ex5:words:4:zh":"to see off","grammar:230:ex5:words:4:note":"おくる","grammar:230:ex5:words:4:pos":"verb","grammar:230:ex5:words:5:zh":"(informing)","grammar:230:ex5:words:5:pos":"particle","grammar:230:ex5:points:0":"駅まで送る: to see someone off to the station.","grammar:230:ex5:points:1":"よ: informing tone."},"231":{"example:231:exzh":"He changed over time.","example:231:exzh2":"My way of thinking changed.","example:231:exzh3":"The seasons change.","example:231:exzh4":"Her voice changed.","example:231:exzh5":"The environment changes.","grammar:231:ex:trans":"He changed over time.","grammar:231:ex:structure":"〜と共に変わった","grammar:231:ex:explain":"「〜と共に（とともに）」 is a rather written-style expression meaning \"along with…, together with…\"; here 「時間と共に」 means \"as time passes.\" The verb 「変わる」 is intransitive, meaning something changes on its own, and the subject is presented with 「は」. 「変わった」 is the plain past. The whole sentence is \"He changed over time.\" 「と共に」 can also mean \"together with someone (doing something)\"; it is formal, more formal than the colloquial 「〜と一緒に」.","grammar:231:ex:words:0:zh":"he","grammar:231:ex:words:0:note":"かれ","grammar:231:ex:words:0:pos":"pronoun","grammar:231:ex:words:1:zh":"(topic)","grammar:231:ex:words:1:pos":"particle","grammar:231:ex:words:2:zh":"time","grammar:231:ex:words:2:note":"じかん","grammar:231:ex:words:2:pos":"noun","grammar:231:ex:words:3:zh":"as; along with","grammar:231:ex:words:3:note":"とともに","grammar:231:ex:words:3:pos":"set phrase","grammar:231:ex:words:4:zh":"changed","grammar:231:ex:words:4:note":"かわった","grammar:231:ex:words:4:pos":"verb","grammar:231:ex:points:0":"❗変わる (intransitive verb, to change); 〜と共に = along with …","grammar:231:ex:points:1":"時間と共に: as time passes.","grammar:231:ex2:trans":"My way of thinking changed.","grammar:231:ex2:structure":"〜は変わった","grammar:231:ex2:words:0:zh":"I","grammar:231:ex2:words:0:note":"わたし","grammar:231:ex2:words:0:pos":"pronoun","grammar:231:ex2:words:1:zh":"'s","grammar:231:ex2:words:1:pos":"particle","grammar:231:ex2:words:2:zh":"idea","grammar:231:ex2:words:2:note":"かんがえ","grammar:231:ex2:words:2:pos":"noun","grammar:231:ex2:words:3:zh":"(topic)","grammar:231:ex2:words:3:pos":"particle","grammar:231:ex2:words:4:zh":"changed","grammar:231:ex2:words:4:note":"かわった","grammar:231:ex2:words:4:pos":"verb","grammar:231:ex2:points:0":"考えが変わる: one's thinking changes.","grammar:231:ex2:points:1":"私の考え: my thoughts.","grammar:231:ex3:trans":"The seasons change.","grammar:231:ex3:structure":"〜が変わる","grammar:231:ex3:words:0:zh":"season","grammar:231:ex3:words:0:note":"きせつ","grammar:231:ex3:words:0:pos":"noun","grammar:231:ex3:words:1:zh":"(nominative)","grammar:231:ex3:words:1:pos":"particle","grammar:231:ex3:words:2:zh":"change","grammar:231:ex3:words:2:note":"かわる","grammar:231:ex3:words:2:pos":"verb","grammar:231:ex3:points:0":"季節が変わる: the seasons change (intransitive verb takes が).","grammar:231:ex3:points:1":"季節: season.","grammar:231:ex4:trans":"Her voice changed.","grammar:231:ex4:structure":"〜は変わった","grammar:231:ex4:words:0:zh":"she","grammar:231:ex4:words:0:note":"かのじょ","grammar:231:ex4:words:0:pos":"pronoun","grammar:231:ex4:words:1:zh":"'s","grammar:231:ex4:words:1:pos":"particle","grammar:231:ex4:words:2:zh":"voice","grammar:231:ex4:words:2:note":"こえ","grammar:231:ex4:words:2:pos":"noun","grammar:231:ex4:words:3:zh":"(topic)","grammar:231:ex4:words:3:pos":"particle","grammar:231:ex4:words:4:zh":"changed","grammar:231:ex4:words:4:note":"かわった","grammar:231:ex4:words:4:pos":"verb","grammar:231:ex4:points:0":"声が変わる: one's voice changes.","grammar:231:ex4:points:1":"彼女の声: her voice.","grammar:231:ex5:trans":"The environment changes.","grammar:231:ex5:structure":"〜が変わる","grammar:231:ex5:words:0:zh":"environment","grammar:231:ex5:words:0:note":"かんきょう","grammar:231:ex5:words:0:pos":"noun","grammar:231:ex5:words:1:zh":"(nominative)","grammar:231:ex5:words:1:pos":"particle","grammar:231:ex5:words:2:zh":"change","grammar:231:ex5:words:2:note":"かわる","grammar:231:ex5:words:2:pos":"verb","grammar:231:ex5:points:0":"環境が変わる: the environment changes.","grammar:231:ex5:points:1":"環境: environment."},"232":{"example:232:exzh":"Life is precious.","example:232:exzh2":"He saved a life.","example:232:exzh3":"Risk one's life to protect it.","example:232:exzh4":"You should treasure life.","example:232:exzh5":"Understand the weight of life."},"234":{"example:234:exzh":"He checked the data.","example:234:exzh2":"Confirmation is needed.","example:234:exzh3":"We confirmed the facts.","example:234:exzh4":"I'll reply after checking the email.","example:234:exzh5":"The checking work is done."},"240":{"example:240:exzh":"Is it okay to keep going like this?","example:240:exzh2":"He respects her as she is.","example:240:exzh3":"It's fine to leave it as it is.","example:240:exzh4":"Children copy adults' movements exactly.","example:240:exzh5":"I want to value myself as I am.","grammar:240:ex:trans":"Is it okay to keep going like this?","grammar:240:ex:structure":"このまま〜てもいいですか","grammar:240:ex:explain":"The core is the permission pattern 「〜てもいい（ですか）」: the te-form of a verb plus 「もいい」 means it's okay to …, … is fine, and adding 「ですか」 politely asks for agreement: may I …? 「このまま」 means like this, as it is. 「続けて」 is the te-form of 「続ける」. The whole sentence means is it okay to keep going like this?, a very practical way to ask permission. To refuse, people often reply 「〜てはいけません」.","grammar:240:ex:words:0:zh":"this","grammar:240:ex:words:0:pos":"pre-noun adjectival","grammar:240:ex:words:1:zh":"(as it is)","grammar:240:ex:words:1:pos":"noun","grammar:240:ex:words:2:zh":"continue","grammar:240:ex:words:2:note":"つづけて","grammar:240:ex:words:2:pos":"verb","grammar:240:ex:words:3:zh":"also, too","grammar:240:ex:words:3:pos":"particle","grammar:240:ex:words:4:zh":"it's okay","grammar:240:ex:words:4:pos":"adjective","grammar:240:ex:words:5:zh":"(polite form)","grammar:240:ex:words:5:pos":"copula","grammar:240:ex:words:6:zh":"(question)","grammar:240:ex:words:6:pos":"particle","grammar:240:ex:points:0":"「このまま」: like this, as it is.","grammar:240:ex:points:1":"「〜てもいいですか」: may I …? (permission)","grammar:240:ex2:trans":"He respects her as she is.","grammar:240:ex2:structure":"〜は、ありのままの〜を尊重している","grammar:240:ex2:explain":"「彼は」 presents the topic of the sentence. 「ありのまま」 is a fixed expression meaning the true, unmodified way something is; with 「の」 it can modify 「彼女」, meaning the her that is her true self. 「を」 marks the object of respect. 「尊重」 plus 「する」 forms the verb 「尊重する」, and here 「している」 shows that he keeps holding an attitude of respect toward her, not just an act of respect at one moment.","grammar:240:ex2:words:0:zh":"he","grammar:240:ex2:words:0:note":"かれ","grammar:240:ex2:words:0:pos":"pronoun","grammar:240:ex2:words:1:zh":"(topic)","grammar:240:ex2:words:1:pos":"particle","grammar:240:ex2:words:2:zh":"the true, unaltered self","grammar:240:ex2:words:2:pos":"noun","grammar:240:ex2:words:3:zh":"(links to a noun, showing a state)","grammar:240:ex2:words:3:pos":"particle","grammar:240:ex2:words:4:zh":"she","grammar:240:ex2:words:4:note":"かのじょ","grammar:240:ex2:words:4:pos":"pronoun","grammar:240:ex2:words:5:zh":"(object)","grammar:240:ex2:words:5:pos":"particle","grammar:240:ex2:words:6:zh":"respect","grammar:240:ex2:words:6:note":"そんちょう","grammar:240:ex2:words:6:pos":"noun","grammar:240:ex2:words:7:zh":"do (combines with 尊重 to form a verb)","grammar:240:ex2:words:7:pos":"verb","grammar:240:ex2:words:8:zh":"(links to a continuing state)","grammar:240:ex2:words:8:pos":"particle","grammar:240:ex2:words:9:zh":"(keeps holding a certain attitude)","grammar:240:ex2:words:9:pos":"verb","grammar:240:ex2:points:0":"「ありのまま」 means the true form of something, with nothing added or changed.","grammar:240:ex2:points:1":"「ありのままの＋人」 means the person just as they really are.","grammar:240:ex2:points:2":"「尊重している」 shows a continuing attitude of respect.","grammar:240:ex3:trans":"It's fine to leave it as it is.","grammar:240:ex3:structure":"そのままにしておいても〜","grammar:240:ex3:words:0:zh":"as it is","grammar:240:ex3:words:0:pos":"adverb","grammar:240:ex3:words:1:zh":"(result)","grammar:240:ex3:words:1:pos":"particle","grammar:240:ex3:words:2:zh":"do","grammar:240:ex3:words:2:pos":"verb","grammar:240:ex3:words:3:zh":"leave it","grammar:240:ex3:words:3:pos":"auxiliary verb","grammar:240:ex3:words:4:zh":"also, too","grammar:240:ex3:words:4:pos":"particle","grammar:240:ex3:words:5:zh":"it's fine","grammar:240:ex3:words:5:pos":"na-adjective","grammar:240:ex3:words:6:zh":"(polite form)","grammar:240:ex3:words:6:pos":"copula","grammar:240:ex3:points:0":"「そのままにしておく」: leave it as it is (idiomatic).","grammar:240:ex3:points:1":"「〜てもいい」: it's fine even if …","grammar:240:ex4:trans":"Children imitate adults' movements exactly as they are.","grammar:240:ex4:structure":"〜は、〜をそのまま真似する","grammar:240:ex4:explain":"「子供は」 makes children the topic. In 「大人の動き」, 「の」 shows the movements are the adults', and the whole phrase is marked with 「を」 as the object of imitation. Here 「そのまま」 works as an adverb meaning just as it is, without change. 「真似する」 is made of the noun 「真似」 plus the verb 「する」 and means imitate; the sentence ends in the dictionary form, describing what children generally do.","grammar:240:ex4:words:0:zh":"child","grammar:240:ex4:words:0:note":"こども","grammar:240:ex4:words:0:pos":"noun","grammar:240:ex4:words:1:zh":"(topic)","grammar:240:ex4:words:1:pos":"particle","grammar:240:ex4:words:2:zh":"adult","grammar:240:ex4:words:2:note":"おとな","grammar:240:ex4:words:2:pos":"noun","grammar:240:ex4:words:3:zh":"(possession)","grammar:240:ex4:words:3:pos":"particle","grammar:240:ex4:words:4:zh":"movement","grammar:240:ex4:words:4:note":"うごき","grammar:240:ex4:words:4:pos":"noun","grammar:240:ex4:words:5:zh":"(object)","grammar:240:ex4:words:5:pos":"particle","grammar:240:ex4:words:6:zh":"exactly as it is","grammar:240:ex4:words:6:pos":"adverb","grammar:240:ex4:words:7:zh":"imitate","grammar:240:ex4:words:7:note":"まね","grammar:240:ex4:words:7:pos":"noun","grammar:240:ex4:words:8:zh":"do (combines with 真似 to form a verb)","grammar:240:ex4:words:8:pos":"verb","grammar:240:ex4:points:0":"「そのまま」 modifies the action, showing it happens just as it is, without any change.","grammar:240:ex4:points:1":"「〜を真似する」 means to imitate someone or a particular movement.","grammar:240:ex5:trans":"I want to value myself as I am.","grammar:240:ex5:structure":"〜を大切にしたい","grammar:240:ex5:explain":"「私は」 presents the speaker as the topic. 「ありのままの自分」 means the real, unaltered self, and 「の」 links that state to 「自分」. 「自分を」 marks the object of cherishing. 「大切にする」 means to cherish or value, with 「に」 marking the manner of treating it. When 「する」 takes 「たい」, which expresses desire, it becomes 「したい」, so 「大切にしたい」 means wanting to cherish.","grammar:240:ex5:words:0:zh":"I","grammar:240:ex5:words:0:note":"わたし","grammar:240:ex5:words:0:pos":"pronoun","grammar:240:ex5:words:1:zh":"(topic)","grammar:240:ex5:words:1:pos":"particle","grammar:240:ex5:words:2:zh":"the true, unaltered self","grammar:240:ex5:words:2:pos":"noun","grammar:240:ex5:words:3:zh":"(links to a noun, showing a state)","grammar:240:ex5:words:3:pos":"particle","grammar:240:ex5:words:4:zh":"oneself","grammar:240:ex5:words:4:note":"じぶん","grammar:240:ex5:words:4:pos":"pronoun","grammar:240:ex5:words:5:zh":"(object)","grammar:240:ex5:words:5:pos":"particle","grammar:240:ex5:words:6:zh":"precious, important","grammar:240:ex5:words:6:note":"たいせつ","grammar:240:ex5:words:6:pos":"na-adjective","grammar:240:ex5:words:7:zh":"(the manner of treating)","grammar:240:ex5:words:7:pos":"particle","grammar:240:ex5:words:8:zh":"treat","grammar:240:ex5:words:8:pos":"verb","grammar:240:ex5:words:9:zh":"to want to","grammar:240:ex5:words:9:pos":"auxiliary verb","grammar:240:ex5:points:0":"「ありのままの自分」 means the self without pretense or forced change.","grammar:240:ex5:points:1":"「〜を大切にする」 is a set expression meaning to cherish or value …","grammar:240:ex5:points:2":"「動詞ます形去掉ます＋たい」 expresses wanting to do something."},"241":{"example:241:exzh":"He went home first.","example:241:exzh2":"Future plans are undecided.","example:241:exzh3":"I'll go ahead and wait.","example:241:exzh4":"Once work is done, let's go for a drink first.","example:241:exzh5":"She acts with an eye to the future.","grammar:241:ex:trans":"He went home first.","grammar:241:ex:structure":"noun は + 先に + verb-ました. 「先に」 works as an adverb meaning first, before others.","grammar:241:ex:explain":"「先に」 (さきに) is an adverb meaning first, in advance, or ahead of others. 「帰りました」 is the polite past of 「帰る」 (帰る changes to its masu-stem 帰り, then ました is added). 「彼は先に帰りました」 means he went home first, implying he left earlier than the others. Note that although 「帰る」 ends in る, it is a godan (u-) verb, not an ichidan (ru-) verb, so it conjugates as godan; this is a common exception.","grammar:241:ex:words:0:zh":"he","grammar:241:ex:words:0:note":"かれ","grammar:241:ex:words:0:pos":"pronoun","grammar:241:ex:words:1:zh":"(topic marker)","grammar:241:ex:words:1:pos":"particle","grammar:241:ex:words:2:zh":"first","grammar:241:ex:words:2:note":"さきに; 先＋に works as an adverb","grammar:241:ex:words:2:pos":"adverb","grammar:241:ex:words:3:zh":"went home","grammar:241:ex:words:3:note":"かえりました; masu-form past","grammar:241:ex:words:3:pos":"verb","grammar:241:ex:points:0":"先に: first, in advance (adverb)","grammar:241:ex:points:1":"帰りました: the polite past of 帰る","grammar:241:ex2:trans":"The plan ahead is not yet set.","grammar:241:ex2:structure":"〔noun の noun〕＋は＋noun＋です. 「先の予定」 = the plan ahead, and the predicate is a noun.","grammar:241:ex2:words:0:zh":"before / ahead","grammar:241:ex2:words:0:note":"さき","grammar:241:ex2:words:0:pos":"noun","grammar:241:ex2:words:1:zh":"'s","grammar:241:ex2:words:1:pos":"particle","grammar:241:ex2:words:2:zh":"plans","grammar:241:ex2:words:2:note":"よてい","grammar:241:ex2:words:2:pos":"noun","grammar:241:ex2:words:3:zh":"(topic marker)","grammar:241:ex2:words:3:pos":"particle","grammar:241:ex2:words:4:zh":"undecided","grammar:241:ex2:words:4:note":"みてい","grammar:241:ex2:words:4:pos":"noun","grammar:241:ex2:words:5:zh":"(polite form)","grammar:241:ex2:words:5:pos":"copula","grammar:241:ex2:points:0":"先: can refer to either before or after in time (here it means what comes later)","grammar:241:ex2:points:1":"〜は…です: describes a state","grammar:241:ex3:trans":"I'll go ahead and wait for you.","grammar:241:ex3:structure":"先に＋〔verb te-form〕＋verb-ています. 「行って」 uses the te-form to connect, meaning go first and then wait.","grammar:241:ex3:words:0:zh":"first","grammar:241:ex3:words:0:note":"さきに","grammar:241:ex3:words:0:pos":"adverb","grammar:241:ex3:words:1:zh":"go (and)","grammar:241:ex3:words:1:note":"いって; the te-form links to the next clause","grammar:241:ex3:words:1:pos":"verb","grammar:241:ex3:words:2:zh":"waiting","grammar:241:ex3:words:2:note":"まっています; 〜ている expresses a state","grammar:241:ex3:words:2:pos":"verb","grammar:241:ex3:points:0":"verb te-form: links two actions in sequence, … and then …","grammar:241:ex3:points:1":"The te-form of 行く is an exception: 行って","grammar:241:ex4:trans":"After work is over, let's go for a drink first.","grammar:241:ex4:structure":"〜たら、先に＋〔verb masu-stem＋に〕＋行こう. 「たら」 marks the condition, and 「飲みに行く」 = go drinking (に marks the purpose of the action).","grammar:241:ex4:words:0:zh":"work","grammar:241:ex4:words:0:note":"しごと","grammar:241:ex4:words:0:pos":"noun","grammar:241:ex4:words:1:zh":"(nominative)","grammar:241:ex4:words:1:pos":"particle","grammar:241:ex4:words:2:zh":"when it's over","grammar:241:ex4:words:2:note":"おわったら; ta-form＋ら for the condition","grammar:241:ex4:words:2:pos":"verb","grammar:241:ex4:words:3:zh":"first","grammar:241:ex4:words:3:note":"さきに","grammar:241:ex4:words:3:pos":"adverb","grammar:241:ex4:words:4:zh":"go drinking","grammar:241:ex4:words:4:note":"のみに; masu-stem＋に marks purpose","grammar:241:ex4:words:4:pos":"verb","grammar:241:ex4:words:5:zh":"let's go","grammar:241:ex4:words:5:note":"ikou；volitional form","grammar:241:ex4:words:5:pos":"verb","grammar:241:ex4:points:0":"〜たら：after… / if…, then…","grammar:241:ex4:points:1":"verb masu-stem + に行く: go in order to do… (飲みに行く = go for a drink)","grammar:241:ex5:trans":"She anticipates what lies ahead and acts.","grammar:241:ex5:structure":"noun を + 〔verb te-form〕 + 動詞します. 「先を見越して」 = anticipating the future; the te-form links to the next action.","grammar:241:ex5:words:0:zh":"she","grammar:241:ex5:words:0:note":"かのじょ","grammar:241:ex5:words:0:pos":"pronoun","grammar:241:ex5:words:1:zh":"(topic marker)","grammar:241:ex5:words:1:pos":"particle","grammar:241:ex5:words:2:zh":"ahead / the future","grammar:241:ex5:words:2:note":"さき","grammar:241:ex5:words:2:pos":"noun","grammar:241:ex5:words:3:zh":"(object marker)","grammar:241:ex5:words:3:pos":"particle","grammar:241:ex5:words:4:zh":"anticipate (and)","grammar:241:ex5:words:4:note":"mikoshite；te-form","grammar:241:ex5:words:4:pos":"verb","grammar:241:ex5:words:5:zh":"act","grammar:241:ex5:words:5:note":"こうどうします","grammar:241:ex5:words:5:pos":"verb","grammar:241:ex5:points:0":"先を見越す: to anticipate the future / to plan ahead","grammar:241:ex5:points:1":"te-form linking: 見越して行動する (anticipate and act)","exam:241:zh":"I can't go home yet, so I said to my friend who was leaving, 「Please go ahead.」","exam:241:why":"「お先にどうぞ」 is a set phrase asking the other person to go first. 「後」 means after, so it can't form this expression."},"242":{"example:242:exzh":"I intend to make a phone call.","example:242:exzh2":"I spent time writing the letter.","example:242:exzh3":"I'll hang a clock on the wall.","example:242:exzh4":"I spent a lot of money on the wedding.","example:242:exzh5":"He spends time on his work.","grammar:242:ex:trans":"I intend to make a phone call.","grammar:242:ex:structure":"電話をかける + つもりです","grammar:242:ex:explain":"In this sentence 「かける」 doesn't mean to hang something up; together with 「電話」 it means to make a phone call. Japanese often says 「電話をかける」, with the object marked by 「を」. The sentence-final 「つもりです」 makes the whole sentence mean \"intend to do.\"","grammar:242:ex:words:0:zh":"phone call","grammar:242:ex:words:0:note":"でんわ","grammar:242:ex:words:0:pos":"noun","grammar:242:ex:words:1:zh":"object marker","grammar:242:ex:words:1:pos":"particle","grammar:242:ex:words:2:zh":"to make (a call)","grammar:242:ex:words:2:pos":"verb","grammar:242:ex:words:3:zh":"intend to","grammar:242:ex:words:3:pos":"noun","grammar:242:ex:words:4:zh":"is","grammar:242:ex:words:4:pos":"copula","grammar:242:ex:points:0":"「電話をかける」 is a set expression meaning to make a phone call.","grammar:242:ex:points:1":"「つもりです」 shows that the speaker already has a certain intention.","grammar:242:ex2:trans":"I spent time writing a letter.","grammar:242:ex2:structure":"手紙を書くのに + 時間をかけました","grammar:242:ex2:words:0:zh":"letter","grammar:242:ex2:words:0:note":"てがみ","grammar:242:ex2:words:0:pos":"noun","grammar:242:ex2:words:1:zh":"object marker","grammar:242:ex2:words:1:pos":"particle","grammar:242:ex2:words:2:zh":"write","grammar:242:ex2:words:2:note":"かく","grammar:242:ex2:words:2:pos":"verb","grammar:242:ex2:words:3:zh":"thing / matter","grammar:242:ex2:words:3:pos":"formal noun","grammar:242:ex2:words:4:zh":"purpose","grammar:242:ex2:words:4:pos":"particle","grammar:242:ex2:words:5:zh":"time","grammar:242:ex2:words:5:note":"じかん","grammar:242:ex2:words:5:pos":"noun","grammar:242:ex2:words:6:zh":"object marker","grammar:242:ex2:words:6:pos":"particle","grammar:242:ex2:words:7:zh":"to take (time)","grammar:242:ex2:words:7:note":"かけました; masu-form past","grammar:242:ex2:words:7:pos":"verb","grammar:242:ex2:points:0":"「時間をかけました」 means spent time, and the object is 「時間」.","grammar:242:ex2:points:1":"「動詞辭書形＋のに」 expresses doing something for the sake of the preceding action.","grammar:242:ex3:trans":"I hang a clock on the wall.","grammar:242:ex3:structure":"壁に + 時計を + かけます","grammar:242:ex3:words:0:zh":"wall","grammar:242:ex3:words:0:note":"かべ","grammar:242:ex3:words:0:pos":"noun","grammar:242:ex3:words:1:zh":"location","grammar:242:ex3:words:1:pos":"particle","grammar:242:ex3:words:2:zh":"clock","grammar:242:ex3:words:2:note":"とけい","grammar:242:ex3:words:2:pos":"noun","grammar:242:ex3:words:3:zh":"object marker","grammar:242:ex3:words:3:pos":"particle","grammar:242:ex3:words:4:zh":"to hang","grammar:242:ex3:words:4:note":"かけます; masu-form","grammar:242:ex3:words:4:pos":"verb","grammar:242:ex3:points:0":"Here 「かけます」 means to hang an object somewhere.","grammar:242:ex3:points:1":"「壁に」 marks the place where something is hung.","grammar:242:ex4:trans":"A lot of money was spent on the wedding.","grammar:242:ex4:structure":"結婚式に＋お金を＋かけました","grammar:242:ex4:words:0:zh":"wedding","grammar:242:ex4:words:0:note":"けっこんしき; wedding","grammar:242:ex4:words:0:pos":"noun","grammar:242:ex4:words:1:zh":"the thing the money is spent on","grammar:242:ex4:words:1:pos":"particle","grammar:242:ex4:words:2:zh":"money","grammar:242:ex4:words:2:note":"おかね; money","grammar:242:ex4:words:2:pos":"noun","grammar:242:ex4:words:3:zh":"object marker","grammar:242:ex4:words:3:pos":"particle","grammar:242:ex4:words:4:zh":"to take (time)","grammar:242:ex4:words:4:pos":"verb","grammar:242:ex4:words:5:zh":"polite past","grammar:242:ex4:words:5:pos":"auxiliary verb","grammar:242:ex4:points:0":"「お金をかける」 means to spend or put money into something; where the money goes is marked with 「に」: 「結婚式に」.","grammar:242:ex4:points:1":"「かけました」 is the polite past form of 「かける」: an ichidan (ru-) verb drops 「る」 and takes 「ました」.","grammar:242:ex5:trans":"He spends time on his work.","grammar:242:ex5:structure":"彼は + 仕事に時間を + かけています","grammar:242:ex5:words:0:zh":"he","grammar:242:ex5:words:0:note":"かれ","grammar:242:ex5:words:0:pos":"pronoun","grammar:242:ex5:words:1:zh":"topic","grammar:242:ex5:words:1:pos":"particle","grammar:242:ex5:words:2:zh":"work","grammar:242:ex5:words:2:note":"しごと","grammar:242:ex5:words:2:pos":"noun","grammar:242:ex5:words:3:zh":"recipient","grammar:242:ex5:words:3:pos":"particle","grammar:242:ex5:words:4:zh":"time","grammar:242:ex5:words:4:note":"じかん","grammar:242:ex5:words:4:pos":"noun","grammar:242:ex5:words:5:zh":"object marker","grammar:242:ex5:words:5:pos":"particle","grammar:242:ex5:words:6:zh":"to take (time)","grammar:242:ex5:words:6:note":"かけて; te-form","grammar:242:ex5:words:6:pos":"verb","grammar:242:ex5:words:7:zh":"in progress","grammar:242:ex5:words:7:note":"います","grammar:242:ex5:words:7:pos":"auxiliary verb","grammar:242:ex5:points:0":"「時間をかけています」 means currently spending time on something.","grammar:242:ex5:points:1":"「に」 marks the thing the time is put into, which is work."},"243":{"example:243:exzh":"There's no way something that stupid would happen.","example:243:exzh2":"He was told he was an idiot.","example:243:exzh3":"Don't do anything stupid.","example:243:exzh4":"A friend made a fool of me.","example:243:exzh5":"Stop doing stupid things!","grammar:243:ex:trans":"There's no such thing.","grammar:243:ex:structure":"そんな〜なことはない","grammar:243:ex:explain":"This is the pattern 「そんな〜なことはない」, which denies that a certain kind of situation exists; literally \"there is no such … thing,\" meaning \"that's impossible.\" 「そんな」 is the pre-noun adjectival \"such,\" and 「バカな」 is the na-adjective \"stupid\" modifying 「こと」 (thing), joined with 「な」. The final 「ない」 is the negative of 「ある」, meaning \"there is not, does not exist.\" The whole sentence means \"there's no such stupid thing — impossible,\" with a tone of rebuttal and denial.","grammar:243:ex:words:0:zh":"such","grammar:243:ex:words:0:pos":"pre-noun adjectival","grammar:243:ex:words:1:zh":"stupid","grammar:243:ex:words:1:pos":"na-adjective","grammar:243:ex:words:2:zh":"(attributive form)","grammar:243:ex:words:2:pos":"auxiliary verb","grammar:243:ex:words:3:zh":"thing / matter","grammar:243:ex:words:3:pos":"noun","grammar:243:ex:words:4:zh":"(topic)","grammar:243:ex:words:4:pos":"particle","grammar:243:ex:words:5:zh":"don't have","grammar:243:ex:words:5:pos":"adjective","grammar:243:ex:points:0":"バカな: stupid (na-adjective).","grammar:243:ex:points:1":"そんなバカなことはない: there's no such stupid thing.","grammar:243:ex2:trans":"He was said to be a fool.","grammar:243:ex2:structure":"〜だと言われた","grammar:243:ex2:words:0:zh":"he","grammar:243:ex2:words:0:note":"かれ","grammar:243:ex2:words:0:pos":"pronoun","grammar:243:ex2:words:1:zh":"(topic)","grammar:243:ex2:words:1:pos":"particle","grammar:243:ex2:words:2:zh":"fool","grammar:243:ex2:words:2:pos":"noun","grammar:243:ex2:words:3:zh":"is","grammar:243:ex2:words:3:pos":"copula","grammar:243:ex2:words:4:zh":"(quotation)","grammar:243:ex2:words:4:pos":"particle","grammar:243:ex2:words:5:zh":"is said","grammar:243:ex2:words:5:note":"いわれた (passive form)","grammar:243:ex2:words:5:pos":"verb","grammar:243:ex2:points:0":"〜と言われた: was said to be … (passive form).","grammar:243:ex2:points:1":"バカだ: (is) a fool (plain-form assertion).","grammar:243:ex3:trans":"Don't do anything stupid.","grammar:243:ex3:structure":"〜なことをしないように","grammar:243:ex3:words:0:zh":"stupid","grammar:243:ex3:words:0:pos":"na-adjective","grammar:243:ex3:words:1:zh":"(attributive form)","grammar:243:ex3:words:1:pos":"auxiliary verb","grammar:243:ex3:words:2:zh":"thing / matter","grammar:243:ex3:words:2:pos":"noun","grammar:243:ex3:words:3:zh":"(object marker)","grammar:243:ex3:words:3:pos":"particle","grammar:243:ex3:words:4:zh":"don't do (it)","grammar:243:ex3:words:4:pos":"verb","grammar:243:ex3:points:0":"バカなこと: something stupid.","grammar:243:ex3:points:1":"「〜ないように」: don't … (a reminder)","grammar:243:ex4:trans":"I was made a fool of by a friend.","grammar:243:ex4:structure":"〜にバカにされた","grammar:243:ex4:words:0:zh":"friend","grammar:243:ex4:words:0:note":"ともだち","grammar:243:ex4:words:0:pos":"noun","grammar:243:ex4:words:1:zh":"(the doer of the action)","grammar:243:ex4:words:1:pos":"particle","grammar:243:ex4:words:2:zh":"to be treated as a fool / to be mocked","grammar:243:ex4:words:2:note":"ばかにされた (passive form)","grammar:243:ex4:words:2:pos":"verb","grammar:243:ex4:points:0":"❓In the passive, the doer is marked with に: 友達に〜された.","grammar:243:ex4:points:1":"バカにする: to look down on, to mock; passive バカにされる.","grammar:243:ex5:trans":"Stop doing stupid things!","grammar:243:ex5:structure":"〜を続けないで","grammar:243:ex5:words:0:zh":"stupid","grammar:243:ex5:words:0:pos":"na-adjective","grammar:243:ex5:words:1:zh":"(attributive form)","grammar:243:ex5:words:1:pos":"auxiliary verb","grammar:243:ex5:words:2:zh":"thing / matter","grammar:243:ex5:words:2:pos":"noun","grammar:243:ex5:words:3:zh":"(object marker)","grammar:243:ex5:words:3:pos":"particle","grammar:243:ex5:words:4:zh":"don't keep (doing)","grammar:243:ex5:words:4:note":"つづけないで","grammar:243:ex5:words:4:pos":"verb","grammar:243:ex5:points:0":"バカなこと: something stupid.","grammar:243:ex5:points:1":"〜ないで（！）: don't … (casual command)."},"244":{"example:244:exzh":"I wish you happiness.","example:244:exzh2":"Please come in this way.","example:244:exzh3":"Please wait.","example:244:exzh4":"Please, do as you like.","example:244:exzh5":"Please check it at hand.","grammar:244:ex:trans":"Wishing you happiness.","grammar:244:ex:structure":"どうぞ〜に","grammar:244:ex:explain":"This is the set blessing 「どうぞお幸せに」, used to wish someone happiness (especially at a wedding), meaning \"I wish you happiness.\" 「どうぞ」 is a polite \"please, do,\" which softens the tone and makes it sincere. 「お幸せに」 is made up of the beautifying prefix 「お」 plus 「幸せ」 (happiness) plus 「に」; the verb that would follow, something like 「なってください」, is actually left out — Japanese often leaves a blessing half-finished like this, which makes it more reserved. A similar one is 「お元気で」 (take care).","grammar:244:ex:words:0:zh":"please","grammar:244:ex:words:0:pos":"adverb","grammar:244:ex:words:1:zh":"(wishing) happiness","grammar:244:ex:words:1:note":"おしあわせに","grammar:244:ex:words:1:pos":"set phrase","grammar:244:ex:points:0":"どうぞ: please, do (polite).","grammar:244:ex:points:1":"どうぞお幸せに: I wish you happiness (a blessing).","grammar:244:ex2:trans":"Please come in here.","grammar:244:ex2:structure":"どうぞお〜ください","grammar:244:ex2:words:0:zh":"this way","grammar:244:ex2:words:0:pos":"pronoun","grammar:244:ex2:words:1:zh":"(direction)","grammar:244:ex2:words:1:pos":"particle","grammar:244:ex2:words:2:zh":"please","grammar:244:ex2:words:2:pos":"adverb","grammar:244:ex2:words:3:zh":"please come in","grammar:244:ex2:words:3:note":"おはいりください","grammar:244:ex2:words:3:pos":"set phrase","grammar:244:ex2:points:0":"どうぞ: please (encouraging the other person).","grammar:244:ex2:points:1":"お入りください: please come in (お + verb + ください, keigo).","grammar:244:ex3:trans":"Please wait a moment.","grammar:244:ex3:structure":"どうぞお〜ください","grammar:244:ex3:words:0:zh":"please","grammar:244:ex3:words:0:pos":"adverb","grammar:244:ex3:words:1:zh":"please wait","grammar:244:ex3:words:1:note":"おまちください","grammar:244:ex3:words:1:pos":"set phrase","grammar:244:ex3:points:0":"お待ちください: please wait (sonkeigo).","grammar:244:ex3:points:1":"どうぞ: adds politeness.","grammar:244:ex4:trans":"Please do as you like.","grammar:244:ex4:structure":"どうぞお〜ように","grammar:244:ex4:words:0:zh":"please","grammar:244:ex4:words:0:pos":"adverb","grammar:244:ex4:words:1:zh":"as you like","grammar:244:ex4:words:1:note":"おすきなように","grammar:244:ex4:words:1:pos":"set phrase","grammar:244:ex4:points:0":"お好きなように: as you like (whatever suits you).","grammar:244:ex4:points:1":"どうぞ: please.","grammar:244:ex5:trans":"Please check what you have at hand.","grammar:244:ex5:structure":"どうぞ〜でご〜ください","grammar:244:ex5:words:0:zh":"please","grammar:244:ex5:words:0:pos":"adverb","grammar:244:ex5:words:1:zh":"at hand","grammar:244:ex5:words:1:note":"おてもと","grammar:244:ex5:words:1:pos":"noun","grammar:244:ex5:words:2:zh":"(place)","grammar:244:ex5:words:2:pos":"particle","grammar:244:ex5:words:3:zh":"please check","grammar:244:ex5:words:3:note":"ごかくにんください","grammar:244:ex5:words:3:pos":"set phrase","grammar:244:ex5:points:0":"ご確認ください: please check (ご + Sino-Japanese noun + ください, keigo).","grammar:244:ex5:points:1":"お手元で: at hand (in your possession).","exam:244:zh":"I offered the guest a chair and said, \"Please sit here.\"","exam:244:why":"「どうぞ」 can be used to politely invite someone to do something. 「どうも」 is often used for things like thanks, and it can't mean please here."},"246":{"example:246:exzh":"That's his fault.","example:246:exzh2":"The delay was due to the weather.","example:246:exzh3":"It's all your fault.","example:246:exzh4":"Her absence is my fault.","example:246:exzh5":"I've had some trouble because of that."},"247":{"example:247:exzh":"It wasn't as easy as he thought.","example:247:exzh2":"The job wasn't as hard as I thought.","example:247:exzh3":"How much do you like it?","example:247:exzh4":"I like you so much that I think about you all the time.","example:247:exzh5":"She hadn't thought about me as deeply as I had."},"248":{"example:248:exzh":"I wonder if it'll rain tomorrow.","example:248:exzh2":"I wonder if he'll come?","example:248:exzh3":"I wonder if this is needed?","example:248:exzh4":"I wonder if she's doing well?","example:248:exzh5":"I wonder if someone will come."},"250":{"example:250:exzh":"He gets moving early every morning.","example:250:exzh2":"I heard the sound of something moving.","example:250:exzh3":"Please look at the car that's moving.","example:250:exzh4":"She moved her hand in a big motion.","example:250:exzh5":"The children are happily moving around in the park.","grammar:250:ex:trans":"He gets moving early every morning.","grammar:250:ex:structure":"早く動きます","grammar:250:ex:explain":"「動く（うごく）」 is an intransitive verb meaning \"(to) move, to act\" on one's own; the subject moves by itself and needs no object. Its transitive counterpart is 「動かす（うごかす, to make … move, to move something）」, which takes an object with 「を」. Here in 「彼は…動きます」, 「彼」 acts on his own, so the intransitive is used. 「早く」 is the adverb \"early,\" and 「毎朝」 means \"every morning.\" The whole sentence is \"He starts moving around early every morning.\"","grammar:250:ex:words:0:zh":"he","grammar:250:ex:words:0:note":"かれ","grammar:250:ex:words:0:pos":"pronoun","grammar:250:ex:words:1:zh":"(topic)","grammar:250:ex:words:1:pos":"particle","grammar:250:ex:words:2:zh":"every morning","grammar:250:ex:words:2:note":"まいあさ","grammar:250:ex:words:2:pos":"adverb","grammar:250:ex:words:3:zh":"early (as an adverb)","grammar:250:ex:words:3:note":"はやく","grammar:250:ex:words:3:pos":"adverb","grammar:250:ex:words:4:zh":"to move, to act","grammar:250:ex:words:4:note":"うごきます","grammar:250:ex:words:4:pos":"verb","grammar:250:ex:points:0":"❗動く（うごく）: to move, to act (intransitive verb); vs 動かす (transitive verb, to make … move).","grammar:250:ex:points:1":"早く動く: to get moving early.","grammar:250:ex2:trans":"I heard the sound of something moving.","grammar:250:ex2:structure":"〜が動いている音が聞こえた","grammar:250:ex2:words:0:zh":"what","grammar:250:ex2:words:0:note":"なにか","grammar:250:ex2:words:0:pos":"pronoun","grammar:250:ex2:words:1:zh":"(nominative)","grammar:250:ex2:words:1:pos":"particle","grammar:250:ex2:words:2:zh":"moving","grammar:250:ex2:words:2:note":"うごいている","grammar:250:ex2:words:2:pos":"verb","grammar:250:ex2:words:3:zh":"voice","grammar:250:ex2:words:3:note":"おと","grammar:250:ex2:words:3:pos":"noun","grammar:250:ex2:words:4:zh":"(nominative)","grammar:250:ex2:words:4:pos":"particle","grammar:250:ex2:words:5:zh":"heard","grammar:250:ex2:words:5:note":"きこえた","grammar:250:ex2:words:5:pos":"verb","grammar:250:ex2:points:0":"❗何かが動いている音: the sound of something moving (pre-noun adjectival).","grammar:250:ex2:points:1":"動く: (of a thing) to move.","grammar:250:ex3:trans":"Please look at that car that's moving.","grammar:250:ex3:structure":"動いている〜を見てください","grammar:250:ex3:words:0:zh":"moving","grammar:250:ex3:words:0:note":"うごいている","grammar:250:ex3:words:0:pos":"verb","grammar:250:ex3:words:1:zh":"car","grammar:250:ex3:words:1:note":"くるま","grammar:250:ex3:words:1:pos":"noun","grammar:250:ex3:words:2:zh":"(object marker)","grammar:250:ex3:words:2:pos":"particle","grammar:250:ex3:words:3:zh":"look","grammar:250:ex3:words:3:note":"みて","grammar:250:ex3:words:3:pos":"verb","grammar:250:ex3:words:4:zh":"please","grammar:250:ex3:words:4:pos":"auxiliary verb","grammar:250:ex3:points:0":"動いている車: a moving car (pre-noun adjectival).","grammar:250:ex3:points:1":"〜ている: ongoing action.","grammar:250:ex4:trans":"She moved her hand in a big motion.","grammar:250:ex4:structure":"〜を動かしました","grammar:250:ex4:words:0:zh":"she","grammar:250:ex4:words:0:note":"かのじょ","grammar:250:ex4:words:0:pos":"pronoun","grammar:250:ex4:words:1:zh":"(topic)","grammar:250:ex4:words:1:pos":"particle","grammar:250:ex4:words:2:zh":"in a big motion","grammar:250:ex4:words:2:note":"おおきく","grammar:250:ex4:words:2:pos":"adverb","grammar:250:ex4:words:3:zh":"hand","grammar:250:ex4:words:3:note":"て","grammar:250:ex4:words:3:pos":"noun","grammar:250:ex4:words:4:zh":"(object marker)","grammar:250:ex4:words:4:pos":"particle","grammar:250:ex4:words:5:zh":"to make … move","grammar:250:ex4:words:5:note":"うごかしました","grammar:250:ex4:words:5:pos":"verb","grammar:250:ex4:points:0":"❗動かす (transitive verb, to make … move, to wave) + を; vs 動く (intransitive verb).","grammar:250:ex4:points:1":"手を動かす: to move one's hand.","grammar:250:ex5:trans":"The children are playing happily in the park.","grammar:250:ex5:structure":"〜で〜そうに動いている","grammar:250:ex5:words:0:zh":"children","grammar:250:ex5:words:0:note":"こどもたち","grammar:250:ex5:words:0:pos":"noun","grammar:250:ex5:words:1:zh":"(topic)","grammar:250:ex5:words:1:pos":"particle","grammar:250:ex5:words:2:zh":"park","grammar:250:ex5:words:2:note":"こうえん","grammar:250:ex5:words:2:pos":"noun","grammar:250:ex5:words:3:zh":"(place)","grammar:250:ex5:words:3:pos":"particle","grammar:250:ex5:words:4:zh":"enjoyably","grammar:250:ex5:words:4:note":"たのしそうに","grammar:250:ex5:words:4:pos":"adverb","grammar:250:ex5:words:5:zh":"carrying out activities","grammar:250:ex5:words:5:note":"うごいている","grammar:250:ex5:words:5:pos":"verb","grammar:250:ex5:points:0":"❗楽しそうに: looking happy, happily (appearance そう + に).","grammar:250:ex5:points:1":"❓公園で: in the park (で = place)."},"251":{"example:251:exzh":"A ship is floating on the sea.","example:251:exzh2":"She likes riding on ships.","example:251:exzh3":"The ship came into the harbor.","example:251:exzh4":"This ship is fast.","example:251:exzh5":"We'll travel by ship.","grammar:251:ex:trans":"A boat is floating on the sea.","grammar:251:ex:structure":"〜に〜が浮かんでいる","grammar:251:ex:explain":"The location 「海」 is marked with 「に」, and 「船が」 picks out the subject with 「が」. The verb 「浮かぶ」 is the intransitive verb \"to float, to rise to the surface\"; here 「〜ている」 expresses the continuing state of floating, not an action in progress. The te-form of 「浮かぶ」 changes to 「浮かんで」 (geminate sound change), and then 「いる」 is added. The whole sentence is \"a boat is floating on the sea.\" This kind of descriptive passage often uses 「〜が〜ている」 to describe a static scene before one's eyes.","grammar:251:ex:words:0:zh":"sea","grammar:251:ex:words:0:note":"うみ","grammar:251:ex:words:0:pos":"noun","grammar:251:ex:words:1:zh":"(location of existence)","grammar:251:ex:words:1:pos":"particle","grammar:251:ex:words:2:zh":"boat","grammar:251:ex:words:2:note":"ふね","grammar:251:ex:words:2:pos":"noun","grammar:251:ex:words:3:zh":"(nominative)","grammar:251:ex:words:3:pos":"particle","grammar:251:ex:words:4:zh":"is floating","grammar:251:ex:words:4:note":"うかんでいる","grammar:251:ex:words:4:pos":"verb","grammar:251:ex:points:0":"海に: on the sea.","grammar:251:ex:points:1":"浮かぶ: to float (intransitive verb); 〜ている: state.","grammar:251:ex2:trans":"She likes riding on boats.","grammar:251:ex2:structure":"〜に乗るのが好きです","grammar:251:ex2:words:0:zh":"she","grammar:251:ex2:words:0:note":"かのじょ","grammar:251:ex2:words:0:pos":"pronoun","grammar:251:ex2:words:1:zh":"(topic)","grammar:251:ex2:words:1:pos":"particle","grammar:251:ex2:words:2:zh":"boat","grammar:251:ex2:words:2:note":"ふね","grammar:251:ex2:words:2:pos":"noun","grammar:251:ex2:words:3:zh":"(object)","grammar:251:ex2:words:3:pos":"particle","grammar:251:ex2:words:4:zh":"to ride, to board","grammar:251:ex2:words:4:note":"のる","grammar:251:ex2:words:4:pos":"verb","grammar:251:ex2:words:5:zh":"(nominalizer)","grammar:251:ex2:words:5:pos":"particle","grammar:251:ex2:words:6:zh":"(object)","grammar:251:ex2:words:6:pos":"particle","grammar:251:ex2:words:7:zh":"to like","grammar:251:ex2:words:7:note":"すき","grammar:251:ex2:words:7:pos":"na-adjective","grammar:251:ex2:words:8:zh":"(polite form)","grammar:251:ex2:words:8:pos":"copula","grammar:251:ex2:points:0":"❗船に乗る: to ride a boat (the object of 乗る takes に).","grammar:251:ex2:points:1":"〜のが好き: to like doing…","grammar:251:ex3:trans":"A boat came into the harbor.","grammar:251:ex3:structure":"〜に入ってきた","grammar:251:ex3:words:0:zh":"boat","grammar:251:ex3:words:0:note":"ふね","grammar:251:ex3:words:0:pos":"noun","grammar:251:ex3:words:1:zh":"(nominative)","grammar:251:ex3:words:1:pos":"particle","grammar:251:ex3:words:2:zh":"harbor","grammar:251:ex3:words:2:note":"みなと","grammar:251:ex3:words:2:pos":"noun","grammar:251:ex3:words:3:zh":"(the destination point)","grammar:251:ex3:words:3:pos":"particle","grammar:251:ex3:words:4:zh":"came up","grammar:251:ex3:words:4:note":"はいってきた","grammar:251:ex3:words:4:pos":"verb","grammar:251:ex3:points:0":"港に入る: to enter the harbor.","grammar:251:ex3:points:1":"〜てくる: to come toward here (入ってきた = came sailing in).","grammar:251:ex4:trans":"This boat is fast.","grammar:251:ex4:structure":"この船は〜です","grammar:251:ex4:words:0:zh":"this","grammar:251:ex4:words:0:pos":"pre-noun adjectival","grammar:251:ex4:words:1:zh":"boat","grammar:251:ex4:words:1:note":"ふね","grammar:251:ex4:words:1:pos":"noun","grammar:251:ex4:words:2:zh":"(topic)","grammar:251:ex4:words:2:pos":"particle","grammar:251:ex4:words:3:zh":"fast","grammar:251:ex4:words:3:note":"はやい","grammar:251:ex4:words:3:pos":"adjective","grammar:251:ex4:words:4:zh":"(polite form)","grammar:251:ex4:words:4:pos":"copula","grammar:251:ex4:points:0":"❗速い (fast in speed) vs 早い (early in time).","grammar:251:ex4:points:1":"この船: this boat.","grammar:251:ex5:trans":"We'll travel by boat.","grammar:251:ex5:structure":"〜で旅行します","grammar:251:ex5:words:0:zh":"we","grammar:251:ex5:words:0:note":"わたしたち","grammar:251:ex5:words:0:pos":"pronoun","grammar:251:ex5:words:1:zh":"(topic)","grammar:251:ex5:words:1:pos":"particle","grammar:251:ex5:words:2:zh":"boat","grammar:251:ex5:words:2:note":"ふね","grammar:251:ex5:words:2:pos":"noun","grammar:251:ex5:words:3:zh":"(means)","grammar:251:ex5:words:3:pos":"particle","grammar:251:ex5:words:4:zh":"travel / trip","grammar:251:ex5:words:4:note":"りょこうします","grammar:251:ex5:words:4:pos":"verb","grammar:251:ex5:points:0":"❓で: means of transport takes で (by boat).","grammar:251:ex5:points:1":"船で旅行する: to travel by boat."},"252":{"example:252:exzh":"This machine is new.","example:252:exzh2":"There are many machines in the factory.","example:252:exzh3":"It's a job repairing machines.","example:252:exzh4":"He knows a lot about machines.","example:252:exzh5":"This machine is easy to use.","grammar:252:ex:trans":"This machine is new.","grammar:252:ex:structure":"〜は新しいです","grammar:252:ex:explain":"The key word 「機械（きかい）」 means \"machine, machinery.\" Be careful: it is homophonous with 「機会（きかい, opportunity）」—the pronunciation is identical, so only the kanji and context tell them apart. 「この機械は」 presents the topic with 「は」, and 「新しい」 is an i-adjective followed by 「です」 as a polite predicate. The whole sentence is \"This machine is new.\" Such homophones (like 機械／機会) are a common trap in Japanese listening; judge by context.","grammar:252:ex:words:0:zh":"this","grammar:252:ex:words:0:pos":"pre-noun adjectival","grammar:252:ex:words:1:zh":"machine","grammar:252:ex:words:1:note":"きかい","grammar:252:ex:words:1:pos":"noun","grammar:252:ex:words:2:zh":"(topic)","grammar:252:ex:words:2:pos":"particle","grammar:252:ex:words:3:zh":"new","grammar:252:ex:words:3:note":"あたらしい","grammar:252:ex:words:3:pos":"adjective","grammar:252:ex:words:4:zh":"(polite form)","grammar:252:ex:words:4:pos":"copula","grammar:252:ex:points:0":"❗機械（きかい）: machine, machinery (homophonous with 「機会」 = opportunity).","grammar:252:ex:points:1":"この機械: this machine.","grammar:252:ex2:trans":"There are many machines in the factory.","grammar:252:ex2:structure":"〜には〜があります (〜 has 〜)","grammar:252:ex2:words:0:zh":"factory","grammar:252:ex2:words:0:note":"こうじょう","grammar:252:ex2:words:0:pos":"noun","grammar:252:ex2:words:1:zh":"(location of existence)","grammar:252:ex2:words:1:pos":"particle","grammar:252:ex2:words:2:zh":"(contrast)","grammar:252:ex2:words:2:pos":"particle","grammar:252:ex2:words:3:zh":"a lot","grammar:252:ex2:words:3:note":"おおく","grammar:252:ex2:words:3:pos":"noun","grammar:252:ex2:words:4:zh":"'s","grammar:252:ex2:words:4:pos":"particle","grammar:252:ex2:words:5:zh":"machine","grammar:252:ex2:words:5:note":"きかい","grammar:252:ex2:words:5:pos":"noun","grammar:252:ex2:words:6:zh":"(nominative)","grammar:252:ex2:words:6:pos":"particle","grammar:252:ex2:words:7:zh":"there is / are","grammar:252:ex2:words:7:pos":"verb","grammar:252:ex2:points:0":"工場: factory.","grammar:252:ex2:points:1":"〜には〜がある: … has…, there is… in…","grammar:252:ex3:trans":"This is a job repairing machines.","grammar:252:ex3:structure":"〜を修理する仕事です","grammar:252:ex3:words:0:zh":"machine","grammar:252:ex3:words:0:note":"きかい","grammar:252:ex3:words:0:pos":"noun","grammar:252:ex3:words:1:zh":"(object marker)","grammar:252:ex3:words:1:pos":"particle","grammar:252:ex3:words:2:zh":"repair","grammar:252:ex3:words:2:note":"しゅうりする","grammar:252:ex3:words:2:pos":"verb","grammar:252:ex3:words:3:zh":"work","grammar:252:ex3:words:3:note":"しごと","grammar:252:ex3:words:3:pos":"noun","grammar:252:ex3:words:4:zh":"is","grammar:252:ex3:words:4:pos":"copula","grammar:252:ex3:points:0":"❗機械を修理する: to repair machines.","grammar:252:ex3:points:1":"〜仕事です: it's a job of …","grammar:252:ex4:trans":"He knows a lot about machines.","grammar:252:ex4:structure":"〜に詳しいです","grammar:252:ex4:words:0:zh":"he","grammar:252:ex4:words:0:note":"かれ","grammar:252:ex4:words:0:pos":"pronoun","grammar:252:ex4:words:1:zh":"(topic)","grammar:252:ex4:words:1:pos":"particle","grammar:252:ex4:words:2:zh":"machine","grammar:252:ex4:words:2:note":"きかい","grammar:252:ex4:words:2:pos":"noun","grammar:252:ex4:words:3:zh":"(object)","grammar:252:ex4:words:3:pos":"particle","grammar:252:ex4:words:4:zh":"familiar with","grammar:252:ex4:words:4:note":"くわしい","grammar:252:ex4:words:4:pos":"adjective","grammar:252:ex4:words:5:zh":"(polite form)","grammar:252:ex4:words:5:pos":"copula","grammar:252:ex4:points:0":"❗〜に詳しい: to be familiar with …, to know … well.","grammar:252:ex4:points:1":"機械に詳しい: to know machines well.","grammar:252:ex5:trans":"This machine is easy to use.","grammar:252:ex5:structure":"〜は使いやすいです","grammar:252:ex5:words:0:zh":"this","grammar:252:ex5:words:0:pos":"pre-noun adjectival","grammar:252:ex5:words:1:zh":"machine","grammar:252:ex5:words:1:note":"きかい","grammar:252:ex5:words:1:pos":"noun","grammar:252:ex5:words:2:zh":"(topic)","grammar:252:ex5:words:2:pos":"particle","grammar:252:ex5:words:3:zh":"easy to use","grammar:252:ex5:words:3:note":"つかいやすい","grammar:252:ex5:words:3:pos":"adjective","grammar:252:ex5:words:4:zh":"(polite form)","grammar:252:ex5:words:4:pos":"copula","grammar:252:ex5:points:0":"❗〜やすい: easy to … (使いやすい = easy to use).","grammar:252:ex5:points:1":"使う→使いやすい。"},"253":{"example:253:exzh":"He gave love to the children.","example:253:exzh2":"It's important to give knowledge.","example:253:exzh3":"She gave her time to a friend.","example:253:exzh4":"We'll give him a special chance.","example:253:exzh5":"Thank you for giving me this experience."},"254":{"example:254:exzh":"I have work tomorrow.","example:254:exzh2":"I'll meet a friend tomorrow.","example:254:exzh3":"How's the weather tomorrow?","example:254:exzh4":"Tomorrow is a day off.","example:254:exzh5":"I'll get up early tomorrow.","grammar:254:ex:trans":"I have work tomorrow.","grammar:254:ex:structure":"明日は〜があります","grammar:254:ex:explain":"「明日（あした）」 is a time noun, and here 「は」 presents it as the topic (as for tomorrow). 「仕事が」 uses 「が」 to pick out the thing that exists, and 「あります」 is the polite form of the existence verb 「ある」, meaning \"there is.\" The whole sentence is \"there's work tomorrow.\" 「あります」 is used because 「仕事」 is an inanimate thing; the same pattern gives 「明日は約束があります」 (I have an appointment tomorrow).","grammar:254:ex:words:0:zh":"tomorrow","grammar:254:ex:words:0:note":"あした","grammar:254:ex:words:0:pos":"noun","grammar:254:ex:words:1:zh":"(topic)","grammar:254:ex:words:1:pos":"particle","grammar:254:ex:words:2:zh":"work","grammar:254:ex:words:2:note":"しごと","grammar:254:ex:words:2:pos":"noun","grammar:254:ex:words:3:zh":"(nominative)","grammar:254:ex:words:3:pos":"particle","grammar:254:ex:words:4:zh":"there is / are","grammar:254:ex:words:4:pos":"verb","grammar:254:ex:points:0":"明日（あした）: tomorrow.","grammar:254:ex:points:1":"〜があります: there is / there are…","grammar:254:ex2:trans":"I'm meeting a friend tomorrow.","grammar:254:ex2:structure":"明日、〜に会います","grammar:254:ex2:words:0:zh":"tomorrow","grammar:254:ex2:words:0:note":"あした","grammar:254:ex2:words:0:pos":"noun","grammar:254:ex2:words:1:zh":"friend","grammar:254:ex2:words:1:note":"ともだち","grammar:254:ex2:words:1:pos":"noun","grammar:254:ex2:words:2:zh":"(object)","grammar:254:ex2:words:2:pos":"particle","grammar:254:ex2:words:3:zh":"meet","grammar:254:ex2:words:3:note":"あいます","grammar:254:ex2:words:3:pos":"verb","grammar:254:ex2:points:0":"友達に会う: to meet a friend (the object of 会う takes に).","grammar:254:ex2:points:1":"明日: tomorrow (a time word placed at the start of the sentence).","grammar:254:ex3:trans":"How's the weather tomorrow?","grammar:254:ex3:structure":"〜はどうですか","grammar:254:ex3:words:0:zh":"tomorrow","grammar:254:ex3:words:0:note":"あした","grammar:254:ex3:words:0:pos":"noun","grammar:254:ex3:words:1:zh":"'s","grammar:254:ex3:words:1:pos":"particle","grammar:254:ex3:words:2:zh":"weather","grammar:254:ex3:words:2:note":"てんき","grammar:254:ex3:words:2:pos":"noun","grammar:254:ex3:words:3:zh":"(topic)","grammar:254:ex3:words:3:pos":"particle","grammar:254:ex3:words:4:zh":"how","grammar:254:ex3:words:4:pos":"question word","grammar:254:ex3:words:5:zh":"is","grammar:254:ex3:words:5:pos":"copula","grammar:254:ex3:words:6:zh":"(question)","grammar:254:ex3:words:6:pos":"particle","grammar:254:ex3:points:0":"明日の天気: tomorrow's weather.","grammar:254:ex3:points:1":"どうですか: how is it, what is it like.","grammar:254:ex4:trans":"Tomorrow is a day off.","grammar:254:ex4:structure":"明日は〜です","grammar:254:ex4:words:0:zh":"tomorrow","grammar:254:ex4:words:0:note":"あした","grammar:254:ex4:words:0:pos":"noun","grammar:254:ex4:words:1:zh":"(topic)","grammar:254:ex4:words:1:pos":"particle","grammar:254:ex4:words:2:zh":"day off","grammar:254:ex4:words:2:note":"やすみ","grammar:254:ex4:words:2:pos":"noun","grammar:254:ex4:words:3:zh":"is","grammar:254:ex4:words:3:pos":"copula","grammar:254:ex4:points:0":"休み: a day off, rest.","grammar:254:ex4:points:1":"明日は休み: tomorrow is a day off.","grammar:254:ex5:trans":"I'll get up early tomorrow.","grammar:254:ex5:structure":"明日は＋adverb＋verb in the masu-form","grammar:254:ex5:words:0:zh":"tomorrow","grammar:254:ex5:words:0:note":"あした","grammar:254:ex5:words:0:pos":"noun","grammar:254:ex5:words:1:zh":"(topic)","grammar:254:ex5:words:1:pos":"particle","grammar:254:ex5:words:2:zh":"early","grammar:254:ex5:words:2:note":"はやく; the adverb form of 早い","grammar:254:ex5:words:2:pos":"adverb","grammar:254:ex5:words:3:zh":"to get up","grammar:254:ex5:words:3:note":"おきます; the masu-form of 起きる","grammar:254:ex5:words:3:pos":"verb","grammar:254:ex5:points:0":"「明日は」 goes at the start of the sentence as the topic, stating what will be done tomorrow; for future events you use the non-past masu-form 「起きます」, not the past form 「起きました」.","grammar:254:ex5:points:1":"「早く」 is the i-adjective 「早い」 with い changed to く, turning it into an adverb that modifies the verb 「起きます」, meaning \"to get up early.\"","exam:254:zh":"Today is Monday, so tomorrow is Tuesday.","exam:254:why":"The day after today is 「明日」. 「昨日」 means yesterday, which here would be Sunday."},"255":{"example:255:exzh":"Everyone has gathered.","example:255:exzh2":"Everyone will take part in the meeting.","example:255:exzh3":"At school, everyone studies.","example:255:exzh4":"I expressed my thanks to everyone.","example:255:exzh5":"This project needs everyone's cooperation."},"256":{"example:256:exzh":"The two of us went to see a movie.","example:256:exzh2":"The two of them are friends.","example:256:exzh3":"The two of them go to the same school.","example:256:exzh4":"The two of them traveled together.","example:256:exzh5":"The two of them agreed.","grammar:256:ex:trans":"The two of us went to see a movie.","grammar:256:ex:structure":"二人で〜に行った","grammar:256:ex:explain":"「二人（ふたり）」 means \"two people,\" and adding 「で」 shows that the action is done with that number of people, as that combination; 「二人で」 means \"the two of us together, just the two of us.\" 「見に行く」 follows the pattern 「verb stem ＋に行く」, meaning \"go in order to do …,\" so 「見に行く」 equals \"go to see.\" 「映画を」 is the object of seeing. The whole sentence is \"the two of us went to see a movie.\" The 「で」 here expresses means or scope, not the place of the action.","grammar:256:ex:words:0:zh":"two people","grammar:256:ex:words:0:note":"ふたり","grammar:256:ex:words:0:pos":"noun","grammar:256:ex:words:1:zh":"(the whole group)","grammar:256:ex:words:1:pos":"particle","grammar:256:ex:words:2:zh":"movie","grammar:256:ex:words:2:note":"えいが","grammar:256:ex:words:2:pos":"noun","grammar:256:ex:words:3:zh":"(object marker)","grammar:256:ex:words:3:pos":"particle","grammar:256:ex:words:4:zh":"look","grammar:256:ex:words:4:note":"み","grammar:256:ex:words:4:pos":"noun","grammar:256:ex:words:5:zh":"(purpose)","grammar:256:ex:words:5:pos":"particle","grammar:256:ex:words:6:zh":"went","grammar:256:ex:words:6:note":"いった","grammar:256:ex:words:6:pos":"verb","grammar:256:ex:points:0":"二人で: the two of them together (で marks the manner).","grammar:256:ex:points:1":"〜に行く: to go in order to do … (見に行く = to go see).","grammar:256:ex2:trans":"These two are friends.","grammar:256:ex2:structure":"二人は〜です","grammar:256:ex2:words:0:zh":"two people","grammar:256:ex2:words:0:note":"ふたり","grammar:256:ex2:words:0:pos":"noun","grammar:256:ex2:words:1:zh":"(topic)","grammar:256:ex2:words:1:pos":"particle","grammar:256:ex2:words:2:zh":"friend","grammar:256:ex2:words:2:note":"ともだち","grammar:256:ex2:words:2:pos":"noun","grammar:256:ex2:words:3:zh":"is","grammar:256:ex2:words:3:pos":"copula","grammar:256:ex2:points:0":"二人（ふたり）: two people.","grammar:256:ex2:points:1":"友達：friend.","grammar:256:ex3:trans":"These two go to the same school.","grammar:256:ex3:structure":"〜に通っています","grammar:256:ex3:words:0:zh":"two people","grammar:256:ex3:words:0:note":"ふたり","grammar:256:ex3:words:0:pos":"noun","grammar:256:ex3:words:1:zh":"(topic)","grammar:256:ex3:words:1:pos":"particle","grammar:256:ex3:words:2:zh":"the same","grammar:256:ex3:words:2:note":"おなじ","grammar:256:ex3:words:2:pos":"pre-noun adjectival","grammar:256:ex3:words:3:zh":"school","grammar:256:ex3:words:3:note":"がっこう","grammar:256:ex3:words:3:pos":"noun","grammar:256:ex3:words:4:zh":"(object)","grammar:256:ex3:words:4:pos":"particle","grammar:256:ex3:words:5:zh":"going back and forth","grammar:256:ex3:words:5:note":"かよっています","grammar:256:ex3:words:5:pos":"verb","grammar:256:ex3:points:0":"❗〜に通う: to travel regularly to… (to school or to work; the destination takes に).","grammar:256:ex3:points:1":"同じ学校: the same school.","grammar:256:ex4:trans":"The two of them took a trip together.","grammar:256:ex4:structure":"二人で〜しました","grammar:256:ex4:words:0:zh":"they","grammar:256:ex4:words:0:note":"かれら","grammar:256:ex4:words:0:pos":"pronoun","grammar:256:ex4:words:1:zh":"(topic)","grammar:256:ex4:words:1:pos":"particle","grammar:256:ex4:words:2:zh":"two people","grammar:256:ex4:words:2:note":"ふたり","grammar:256:ex4:words:2:pos":"noun","grammar:256:ex4:words:3:zh":"(the whole group)","grammar:256:ex4:words:3:pos":"particle","grammar:256:ex4:words:4:zh":"traveled","grammar:256:ex4:words:4:note":"りょこうしました","grammar:256:ex4:words:4:pos":"verb","grammar:256:ex4:points:0":"二人で旅行する: the two of them travel together.","grammar:256:ex4:points:1":"旅行する→旅行しました (dictionary form → polite past).","grammar:256:ex5:trans":"Their opinions agreed.","grammar:256:ex5:structure":"〜が一致しました","grammar:256:ex5:words:0:zh":"two people","grammar:256:ex5:words:0:note":"ふたり","grammar:256:ex5:words:0:pos":"noun","grammar:256:ex5:words:1:zh":"'s","grammar:256:ex5:words:1:pos":"particle","grammar:256:ex5:words:2:zh":"opinion","grammar:256:ex5:words:2:note":"いけん","grammar:256:ex5:words:2:pos":"noun","grammar:256:ex5:words:3:zh":"(nominative)","grammar:256:ex5:words:3:pos":"particle","grammar:256:ex5:words:4:zh":"agreed","grammar:256:ex5:words:4:note":"いっちしました","grammar:256:ex5:words:4:pos":"verb","grammar:256:ex5:points:0":"二人の意見: the two people's opinions.","grammar:256:ex5:points:1":"一致する: to match, to agree.","exam:256:zh":"Only my older brother and I went out, so two people went out in total.","exam:256:why":"My older brother plus me makes 「二人」 in total. 「一人」 counts only one of them."},"257":{"example:257:exzh":"Please open the door.","example:257:exzh2":"When you open the window, it feels nice.","example:257:exzh3":"He opened the box.","example:257:exzh4":"It's time to open the textbook.","example:257:exzh5":"There are doors that don't get opened.","grammar:257:ex:trans":"Please open the door.","grammar:257:ex:structure":"〜を開けてください","grammar:257:ex:explain":"「開ける（あける）」 is a transitive verb meaning \"(a person) opens …,\" taking its object with 「を」; here it's 「ドアを開ける」 (to open the door). It pairs with the intransitive 「開く（あく, the door opens by itself）」: when someone opens it, use 「開ける」; when it opens on its own, use 「開く」. 「〜てください」 is a polite request, \"please …,\" formed with the verb's te-form plus ください. The whole sentence is \"Please open the door.\" Transitive/intransitive pairs are an important concept in Japanese.","grammar:257:ex:words:0:zh":"door","grammar:257:ex:words:0:note":"loanword","grammar:257:ex:words:0:pos":"noun","grammar:257:ex:words:1:zh":"(object marker)","grammar:257:ex:words:1:pos":"particle","grammar:257:ex:words:2:zh":"open","grammar:257:ex:words:2:note":"あけて","grammar:257:ex:words:2:pos":"verb","grammar:257:ex:words:3:zh":"please","grammar:257:ex:words:3:pos":"auxiliary verb","grammar:257:ex:points:0":"❗開ける (transitive verb, to open …) + を; vs 開く (intransitive verb).","grammar:257:ex:points:1":"ドアを開ける: to open the door.","grammar:257:ex2:trans":"When you open the window, it feels nice.","grammar:257:ex2:structure":"〜を開けると、〜がいい","grammar:257:ex2:words:0:zh":"window","grammar:257:ex2:words:0:note":"まど","grammar:257:ex2:words:0:pos":"noun","grammar:257:ex2:words:1:zh":"(object marker)","grammar:257:ex2:words:1:pos":"particle","grammar:257:ex2:words:2:zh":"open","grammar:257:ex2:words:2:note":"あける","grammar:257:ex2:words:2:pos":"verb","grammar:257:ex2:words:3:zh":"(as soon as…)","grammar:257:ex2:words:3:pos":"particle","grammar:257:ex2:words:4:zh":"feeling","grammar:257:ex2:words:4:note":"きもち","grammar:257:ex2:words:4:pos":"noun","grammar:257:ex2:words:5:zh":"(nominative)","grammar:257:ex2:words:5:pos":"particle","grammar:257:ex2:words:6:zh":"good","grammar:257:ex2:words:6:pos":"adjective","grammar:257:ex2:points:0":"❗〜と: as soon as …, then …","grammar:257:ex2:points:1":"❗気持ちがいい: pleasant, feels good.","grammar:257:ex3:trans":"He opened the box.","grammar:257:ex3:structure":"〜を開けた","grammar:257:ex3:words:0:zh":"he","grammar:257:ex3:words:0:note":"かれ","grammar:257:ex3:words:0:pos":"pronoun","grammar:257:ex3:words:1:zh":"(topic)","grammar:257:ex3:words:1:pos":"particle","grammar:257:ex3:words:2:zh":"box","grammar:257:ex3:words:2:note":"はこ","grammar:257:ex3:words:2:pos":"noun","grammar:257:ex3:words:3:zh":"(object marker)","grammar:257:ex3:words:3:pos":"particle","grammar:257:ex3:words:4:zh":"opened","grammar:257:ex3:words:4:note":"あけた","grammar:257:ex3:words:4:pos":"verb","grammar:257:ex3:points:0":"箱を開ける: to open a box.","grammar:257:ex3:points:1":"開ける→開けた。","grammar:257:ex4:trans":"It's time to open the textbook.","grammar:257:ex4:structure":"〜を開ける時間です","grammar:257:ex4:words:0:zh":"textbook","grammar:257:ex4:words:0:note":"きょうかしょ","grammar:257:ex4:words:0:pos":"noun","grammar:257:ex4:words:1:zh":"(object marker)","grammar:257:ex4:words:1:pos":"particle","grammar:257:ex4:words:2:zh":"open","grammar:257:ex4:words:2:note":"あける","grammar:257:ex4:words:2:pos":"verb","grammar:257:ex4:words:3:zh":"time","grammar:257:ex4:words:3:note":"じかん","grammar:257:ex4:words:3:pos":"noun","grammar:257:ex4:words:4:zh":"(polite form)","grammar:257:ex4:words:4:pos":"copula","grammar:257:ex4:points:0":"❗「本を開ける」 is also often said as 「本を開く（ひらく）」.","grammar:257:ex4:points:1":"教科書: textbook.","grammar:257:ex5:trans":"There are doors you don't open.","grammar:257:ex5:structure":"開けない〜がある","grammar:257:ex5:words:0:zh":"won't open / can't open","grammar:257:ex5:words:0:note":"あけない","grammar:257:ex5:words:0:pos":"verb","grammar:257:ex5:words:1:zh":"door","grammar:257:ex5:words:1:note":"loanword","grammar:257:ex5:words:1:pos":"noun","grammar:257:ex5:words:2:zh":"(nominative)","grammar:257:ex5:words:2:pos":"particle","grammar:257:ex5:words:3:zh":"there is / are","grammar:257:ex5:words:3:pos":"verb","grammar:257:ex5:points:0":"❗開けない: won't open (negative); for \"can't open,\" use 「開けられない」 (negative potential).","grammar:257:ex5:points:1":"ドアがある: there is a door.","exam:257:zh":"If you open the closed window, the wind from outside comes into the room.","exam:257:why":"To let the wind come in through the window, you need to 「開ける」 it. 「閉める」 means to close, the opposite of the action needed here."},"260":{"example:260:exzh":"What kind of guy is this?","example:260:exzh2":"Do you know this guy?","example:260:exzh3":"It's fun when this guy comes.","example:260:exzh4":"I want to get close to this guy.","example:260:exzh5":"This guy is amazing."},"261":{"example:261:exzh":"This is exactly the book I was looking for.","example:261:exzh2":"He is a true friend."},"262":{"example:262:exzh":"He keeps quiet.","example:262:exzh2":"I want him to be quiet.","example:262:exzh3":"Please listen quietly to what I'm saying."},"263":{"example:263:exzh":"I'm busy. In other words, I can't go.","example:263:exzh2":"He's a student. In other words, he's studying."},"264":{"example:264:exzh":"He's going to take an exam.","example:264:exzh2":"I want to take that job.","grammar:264:ex:trans":"He will take an exam.","grammar:264:ex:structure":"〜を受ける","grammar:264:ex:explain":"「受ける（うける）」 basically means \"to receive, to undergo,\" but 「試験を受ける」 is a fixed collocation meaning \"to take an exam, to sit for an exam\"—it doesn't mean literally catching the exam—and the object is marked with 「を」. So 「彼は試験を受ける」 simply means \"He will take an exam.\" The meaning of 「受ける」 changes with its object, as in 「授業を受ける」 (to take a class) and 「影響を受ける」 (to be affected); learn these as idiomatic combinations.","grammar:264:ex:words:0:zh":"he","grammar:264:ex:words:0:note":"かれ","grammar:264:ex:words:0:pos":"pronoun","grammar:264:ex:words:1:zh":"(topic)","grammar:264:ex:words:1:pos":"particle","grammar:264:ex:words:2:zh":"test","grammar:264:ex:words:2:note":"しけん","grammar:264:ex:words:2:pos":"noun","grammar:264:ex:words:3:zh":"(object marker)","grammar:264:ex:words:3:pos":"particle","grammar:264:ex:words:4:zh":"to receive, to take","grammar:264:ex:words:4:note":"うける","grammar:264:ex:words:4:pos":"verb","grammar:264:ex:points:0":"❗試験を受ける: to take an exam (idiomatic use of 受ける).","grammar:264:ex:points:1":"受ける: to receive, to undergo.","grammar:264:ex2:trans":"I want to take that job.","grammar:264:ex2:structure":"〜を受けたい","grammar:264:ex2:words:0:zh":"that","grammar:264:ex2:words:0:pos":"pre-noun adjectival","grammar:264:ex2:words:1:zh":"work","grammar:264:ex2:words:1:note":"しごと","grammar:264:ex2:words:1:pos":"noun","grammar:264:ex2:words:2:zh":"(object marker)","grammar:264:ex2:words:2:pos":"particle","grammar:264:ex2:words:3:zh":"want to take","grammar:264:ex2:words:3:note":"うけたい","grammar:264:ex2:words:3:pos":"verb","grammar:264:ex2:points:0":"❗仕事を受ける: to take on a job.","grammar:264:ex2:points:1":"〜たい: to want to …."},"265":{"example:265:exzh":"I passed the message on to him.","example:265:exzh2":"I have to tell someone about this.","grammar:265:ex:trans":"I passed the message on to him.","grammar:265:ex:structure":"〜に〜を伝えた","grammar:265:ex:explain":"「伝える（つたえる）」 is the transitive verb \"to convey, to pass on,\" and it takes two objects: the person you convey to is marked with 「に」 (彼に = to him), and the content you convey with 「を」 (メッセージを = the message). 「伝えた」 is the plain past. The whole sentence is \"I passed the message on to him.\" Note that 「に」 here marks the recipient of the message; this 「〜に〜を」 giving/transfer structure is very common in Japanese.","grammar:265:ex:words:0:zh":"I","grammar:265:ex:words:0:note":"わたし","grammar:265:ex:words:0:pos":"pronoun","grammar:265:ex:words:1:zh":"(topic)","grammar:265:ex:words:1:pos":"particle","grammar:265:ex:words:2:zh":"he","grammar:265:ex:words:2:note":"かれ","grammar:265:ex:words:2:pos":"pronoun","grammar:265:ex:words:3:zh":"(object)","grammar:265:ex:words:3:pos":"particle","grammar:265:ex:words:4:zh":"news","grammar:265:ex:words:4:note":"loanword","grammar:265:ex:words:4:pos":"noun","grammar:265:ex:words:5:zh":"(object marker)","grammar:265:ex:words:5:pos":"particle","grammar:265:ex:words:6:zh":"conveyed","grammar:265:ex:words:6:note":"つたえた","grammar:265:ex:words:6:pos":"verb","grammar:265:ex:points:0":"❗〜に〜を伝える: to convey … to … (the recipient is marked with に).","grammar:265:ex:points:1":"メッセージを伝える: to pass on a message.","grammar:265:ex2:trans":"I have to tell someone about this.","grammar:265:ex2:structure":"〜に〜なければならない","grammar:265:ex2:words:0:zh":"this","grammar:265:ex2:words:0:pos":"pre-noun adjectival","grammar:265:ex2:words:1:zh":"thing / matter","grammar:265:ex2:words:1:pos":"noun","grammar:265:ex2:words:2:zh":"(object marker)","grammar:265:ex2:words:2:pos":"particle","grammar:265:ex2:words:3:zh":"someone","grammar:265:ex2:words:3:note":"だれか","grammar:265:ex2:words:3:pos":"pronoun","grammar:265:ex2:words:4:zh":"(object)","grammar:265:ex2:words:4:pos":"particle","grammar:265:ex2:words:5:zh":"must convey","grammar:265:ex2:words:5:note":"つたえなければならない","grammar:265:ex2:words:5:pos":"verb","grammar:265:ex2:points:0":"❗〜なければならない: must ...","grammar:265:ex2:points:1":"誰かに伝える: to tell someone."},"269":{"example:269:exzh":"Work takes time.","example:269:exzh2":"It costs money.","example:269:exzh3":"It takes time.","example:269:exzh4":"It costs in all sorts of ways.","example:269:exzh5":"Sometimes that's how much it takes.","grammar:269:ex:trans":"Work takes a lot of time.","grammar:269:ex:structure":"noun + に + 時間 + が + かかる. 「〜に時間がかかる」 = to spend time on…","grammar:269:ex:explain":"「かかる」 is an intransitive verb meaning to take (time or money), and the amount spent is marked with 「が」. 「〜に時間がかかる」 is a set pattern meaning to take time on…, so 「仕事に時間がかかる」 means work takes a lot of time. Here 「に」 marks the thing the time is being spent on. Note that the real subject of taking time is 「時間」, which is why 「が」 is used; this is the reverse of what many learners expect, and it is a common beginner mistake.","grammar:269:ex:words:0:zh":"work","grammar:269:ex:words:0:note":"しごと","grammar:269:ex:words:0:pos":"noun","grammar:269:ex:words:1:zh":"(target / purpose)","grammar:269:ex:words:1:pos":"particle","grammar:269:ex:words:2:zh":"time","grammar:269:ex:words:2:note":"じかん","grammar:269:ex:words:2:pos":"noun","grammar:269:ex:words:3:zh":"(nominative)","grammar:269:ex:words:3:pos":"particle","grammar:269:ex:words:4:zh":"to take (time)","grammar:269:ex:words:4:note":"dictionary form；takes time/money","grammar:269:ex:words:4:pos":"verb","grammar:269:ex:points:0":"〜がかかる: to take (time/money)","grammar:269:ex:points:1":"仕事に時間がかかる: work takes time","grammar:269:ex2:trans":"It costs money.","grammar:269:ex2:structure":"お金 + が + かかる. 「お金がかかる」 = to cost money / to be costly.","grammar:269:ex2:words:0:zh":"money","grammar:269:ex2:words:0:note":"おかね","grammar:269:ex2:words:0:pos":"noun","grammar:269:ex2:words:1:zh":"(nominative)","grammar:269:ex2:words:1:pos":"particle","grammar:269:ex2:words:2:zh":"to take (time)","grammar:269:ex2:words:2:note":"money is spent","grammar:269:ex2:words:2:pos":"verb","grammar:269:ex2:points:0":"お金がかかる: to cost money","grammar:269:ex2:points:1":"かかる: (cost/time) to arise, to be required","grammar:269:ex3:trans":"It took time.","grammar:269:ex3:structure":"時間 + が + かかる. The most basic takes-time pattern.","grammar:269:ex3:words:0:zh":"time","grammar:269:ex3:words:0:note":"じかん","grammar:269:ex3:words:0:pos":"noun","grammar:269:ex3:words:1:zh":"(nominative)","grammar:269:ex3:words:1:pos":"particle","grammar:269:ex3:words:2:zh":"to take (time)","grammar:269:ex3:words:2:note":"dictionary form","grammar:269:ex3:words:2:pos":"verb","grammar:269:ex3:points:0":"時間がかかる: takes time, is time-consuming","grammar:269:ex3:points:1":"が marks the thing that is spent","grammar:269:ex4:trans":"It costs in all sorts of ways.","grammar:269:ex4:structure":"adverb + かかる. 「色々と」 modifies the verb, meaning in various ways (spent / occurring).","grammar:269:ex4:words:0:zh":"in various ways","grammar:269:ex4:words:0:note":"iroiro to；adverb usage","grammar:269:ex4:words:0:pos":"adverb","grammar:269:ex4:words:1:zh":"to be spent / to arise","grammar:269:ex4:words:1:note":"dictionary form","grammar:269:ex4:words:1:pos":"verb","grammar:269:ex4:points:0":"色々と: in all sorts of ways (adverb)","grammar:269:ex4:points:1":"かかる: to cost / to be involved (depending on context)","grammar:269:ex5:trans":"Sometimes that much is required.","grammar:269:ex5:structure":"〜verb + ことがある. 「〜ことがある」 means sometimes (it) happens that…","grammar:269:ex5:words:0:zh":"that","grammar:269:ex5:words:0:pos":"pronoun","grammar:269:ex5:words:1:zh":"(nominative)","grammar:269:ex5:words:1:pos":"particle","grammar:269:ex5:words:2:zh":"to cost / to affect","grammar:269:ex5:words:2:note":"dictionary form","grammar:269:ex5:words:2:pos":"verb","grammar:269:ex5:words:3:zh":"(nominalizer)","grammar:269:ex5:words:3:pos":"noun","grammar:269:ex5:words:4:zh":"(nominative)","grammar:269:ex5:words:4:pos":"particle","grammar:269:ex5:words:5:zh":"there is / are","grammar:269:ex5:words:5:note":"〜ことがある = sometimes does","grammar:269:ex5:words:5:pos":"verb","grammar:269:ex5:points:0":"〜ことがある: sometimes… (expresses occasional occurrence)","grammar:269:ex5:points:1":"こと nominalizes + がある"},"271":{"example:271:exzh":"I like horses.","example:271:exzh2":"A horse is running.","example:271:exzh3":"He's a horse rider.","example:271:exzh4":"Horses are fast animals.","example:271:exzh5":"Take care of the horse.","grammar:271:ex:trans":"I like horses.","grammar:271:ex:structure":"〜が好きです","grammar:271:ex:explain":"When expressing likes and dislikes, the thing you like takes 「が」 rather than 「を」—an important rule in Japanese. 「馬が好き」 means \"to like horses.\" 「私は」 presents the subject (I) with 「は」, and 「馬が」 marks what is liked. 「好き」 is a na-adjective followed by 「です」 as a polite predicate. The whole sentence is \"I like horses.\" Words expressing ability or desire, such as 「上手」, 「欲しい」, and 「わかる」, likewise tend to take 「が」 for their object.","grammar:271:ex:words:0:zh":"I","grammar:271:ex:words:0:note":"わたし","grammar:271:ex:words:0:pos":"pronoun","grammar:271:ex:words:1:zh":"(topic)","grammar:271:ex:words:1:pos":"particle","grammar:271:ex:words:2:zh":"horse","grammar:271:ex:words:2:note":"うま","grammar:271:ex:words:2:pos":"noun","grammar:271:ex:words:3:zh":"(object)","grammar:271:ex:words:3:pos":"particle","grammar:271:ex:words:4:zh":"to like","grammar:271:ex:words:4:note":"すき","grammar:271:ex:words:4:pos":"na-adjective","grammar:271:ex:words:5:zh":"(polite form)","grammar:271:ex:words:5:pos":"copula","grammar:271:ex:points:0":"❗馬（うま）: horse.","grammar:271:ex:points:1":"〜が好き: to like …","grammar:271:ex2:trans":"The horse is running.","grammar:271:ex2:structure":"〜が走っている","grammar:271:ex2:words:0:zh":"horse","grammar:271:ex2:words:0:note":"うま","grammar:271:ex2:words:0:pos":"noun","grammar:271:ex2:words:1:zh":"(nominative)","grammar:271:ex2:words:1:pos":"particle","grammar:271:ex2:words:2:zh":"running","grammar:271:ex2:words:2:note":"はしっている","grammar:271:ex2:words:2:pos":"verb","grammar:271:ex2:points:0":"馬が走る: the horse runs (intransitive verbs take が).","grammar:271:ex2:points:1":"〜ている: ongoing action.","grammar:271:ex3:trans":"He is a horseback rider.","grammar:271:ex3:structure":"〜は馬乗り","grammar:271:ex3:words:0:zh":"he","grammar:271:ex3:words:0:note":"かれ","grammar:271:ex3:words:0:pos":"pronoun","grammar:271:ex3:words:1:zh":"(topic)","grammar:271:ex3:words:1:pos":"particle","grammar:271:ex3:words:2:zh":"horseback rider","grammar:271:ex3:words:2:note":"うまのり","grammar:271:ex3:words:2:pos":"noun","grammar:271:ex3:points:0":"❗馬乗り: horseback riding (rider) (馬 + 乗り).","grammar:271:ex3:points:1":"彼は馬乗り: he can ride a horse.","grammar:271:ex4:trans":"A horse is a fast animal.","grammar:271:ex4:structure":"〜は速いです","grammar:271:ex4:words:0:zh":"horse","grammar:271:ex4:words:0:note":"うま","grammar:271:ex4:words:0:pos":"noun","grammar:271:ex4:words:1:zh":"(topic)","grammar:271:ex4:words:1:pos":"particle","grammar:271:ex4:words:2:zh":"fast","grammar:271:ex4:words:2:note":"はやい","grammar:271:ex4:words:2:pos":"adjective","grammar:271:ex4:words:3:zh":"(polite form)","grammar:271:ex4:words:3:pos":"copula","grammar:271:ex4:points:0":"❗速い (はやい): fast (speed); vs 早い (early in time).","grammar:271:ex4:points:1":"馬は速い: horses run fast.","grammar:271:ex5:trans":"Look after a horse.","grammar:271:ex5:structure":"〜の世話をする","grammar:271:ex5:words:0:zh":"horse","grammar:271:ex5:words:0:note":"うま","grammar:271:ex5:words:0:pos":"noun","grammar:271:ex5:words:1:zh":"'s","grammar:271:ex5:words:1:pos":"particle","grammar:271:ex5:words:2:zh":"look after","grammar:271:ex5:words:2:note":"せわ","grammar:271:ex5:words:2:pos":"noun","grammar:271:ex5:words:3:zh":"(object marker)","grammar:271:ex5:words:3:pos":"particle","grammar:271:ex5:words:4:zh":"do","grammar:271:ex5:words:4:pos":"verb","grammar:271:ex5:points:0":"❗世話をする: to look after, to take care of (set phrase).","grammar:271:ex5:points:1":"馬の世話: looking after a horse."},"272":{"example:272:exzh":"Head for school.","example:272:exzh2":"I'm heading home.","example:272:exzh3":"Head south.","example:272:exzh4":"Head for the destination.","example:272:exzh5":"Advance toward the road."},"274":{"example:274:exzh":"Take the bus.","example:274:exzh2":"I'm on the train.","example:274:exzh3":"Take the elevator.","example:274:exzh4":"Take a taxi.","example:274:exzh5":"I plan to fly.","grammar:274:ex:trans":"Take the bus.","grammar:274:ex:structure":"〜に乗る","grammar:274:ex:explain":"「乗る（のる）」 means to board or get on a means of transport. The key point here is that the particle is 「に」, not 「を」: the vehicle you board is marked with 「に」, so 「バスに乗る」 means to get on the bus. Learners often get this wrong because the Chinese verb for ride feels like a transitive verb. Conversely, getting off takes 「を」 (「バスを降りる」). The whole sentence means to ride the bus. Memory hook: 「乗る」 is movement toward the point that is the vehicle, so it takes 「に」.","grammar:274:ex:words:0:zh":"bus","grammar:274:ex:words:0:note":"loanword","grammar:274:ex:words:0:pos":"noun","grammar:274:ex:words:1:zh":"(object)","grammar:274:ex:words:1:pos":"particle","grammar:274:ex:words:2:zh":"to ride, to board","grammar:274:ex:words:2:note":"のる","grammar:274:ex:words:2:pos":"verb","grammar:274:ex:points:0":"❗乗る takes に: means of transport takes に (バスに乗る).","grammar:274:ex:points:1":"乗る: to board, to get on.","grammar:274:ex2:trans":"Riding the train.","grammar:274:ex2:structure":"〜に乗っている","grammar:274:ex2:words:0:zh":"train","grammar:274:ex2:words:0:note":"でんしゃ","grammar:274:ex2:words:0:pos":"noun","grammar:274:ex2:words:1:zh":"(object)","grammar:274:ex2:words:1:pos":"particle","grammar:274:ex2:words:2:zh":"riding, on board","grammar:274:ex2:words:2:note":"のっている","grammar:274:ex2:words:2:pos":"verb","grammar:274:ex2:points:0":"電車に乗る: to ride the train.","grammar:274:ex2:points:1":"〜ている: in progress (in the middle of a ride).","grammar:274:ex3:trans":"Take the elevator.","grammar:274:ex3:structure":"〜に乗る","grammar:274:ex3:words:0:zh":"elevator","grammar:274:ex3:words:0:note":"loanword","grammar:274:ex3:words:0:pos":"noun","grammar:274:ex3:words:1:zh":"(object)","grammar:274:ex3:words:1:pos":"particle","grammar:274:ex3:words:2:zh":"to ride, to board","grammar:274:ex3:words:2:note":"のる","grammar:274:ex3:words:2:pos":"verb","grammar:274:ex3:points:0":"エレベーターに乗る: to take the elevator.","grammar:274:ex3:points:1":"に: the thing you get on.","grammar:274:ex4:trans":"Take a taxi.","grammar:274:ex4:structure":"〜に乗る","grammar:274:ex4:words:0:zh":"taxi","grammar:274:ex4:words:0:note":"loanword","grammar:274:ex4:words:0:pos":"noun","grammar:274:ex4:words:1:zh":"(object)","grammar:274:ex4:words:1:pos":"particle","grammar:274:ex4:words:2:zh":"to ride, to board","grammar:274:ex4:words:2:note":"のる","grammar:274:ex4:words:2:pos":"verb","grammar:274:ex4:points:0":"タクシーに乗る: to take a taxi.","grammar:274:ex4:points:1":"乗る: to board, to take.","grammar:274:ex5:trans":"Scheduled to take a plane.","grammar:274:ex5:structure":"〜に乗る予定だ","grammar:274:ex5:words:0:zh":"plane","grammar:274:ex5:words:0:note":"ひこうき","grammar:274:ex5:words:0:pos":"noun","grammar:274:ex5:words:1:zh":"(object)","grammar:274:ex5:words:1:pos":"particle","grammar:274:ex5:words:2:zh":"to ride, to board","grammar:274:ex5:words:2:note":"のる","grammar:274:ex5:words:2:pos":"verb","grammar:274:ex5:words:3:zh":"plan","grammar:274:ex5:words:3:note":"よてい","grammar:274:ex5:words:3:pos":"noun","grammar:274:ex5:words:4:zh":"is","grammar:274:ex5:words:4:pos":"copula","grammar:274:ex5:points:0":"飛行機に乗る: to take a plane.","grammar:274:ex5:points:1":"〜予定だ: be scheduled to…, plan to…","exam:274:zh":"My house is far from the station, so I decided to take the bus when I go there.","exam:274:why":"Riding a means of transport is 「バスに乗る」. 「降りる」 means getting off, and you usually say 「バスを降りる」."},"276":{"example:276:exzh":"That's not okay.","example:276:exzh2":"Not here.","example:276:exzh3":"You can't take photos here.","example:276:exzh4":"I was told it's not allowed.","example:276:exzh5":"That's a bad thing.","grammar:276:ex:trans":"That's not allowed.","grammar:276:ex:structure":"〜はだめです","grammar:276:ex:explain":"「だめ（駄目）」 is a na-adjective meaning no good, not allowed, or useless; it can express prohibition, denial, or that something is broken. 「それはだめです」 means that's not okay, that won't do. In 「それは」, 「は」 marks the topic, and 「です」 is the polite form. This is a very common casual expression, less formal than 「いけません」. To give permission you say 「いいです」 (that's fine), the exact opposite. In writing it is often written in katakana as 「ダメ」.","grammar:276:ex:words:0:zh":"that","grammar:276:ex:words:0:pos":"pronoun","grammar:276:ex:words:1:zh":"(topic)","grammar:276:ex:words:1:pos":"particle","grammar:276:ex:words:2:zh":"no good","grammar:276:ex:words:2:pos":"na-adjective","grammar:276:ex:words:3:zh":"(polite form)","grammar:276:ex:words:3:pos":"copula","grammar:276:ex:points:0":"だめ: no good, not allowed (na-adjective, = ダメ).","grammar:276:ex:points:1":"それはだめです: that's not allowed.","grammar:276:ex2:trans":"Not allowed here.","grammar:276:ex2:structure":"〜でだめ","grammar:276:ex2:words:0:zh":"here","grammar:276:ex2:words:0:pos":"pronoun","grammar:276:ex2:words:1:zh":"(place)","grammar:276:ex2:words:1:pos":"particle","grammar:276:ex2:words:2:zh":"no good","grammar:276:ex2:words:2:pos":"na-adjective","grammar:276:ex2:points:0":"ここでだめ: not okay here (で marks the place).","grammar:276:ex2:points:1":"だめ: not allowed.","grammar:276:ex3:trans":"You're not allowed to take photos here, you know.","grammar:276:ex3:structure":"〜のはだめです","grammar:276:ex3:words:0:zh":"here","grammar:276:ex3:words:0:pos":"pronoun","grammar:276:ex3:words:1:zh":"at / in (place of action)","grammar:276:ex3:words:1:pos":"particle","grammar:276:ex3:words:2:zh":"photo","grammar:276:ex3:words:2:note":"しゃしん","grammar:276:ex3:words:2:pos":"noun","grammar:276:ex3:words:3:zh":"(object)","grammar:276:ex3:words:3:pos":"particle","grammar:276:ex3:words:4:zh":"take (a photo)","grammar:276:ex3:words:4:note":"とる","grammar:276:ex3:words:4:pos":"verb","grammar:276:ex3:words:5:zh":"(turns the action into a noun)","grammar:276:ex3:words:5:pos":"formal noun","grammar:276:ex3:words:6:zh":"(topic)","grammar:276:ex3:words:6:pos":"particle","grammar:276:ex3:words:7:zh":"no good, not allowed","grammar:276:ex3:words:7:pos":"na-adjective","grammar:276:ex3:words:8:zh":"(polite form)","grammar:276:ex3:words:8:pos":"copula","grammar:276:ex3:words:9:zh":"(reminder tone)","grammar:276:ex3:words:9:pos":"particle","grammar:276:ex3:points:0":"「撮るのはだめです」: 「だめ」 marks prohibition; it's more casual than 「いけません」 and is often said to friends or children.","grammar:276:ex3:points:1":"The 「の」 in 「撮るの」 turns the verb into a noun, so 「〜のは」 means the act of doing…","grammar:276:ex3:points:2":"The sentence-final 「よ」 points out something the listener doesn't know, with a tone like you know / just so you know.","grammar:276:ex4:trans":"Was told that it's no good.","grammar:276:ex4:structure":"〜だと言われた","grammar:276:ex4:words:0:zh":"no good","grammar:276:ex4:words:0:pos":"na-adjective","grammar:276:ex4:words:1:zh":"is","grammar:276:ex4:words:1:pos":"copula","grammar:276:ex4:words:2:zh":"(quotation)","grammar:276:ex4:words:2:pos":"particle","grammar:276:ex4:words:3:zh":"is said","grammar:276:ex4:words:3:note":"いわれた (passive form)","grammar:276:ex4:words:3:pos":"verb","grammar:276:ex4:points:0":"〜と言われた: was told that… (passive form).","grammar:276:ex4:points:1":"だめだ: it's no good (plain-form copula).","grammar:276:ex5:trans":"That's a bad thing.","grammar:276:ex5:structure":"〜はだめなことだ","grammar:276:ex5:words:0:zh":"that","grammar:276:ex5:words:0:pos":"pronoun","grammar:276:ex5:words:1:zh":"(topic)","grammar:276:ex5:words:1:pos":"particle","grammar:276:ex5:words:2:zh":"no good","grammar:276:ex5:words:2:pos":"na-adjective","grammar:276:ex5:words:3:zh":"(attributive form)","grammar:276:ex5:words:3:pos":"auxiliary verb","grammar:276:ex5:words:4:zh":"thing / matter","grammar:276:ex5:words:4:pos":"noun","grammar:276:ex5:words:5:zh":"is","grammar:276:ex5:words:5:pos":"copula","grammar:276:ex5:points:0":"だめなこと: something that's not okay (な + noun).","grammar:276:ex5:points:1":"こと: thing, matter."},"277":{"example:277:exzh":"That's correct.","example:277:exzh2":"The correct answer.","example:277:exzh3":"The right choice.","example:277:exzh4":"Correctness is necessary.","example:277:exzh5":"He's an upright person.","grammar:277:ex:trans":"That is correct.","grammar:277:ex:structure":"〜は正しい","grammar:277:ex:explain":"「正しい（ただしい）」 is an i-adjective meaning correct, right, proper. 「それは正しい」 means that is right. 「それは」 presents the topic with 「は」, and the sentence ends directly with the i-adjective 「正しい」 in the plain form (with no です). The whole sentence means that is correct. To be more polite, add 「です」 to get 「正しいです」. The opposite is 「間違っている」 (wrong) or 「正しくない」 (not correct).","grammar:277:ex:words:0:zh":"that","grammar:277:ex:words:0:pos":"pronoun","grammar:277:ex:words:1:zh":"(topic)","grammar:277:ex:words:1:pos":"particle","grammar:277:ex:words:2:zh":"correct","grammar:277:ex:words:2:note":"ただしい","grammar:277:ex:words:2:pos":"adjective","grammar:277:ex:points:0":"❗正しい (ただしい): correct, right, proper.","grammar:277:ex:points:1":"それは正しい: that is right.","grammar:277:ex2:trans":"The correct answer.","grammar:277:ex2:structure":"正しい〜","grammar:277:ex2:words:0:zh":"correct","grammar:277:ex2:words:0:note":"ただしい","grammar:277:ex2:words:0:pos":"adjective","grammar:277:ex2:words:1:zh":"answer","grammar:277:ex2:words:1:note":"こたえ","grammar:277:ex2:words:1:pos":"noun","grammar:277:ex2:points:0":"正しい答え: the correct answer (attributive use).","grammar:277:ex2:points:1":"答え: answer.","grammar:277:ex3:trans":"The right choice.","grammar:277:ex3:structure":"正しい〜","grammar:277:ex3:words:0:zh":"correct","grammar:277:ex3:words:0:note":"ただしい","grammar:277:ex3:words:0:pos":"adjective","grammar:277:ex3:words:1:zh":"choice","grammar:277:ex3:words:1:note":"せんたく","grammar:277:ex3:words:1:pos":"noun","grammar:277:ex3:points:0":"正しい選択: the right choice.","grammar:277:ex3:points:1":"選択: choice.","grammar:277:ex4:trans":"Correctness is needed.","grammar:277:ex4:structure":"〜が必要","grammar:277:ex4:words:0:zh":"correctness","grammar:277:ex4:words:0:note":"ただしさ","grammar:277:ex4:words:0:pos":"noun","grammar:277:ex4:words:1:zh":"(nominative)","grammar:277:ex4:words:1:pos":"particle","grammar:277:ex4:words:2:zh":"necessary","grammar:277:ex4:words:2:note":"ひつよう","grammar:277:ex4:words:2:pos":"na-adjective","grammar:277:ex4:points:0":"❗正しさ: correctness (正しい → 正しさ, nominalized).","grammar:277:ex4:points:1":"〜が必要: … is needed.","grammar:277:ex5:trans":"He is an upright person.","grammar:277:ex5:structure":"〜は正しい〜だ","grammar:277:ex5:words:0:zh":"he","grammar:277:ex5:words:0:note":"かれ","grammar:277:ex5:words:0:pos":"pronoun","grammar:277:ex5:words:1:zh":"(topic)","grammar:277:ex5:words:1:pos":"particle","grammar:277:ex5:words:2:zh":"honest","grammar:277:ex5:words:2:note":"ただしい","grammar:277:ex5:words:2:pos":"adjective","grammar:277:ex5:words:3:zh":"person","grammar:277:ex5:words:3:note":"ひと","grammar:277:ex5:words:3:pos":"noun","grammar:277:ex5:words:4:zh":"is","grammar:277:ex5:words:4:pos":"copula","grammar:277:ex5:points:0":"❗正しい人: an honest person (正しい also means being upright in character).","grammar:277:ex5:points:1":"彼は正しい人: he is an honest person."},"278":{"example:278:exzh":"Go to bed early.","example:278:exzh2":"It's time to sleep.","example:278:exzh3":"He's already asleep.","example:278:exzh4":"I like sleeping.","example:278:exzh5":"I go to bed early every day.","grammar:278:ex:trans":"Go to bed early.","grammar:278:ex:structure":"早く寝る","grammar:278:ex:explain":"「寝る（ねる）」 is an ichidan (ru-) verb meaning to sleep, to go to bed, to lie down. The preceding 「早く」 is the adverb early, formed from the i-adjective 「早い」 by dropping い and adding く, and it modifies the verb. 「早く寝る」 means to go to bed early. The sentence is in plain form. Note that 「寝る」 is an ichidan (ru-) verb: when conjugating, drop 「る」 and add ます and so on (寝ます, 寝て) — don't mistake it for a godan (u-) verb. The related 「起きる」 (to get up) is also ichidan.","grammar:278:ex:words:0:zh":"early (as an adverb)","grammar:278:ex:words:0:note":"はやく","grammar:278:ex:words:0:pos":"adverb","grammar:278:ex:words:1:zh":"sleep","grammar:278:ex:words:1:note":"ねる","grammar:278:ex:words:1:pos":"verb","grammar:278:ex:points:0":"寝る: to sleep (ichidan (ru-) verb).","grammar:278:ex:points:1":"早く: early, in an early manner (早い→早く).","grammar:278:ex2:trans":"It's time for bed.","grammar:278:ex2:structure":"〜時間だ","grammar:278:ex2:words:0:zh":"sleep","grammar:278:ex2:words:0:note":"ねる","grammar:278:ex2:words:0:pos":"verb","grammar:278:ex2:words:1:zh":"time","grammar:278:ex2:words:1:note":"じかん","grammar:278:ex2:words:1:pos":"noun","grammar:278:ex2:words:2:zh":"is","grammar:278:ex2:words:2:pos":"copula","grammar:278:ex2:points:0":"寝る時間: time to sleep, bedtime (verb in attributive form).","grammar:278:ex2:points:1":"〜時間だ: it's time to…","grammar:278:ex3:trans":"He's already asleep.","grammar:278:ex3:structure":"もう〜ている","grammar:278:ex3:words:0:zh":"he","grammar:278:ex3:words:0:note":"かれ","grammar:278:ex3:words:0:pos":"pronoun","grammar:278:ex3:words:1:zh":"(topic)","grammar:278:ex3:words:1:pos":"particle","grammar:278:ex3:words:2:zh":"already","grammar:278:ex3:words:2:pos":"adverb","grammar:278:ex3:words:3:zh":"asleep","grammar:278:ex3:words:3:note":"ねている","grammar:278:ex3:words:3:pos":"verb","grammar:278:ex3:points:0":"もう寝ている: is already sleeping.","grammar:278:ex3:points:1":"〜ている: (asleep) state.","grammar:278:ex4:trans":"I like sleeping.","grammar:278:ex4:structure":"〜のが好き","grammar:278:ex4:words:0:zh":"sleep","grammar:278:ex4:words:0:note":"ねる","grammar:278:ex4:words:0:pos":"verb","grammar:278:ex4:words:1:zh":"(nominalizer)","grammar:278:ex4:words:1:pos":"particle","grammar:278:ex4:words:2:zh":"(object)","grammar:278:ex4:words:2:pos":"particle","grammar:278:ex4:words:3:zh":"to like","grammar:278:ex4:words:3:note":"すき","grammar:278:ex4:words:3:pos":"na-adjective","grammar:278:ex4:points:0":"〜のが好き: to like doing…","grammar:278:ex4:points:1":"寝るのが好き: to like sleeping.","grammar:278:ex5:trans":"Go to bed early every day.","grammar:278:ex5:structure":"毎日〜寝る","grammar:278:ex5:words:0:zh":"every day","grammar:278:ex5:words:0:note":"まいにち","grammar:278:ex5:words:0:pos":"adverb","grammar:278:ex5:words:1:zh":"early (as an adverb)","grammar:278:ex5:words:1:note":"はやく","grammar:278:ex5:words:1:pos":"adverb","grammar:278:ex5:words:2:zh":"sleep","grammar:278:ex5:words:2:note":"ねる","grammar:278:ex5:words:2:pos":"verb","grammar:278:ex5:points:0":"毎日: every day.","grammar:278:ex5:points:1":"早く寝る: to go to bed early.","exam:278:zh":"I'm really sleepy, so I plan to go to bed early tonight.","exam:278:why":"「眠い」 means sleepy, so it fits with 「寝る」. 「起きる」 means to get up, not to go to bed."},"284":{"example:284:exzh":"He can say anything.","example:284:exzh2":"Some people can't say what they like.","example:284:exzh3":"I wish I could tell the truth.","example:284:exzh4":"Can you express your own opinion?","example:284:exzh5":"She seems unable to say what she really feels.","grammar:284:ex:trans":"He can say anything.","grammar:284:ex:structure":"何でも言えます","grammar:284:ex:explain":"The key word is 「言える」, the potential form of 「言う」 (to say), meaning can say, is able to say. To make the potential form of a godan verb, change the final u-row sound to the e-row and add 「る」: 「言う」 becomes 「言える」. 「何でも」 means anything, whatever. 「言えます」 is the polite form of the potential verb. The whole sentence 「彼は何でも言えます」 means he can say anything (he dares to say anything). The potential form expresses having the ability or the conditions to do something.","grammar:284:ex:words:0:zh":"he","grammar:284:ex:words:0:note":"かれ","grammar:284:ex:words:0:pos":"pronoun","grammar:284:ex:words:1:zh":"(topic)","grammar:284:ex:words:1:pos":"particle","grammar:284:ex:words:2:zh":"anything","grammar:284:ex:words:2:note":"なんでも","grammar:284:ex:words:2:pos":"adverb","grammar:284:ex:words:3:zh":"can say","grammar:284:ex:words:3:note":"いえます","grammar:284:ex:words:3:pos":"verb","grammar:284:ex:points:0":"❗言える: can say (potential form of 言う).","grammar:284:ex:points:1":"何でも言える: can say anything.","grammar:284:ex2:trans":"Some people can't say the things they like.","grammar:284:ex2:structure":"〜を言えない人もいる","grammar:284:ex2:words:0:zh":"to like","grammar:284:ex2:words:0:note":"すき","grammar:284:ex2:words:0:pos":"na-adjective","grammar:284:ex2:words:1:zh":"(attributive form)","grammar:284:ex2:words:1:pos":"auxiliary verb","grammar:284:ex2:words:2:zh":"thing / matter","grammar:284:ex2:words:2:pos":"noun","grammar:284:ex2:words:3:zh":"(object marker)","grammar:284:ex2:words:3:pos":"particle","grammar:284:ex2:words:4:zh":"can't say","grammar:284:ex2:words:4:note":"いえない","grammar:284:ex2:words:4:pos":"verb","grammar:284:ex2:words:5:zh":"person","grammar:284:ex2:words:5:note":"ひと","grammar:284:ex2:words:5:pos":"noun","grammar:284:ex2:words:6:zh":"also, too","grammar:284:ex2:words:6:pos":"particle","grammar:284:ex2:words:7:zh":"there is / are","grammar:284:ex2:words:7:pos":"verb","grammar:284:ex2:points:0":"言えない: can't say (negative potential).","grammar:284:ex2:points:1":"〜人もいる: there are also people who…","grammar:284:ex3:trans":"If only I could tell the truth.","grammar:284:ex3:structure":"〜を言えたらいいのに","grammar:284:ex3:words:0:zh":"the truth","grammar:284:ex3:words:0:note":"しんじつ","grammar:284:ex3:words:0:pos":"noun","grammar:284:ex3:words:1:zh":"(object marker)","grammar:284:ex3:words:1:pos":"particle","grammar:284:ex3:words:2:zh":"if I could say","grammar:284:ex3:words:2:note":"いえたら","grammar:284:ex3:words:2:pos":"verb","grammar:284:ex3:words:3:zh":"if only","grammar:284:ex3:words:3:pos":"set phrase","grammar:284:ex3:points:0":"❗〜たらいいのに: (it's a shame that) if only … .","grammar:284:ex3:points:1":"真実を言う: tell the truth.","grammar:284:ex4:trans":"Can you express your own opinion?","grammar:284:ex4:structure":"〜を言えますか","grammar:284:ex4:words:0:zh":"oneself","grammar:284:ex4:words:0:note":"じぶん","grammar:284:ex4:words:0:pos":"noun","grammar:284:ex4:words:1:zh":"'s","grammar:284:ex4:words:1:pos":"particle","grammar:284:ex4:words:2:zh":"opinion","grammar:284:ex4:words:2:note":"いけん","grammar:284:ex4:words:2:pos":"noun","grammar:284:ex4:words:3:zh":"(object marker)","grammar:284:ex4:words:3:pos":"particle","grammar:284:ex4:words:4:zh":"can say","grammar:284:ex4:words:4:note":"いえます","grammar:284:ex4:words:4:pos":"verb","grammar:284:ex4:words:5:zh":"(question)","grammar:284:ex4:words:5:pos":"particle","grammar:284:ex4:points:0":"❗自分の意見: one's own opinion.","grammar:284:ex4:points:1":"言える: can say (potential form).","grammar:284:ex5:trans":"She seems unable to say what she really thinks.","grammar:284:ex5:structure":"〜を言えないようです","grammar:284:ex5:words:0:zh":"she","grammar:284:ex5:words:0:note":"かのじょ","grammar:284:ex5:words:0:pos":"pronoun","grammar:284:ex5:words:1:zh":"(topic)","grammar:284:ex5:words:1:pos":"particle","grammar:284:ex5:words:2:zh":"true feelings","grammar:284:ex5:words:2:note":"ほんしん","grammar:284:ex5:words:2:pos":"noun","grammar:284:ex5:words:3:zh":"(object marker)","grammar:284:ex5:words:3:pos":"particle","grammar:284:ex5:words:4:zh":"can't say","grammar:284:ex5:words:4:note":"いえない","grammar:284:ex5:words:4:pos":"verb","grammar:284:ex5:words:5:zh":"seems","grammar:284:ex5:words:5:pos":"set phrase","grammar:284:ex5:words:6:zh":"(polite form)","grammar:284:ex5:words:6:pos":"copula","grammar:284:ex5:points:0":"❗〜ようです: it seems that … (conjecture).","grammar:284:ex5:points:1":"本心: true feelings.","exam:284:zh":"When I see my teacher in the morning, I make a point of saying 「おはようございます」.","exam:284:why":"Saying a greeting to someone you meet is 「言う」. 「聞く」 means to listen or to ask, and it can't express greeting your teacher."},"286":{"example:286:exzh":"I want to know about the usage of this word.","example:286:exzh2":"This software is for work.","example:286:exzh3":"He found a new use.","example:286:exzh4":"The things you have to do are important.","example:286:exzh5":"This tool has many different uses.","grammar:286:ex:trans":"I want to know how this word is used.","grammar:286:ex:structure":"〜について知りたい","grammar:286:ex:explain":"「〜について」 is a set pattern meaning about… or regarding…; it introduces the topic you are talking or learning about, so 「この言葉の用法について」 means about how this word is used. 「用法（ようほう）」 is a noun made from 「用」 + 「法」, meaning usage. 「知りたい」 is 「知る」 (to know) plus 「たい」 (to want), meaning want to know. The whole sentence means I want to learn how this word is used.","grammar:286:ex:words:0:zh":"this","grammar:286:ex:words:0:pos":"pre-noun adjectival","grammar:286:ex:words:1:zh":"word","grammar:286:ex:words:1:note":"ことば","grammar:286:ex:words:1:pos":"noun","grammar:286:ex:words:2:zh":"'s","grammar:286:ex:words:2:pos":"particle","grammar:286:ex:words:3:zh":"usage","grammar:286:ex:words:3:note":"ようほう","grammar:286:ex:words:3:pos":"noun","grammar:286:ex:words:4:zh":"about","grammar:286:ex:words:4:pos":"set phrase","grammar:286:ex:words:5:zh":"want to know","grammar:286:ex:words:5:note":"しりたい","grammar:286:ex:words:5:pos":"verb","grammar:286:ex:points:0":"用法（ようほう）: usage (用 + 法).","grammar:286:ex:points:1":"〜について: about…","grammar:286:ex2:trans":"This software is for work.","grammar:286:ex2:structure":"〜は、noun＋用です","grammar:286:ex2:explain":"「この」 directly modifies 「ソフトウェア」, meaning this software. 「は」 brings the software up as the topic. 「用」 is a suffix read 「よう」; attached to 「仕事」 it forms 「仕事用」, meaning for work use. 「です」 is the polite ending for a noun predicate, and the whole sentence explains what this software is for.","grammar:286:ex2:words:0:zh":"this","grammar:286:ex2:words:0:pos":"pre-noun adjectival","grammar:286:ex2:words:1:zh":"software","grammar:286:ex2:words:1:pos":"noun","grammar:286:ex2:words:2:zh":"(topic)","grammar:286:ex2:words:2:pos":"particle","grammar:286:ex2:words:3:zh":"work","grammar:286:ex2:words:3:note":"しごと","grammar:286:ex2:words:3:pos":"noun","grammar:286:ex2:words:4:zh":"for the use of…","grammar:286:ex2:words:4:note":"よう","grammar:286:ex2:words:4:pos":"suffix","grammar:286:ex2:words:5:zh":"is (polite ending)","grammar:286:ex2:words:5:pos":"auxiliary verb","grammar:286:ex2:points:0":"「名詞＋用」 shows what an item is used for or who it is meant for.","grammar:286:ex2:points:1":"「この」 must be followed by a noun; it cannot stand alone to mean this thing.","grammar:286:ex3:trans":"He found a new use for it.","grammar:286:ex3:structure":"〜を見つけた","grammar:286:ex3:words:0:zh":"he","grammar:286:ex3:words:0:note":"かれ","grammar:286:ex3:words:0:pos":"pronoun","grammar:286:ex3:words:1:zh":"(topic)","grammar:286:ex3:words:1:pos":"particle","grammar:286:ex3:words:2:zh":"new","grammar:286:ex3:words:2:note":"あたらしい","grammar:286:ex3:words:2:pos":"adjective","grammar:286:ex3:words:3:zh":"use, purpose","grammar:286:ex3:words:3:note":"よう","grammar:286:ex3:words:3:pos":"noun","grammar:286:ex3:words:4:zh":"(object marker)","grammar:286:ex3:words:4:pos":"particle","grammar:286:ex3:words:5:zh":"found","grammar:286:ex3:words:5:note":"みつけた","grammar:286:ex3:words:5:pos":"verb","grammar:286:ex3:points:0":"用（よう）: use, purpose.","grammar:286:ex3:points:1":"見つける: to find, to discover.","grammar:286:ex4:trans":"The things you need to do are important.","grammar:286:ex4:structure":"〜は大事なことだ","grammar:286:ex4:words:0:zh":"use, purpose","grammar:286:ex4:words:0:note":"よう","grammar:286:ex4:words:0:pos":"noun","grammar:286:ex4:words:1:zh":"(topic)","grammar:286:ex4:words:1:pos":"particle","grammar:286:ex4:words:2:zh":"important","grammar:286:ex4:words:2:note":"だいじ","grammar:286:ex4:words:2:pos":"na-adjective","grammar:286:ex4:words:3:zh":"(attributive form)","grammar:286:ex4:words:3:pos":"auxiliary verb","grammar:286:ex4:words:4:zh":"thing / matter","grammar:286:ex4:words:4:pos":"noun","grammar:286:ex4:words:5:zh":"is","grammar:286:ex4:words:5:pos":"copula","grammar:286:ex4:points:0":"用: use / usage.","grammar:286:ex4:points:1":"大事なこと: something important (な + noun).","grammar:286:ex5:trans":"This tool has a variety of uses.","grammar:286:ex5:structure":"〜は多様だ","grammar:286:ex5:words:0:zh":"this","grammar:286:ex5:words:0:pos":"pre-noun adjectival","grammar:286:ex5:words:1:zh":"tool","grammar:286:ex5:words:1:note":"どうぐ","grammar:286:ex5:words:1:pos":"noun","grammar:286:ex5:words:2:zh":"'s","grammar:286:ex5:words:2:pos":"particle","grammar:286:ex5:words:3:zh":"use, purpose","grammar:286:ex5:words:3:note":"よう","grammar:286:ex5:words:3:pos":"noun","grammar:286:ex5:words:4:zh":"(topic)","grammar:286:ex5:words:4:pos":"particle","grammar:286:ex5:words:5:zh":"varied, diverse","grammar:286:ex5:words:5:note":"たよう","grammar:286:ex5:words:5:pos":"na-adjective","grammar:286:ex5:words:6:zh":"is","grammar:286:ex5:words:6:pos":"copula","grammar:286:ex5:points:0":"道具の用: the tool's use.","grammar:286:ex5:points:1":"多様だ: diverse (na-adjective, plain form)."},"287":{"example:287:exzh":"My wife is very kind.","example:287:exzh2":"I want to go on a trip with my wife.","example:287:exzh3":"He loves his wife.","example:287:exzh4":"I celebrated my wife's birthday.","example:287:exzh5":"My wife is good at cooking.","grammar:287:ex:trans":"My wife is very gentle.","grammar:287:ex:structure":"〜は〜です","grammar:287:ex:explain":"The key word 「妻（つま）」 is a humble, fairly neutral way to refer to your own wife; for someone else's wife you use 「奥さん」, an important part of the in-group/out-group distinction in Japanese. In 「私の妻は」, 「は」 marks the topic; 「優しい」 is the i-adjective gentle, and 「とても」 means very. The whole sentence means my wife is very gentle. In the same way, you call your own husband 「夫（おっと）」 and someone else's husband 「ご主人」.","grammar:287:ex:words:0:zh":"I","grammar:287:ex:words:0:note":"わたし","grammar:287:ex:words:0:pos":"pronoun","grammar:287:ex:words:1:zh":"'s","grammar:287:ex:words:1:pos":"particle","grammar:287:ex:words:2:zh":"wife","grammar:287:ex:words:2:note":"つま","grammar:287:ex:words:2:pos":"noun","grammar:287:ex:words:3:zh":"(topic)","grammar:287:ex:words:3:pos":"particle","grammar:287:ex:words:4:zh":"extremely","grammar:287:ex:words:4:pos":"adverb","grammar:287:ex:words:5:zh":"kind","grammar:287:ex:words:5:note":"やさしい","grammar:287:ex:words:5:pos":"adjective","grammar:287:ex:words:6:zh":"(polite form)","grammar:287:ex:words:6:pos":"copula","grammar:287:ex:points:0":"❗妻（つま）: (humble) one's own wife; for someone else's wife use 奥さん.","grammar:287:ex:points:1":"優しい: gentle, kind.","grammar:287:ex2:trans":"I want to go on a trip with my wife.","grammar:287:ex2:structure":"〜と一緒に〜に行きたい","grammar:287:ex2:words:0:zh":"wife","grammar:287:ex2:words:0:note":"つま","grammar:287:ex2:words:0:pos":"noun","grammar:287:ex2:words:1:zh":"with","grammar:287:ex2:words:1:pos":"particle","grammar:287:ex2:words:2:zh":"together","grammar:287:ex2:words:2:note":"いっしょに","grammar:287:ex2:words:2:pos":"adverb","grammar:287:ex2:words:3:zh":"travel / trip","grammar:287:ex2:words:3:note":"りょこう","grammar:287:ex2:words:3:pos":"noun","grammar:287:ex2:words:4:zh":"(purpose)","grammar:287:ex2:words:4:pos":"particle","grammar:287:ex2:words:5:zh":"want to go","grammar:287:ex2:words:5:note":"いきたい","grammar:287:ex2:words:5:pos":"verb","grammar:287:ex2:points:0":"〜と一緒に: together with…","grammar:287:ex2:points:1":"旅行に行く: to go on a trip; 〜たい: to want to…","grammar:287:ex3:trans":"He loves his wife.","grammar:287:ex3:structure":"〜を愛しています","grammar:287:ex3:words:0:zh":"he","grammar:287:ex3:words:0:note":"かれ","grammar:287:ex3:words:0:pos":"pronoun","grammar:287:ex3:words:1:zh":"(topic)","grammar:287:ex3:words:1:pos":"particle","grammar:287:ex3:words:2:zh":"wife","grammar:287:ex3:words:2:note":"つま","grammar:287:ex3:words:2:pos":"noun","grammar:287:ex3:words:3:zh":"(object marker)","grammar:287:ex3:words:3:pos":"particle","grammar:287:ex3:words:4:zh":"loving","grammar:287:ex3:words:4:note":"あいしています","grammar:287:ex3:words:4:pos":"verb","grammar:287:ex3:points:0":"❓愛する takes を for its object (妻を愛する).","grammar:287:ex3:points:1":"〜ている：a continuing state.","grammar:287:ex4:trans":"I celebrated my wife's birthday.","grammar:287:ex4:structure":"〜を祝いました","grammar:287:ex4:words:0:zh":"wife","grammar:287:ex4:words:0:note":"つま","grammar:287:ex4:words:0:pos":"noun","grammar:287:ex4:words:1:zh":"'s","grammar:287:ex4:words:1:pos":"particle","grammar:287:ex4:words:2:zh":"birthday","grammar:287:ex4:words:2:note":"たんじょうび","grammar:287:ex4:words:2:pos":"noun","grammar:287:ex4:words:3:zh":"(object marker)","grammar:287:ex4:words:3:pos":"particle","grammar:287:ex4:words:4:zh":"celebrated","grammar:287:ex4:words:4:note":"いわいました","grammar:287:ex4:words:4:pos":"verb","grammar:287:ex4:points:0":"祝う: to celebrate, to congratulate.","grammar:287:ex4:points:1":"妻の誕生日: my wife's birthday.","grammar:287:ex5:trans":"My wife is good at cooking.","grammar:287:ex5:structure":"〜は〜が上手です","grammar:287:ex5:words:0:zh":"wife","grammar:287:ex5:words:0:note":"つま","grammar:287:ex5:words:0:pos":"noun","grammar:287:ex5:words:1:zh":"(topic)","grammar:287:ex5:words:1:pos":"particle","grammar:287:ex5:words:2:zh":"cooking","grammar:287:ex5:words:2:note":"りょうり","grammar:287:ex5:words:2:pos":"noun","grammar:287:ex5:words:3:zh":"(object)","grammar:287:ex5:words:3:pos":"particle","grammar:287:ex5:words:4:zh":"good at","grammar:287:ex5:words:4:note":"じょうず","grammar:287:ex5:words:4:pos":"na-adjective","grammar:287:ex5:words:5:zh":"(polite form)","grammar:287:ex5:words:5:pos":"copula","grammar:287:ex5:points:0":"The object of 「上手」 takes が (料理が上手).","grammar:287:ex5:points:1":"妻: wife."},"288":{"example:288:exzh":"There are lots of photos in my album.","example:288:exzh2":"This photo is very beautiful.","example:288:exzh3":"I took a photo with a friend.","example:288:exzh4":"This photo is a memory.","example:288:exzh5":"She likes collecting photos.","grammar:288:ex:trans":"There are many photos in my album.","grammar:288:ex:structure":"〜には〜があります (〜 has 〜)","grammar:288:ex:explain":"「〜には〜がある」 means there is/are … in (a place). The place where something exists takes 「に」 plus 「は」 (adding a slight contrastive, topic-marking nuance), and the thing that exists takes 「が」. 「私のアルバムには」 means in my album, and 「たくさんの写真が」 means many photos, with 「たくさんの」 modifying the noun via 「の」. 「あります」 is the polite form of the existence verb (photos are inanimate). The whole sentence means there are many photos in my album.","grammar:288:ex:words:0:zh":"I","grammar:288:ex:words:0:note":"わたし","grammar:288:ex:words:0:pos":"pronoun","grammar:288:ex:words:1:zh":"'s","grammar:288:ex:words:1:pos":"particle","grammar:288:ex:words:2:zh":"album","grammar:288:ex:words:2:note":"loanword","grammar:288:ex:words:2:pos":"noun","grammar:288:ex:words:3:zh":"(location of existence)","grammar:288:ex:words:3:pos":"particle","grammar:288:ex:words:4:zh":"(contrast)","grammar:288:ex:words:4:pos":"particle","grammar:288:ex:words:5:zh":"a lot","grammar:288:ex:words:5:pos":"adverb","grammar:288:ex:words:6:zh":"'s","grammar:288:ex:words:6:pos":"particle","grammar:288:ex:words:7:zh":"photo","grammar:288:ex:words:7:note":"しゃしん","grammar:288:ex:words:7:pos":"noun","grammar:288:ex:words:8:zh":"(nominative)","grammar:288:ex:words:8:pos":"particle","grammar:288:ex:words:9:zh":"there is / are","grammar:288:ex:words:9:pos":"verb","grammar:288:ex:points:0":"〜には〜がある: there is/are … in…","grammar:288:ex:points:1":"たくさんの写真: many photos.","grammar:288:ex2:trans":"This photo is very beautiful.","grammar:288:ex2:structure":"〜はとても〜です","grammar:288:ex2:words:0:zh":"this","grammar:288:ex2:words:0:pos":"pre-noun adjectival","grammar:288:ex2:words:1:zh":"photo","grammar:288:ex2:words:1:note":"しゃしん","grammar:288:ex2:words:1:pos":"noun","grammar:288:ex2:words:2:zh":"(topic)","grammar:288:ex2:words:2:pos":"particle","grammar:288:ex2:words:3:zh":"extremely","grammar:288:ex2:words:3:pos":"adverb","grammar:288:ex2:words:4:zh":"beautiful","grammar:288:ex2:words:4:pos":"na-adjective","grammar:288:ex2:words:5:zh":"(polite form)","grammar:288:ex2:words:5:pos":"copula","grammar:288:ex2:points:0":"この写真: this photo.","grammar:288:ex2:points:1":"きれい: pretty, beautiful (na-adjective).","grammar:288:ex3:trans":"I took photos with a friend.","grammar:288:ex3:structure":"〜と〜を撮りました","grammar:288:ex3:words:0:zh":"friend","grammar:288:ex3:words:0:note":"ともだち","grammar:288:ex3:words:0:pos":"noun","grammar:288:ex3:words:1:zh":"with","grammar:288:ex3:words:1:pos":"particle","grammar:288:ex3:words:2:zh":"together","grammar:288:ex3:words:2:note":"いっしょに","grammar:288:ex3:words:2:pos":"adverb","grammar:288:ex3:words:3:zh":"photo","grammar:288:ex3:words:3:note":"しゃしん","grammar:288:ex3:words:3:pos":"noun","grammar:288:ex3:words:4:zh":"(object marker)","grammar:288:ex3:words:4:pos":"particle","grammar:288:ex3:words:5:zh":"took (a photo)","grammar:288:ex3:words:5:note":"とりました","grammar:288:ex3:words:5:pos":"verb","grammar:288:ex3:points:0":"写真を撮る: to take a photo.","grammar:288:ex3:points:1":"撮る→撮りました (dictionary form → polite past).","grammar:288:ex4:trans":"This photo is a memory.","grammar:288:ex4:structure":"〜は〜です","grammar:288:ex4:words:0:zh":"this","grammar:288:ex4:words:0:pos":"pre-noun adjectival","grammar:288:ex4:words:1:zh":"photo","grammar:288:ex4:words:1:note":"しゃしん","grammar:288:ex4:words:1:pos":"noun","grammar:288:ex4:words:2:zh":"(topic)","grammar:288:ex4:words:2:pos":"particle","grammar:288:ex4:words:3:zh":"memories","grammar:288:ex4:words:3:note":"おもいで","grammar:288:ex4:words:3:pos":"noun","grammar:288:ex4:words:4:zh":"is","grammar:288:ex4:words:4:pos":"copula","grammar:288:ex4:points:0":"思い出: memory.","grammar:288:ex4:points:1":"この写真は思い出: this photo is a memory.","grammar:288:ex5:trans":"She likes collecting photos.","grammar:288:ex5:structure":"〜のが好きです","grammar:288:ex5:words:0:zh":"she","grammar:288:ex5:words:0:note":"かのじょ","grammar:288:ex5:words:0:pos":"pronoun","grammar:288:ex5:words:1:zh":"(topic)","grammar:288:ex5:words:1:pos":"particle","grammar:288:ex5:words:2:zh":"photo","grammar:288:ex5:words:2:note":"しゃしん","grammar:288:ex5:words:2:pos":"noun","grammar:288:ex5:words:3:zh":"(object marker)","grammar:288:ex5:words:3:pos":"particle","grammar:288:ex5:words:4:zh":"collect","grammar:288:ex5:words:4:note":"あつめる","grammar:288:ex5:words:4:pos":"verb","grammar:288:ex5:words:5:zh":"(nominalizer)","grammar:288:ex5:words:5:pos":"particle","grammar:288:ex5:words:6:zh":"(object)","grammar:288:ex5:words:6:pos":"particle","grammar:288:ex5:words:7:zh":"to like","grammar:288:ex5:words:7:note":"すき","grammar:288:ex5:words:7:pos":"na-adjective","grammar:288:ex5:words:8:zh":"(polite form)","grammar:288:ex5:words:8:pos":"copula","grammar:288:ex5:points:0":"〜のが好き: to like doing…","grammar:288:ex5:points:1":"写真を集める: to collect photos.","exam:288:zh":"I put the photos I took with my camera on the trip into the album.","exam:288:why":"What you take with a camera and put in an album is 「写真」. 「地図」 is also related to travel, but it isn't the photos you take and keep here."},"289":{"example:289:exzh":"This town is lively.","example:289:exzh2":"I like walking around town.","example:289:exzh3":"There are many shops in town.","example:289:exzh4":"The town at night is special.","example:289:exzh5":"This town has a long history."},"291":{"example:291:exzh":"Please come over to my place.","example:291:exzh2":"We're a family of four.","example:291:exzh3":"Our dog is very cute.","example:291:exzh4":"Our house is in a quiet place.","example:291:exzh5":"Flowers are blooming in our garden.","grammar:291:ex:trans":"Please come over to my place.","grammar:291:ex:structure":"うちに〜に来てください","grammar:291:ex:explain":"The key point: when the kanji 「家」 is read 「うち」, it means my home, my side, my own place, with a friendly sense of belonging to my group (read 「いえ」, it refers more to the physical house). The 「に」 in 「うちに」 marks the destination. 「遊びに来る」 is the verb stem plus 「に来る」, meaning to come in order to do…, so 「遊びに来る」 means to come over and hang out. 「〜てください」 is a polite request. The whole sentence means please come over to my place.","grammar:291:ex:words:0:zh":"house","grammar:291:ex:words:0:pos":"noun","grammar:291:ex:words:1:zh":"(destination)","grammar:291:ex:words:1:pos":"particle","grammar:291:ex:words:2:zh":"hang out","grammar:291:ex:words:2:note":"あそび","grammar:291:ex:words:2:pos":"noun","grammar:291:ex:words:3:zh":"(purpose)","grammar:291:ex:words:3:pos":"particle","grammar:291:ex:words:4:zh":"come","grammar:291:ex:words:4:note":"きて","grammar:291:ex:words:4:pos":"verb","grammar:291:ex:words:5:zh":"please","grammar:291:ex:words:5:pos":"auxiliary verb","grammar:291:ex:points:1":"遊びに来る: to come over and hang out.","grammar:291:ex2:trans":"There are four people in our family.","grammar:291:ex2:structure":"うちは〜です","grammar:291:ex2:words:0:zh":"house","grammar:291:ex2:words:0:pos":"noun","grammar:291:ex2:words:1:zh":"(topic)","grammar:291:ex2:words:1:pos":"particle","grammar:291:ex2:words:2:zh":"four people","grammar:291:ex2:words:2:note":"よにん","grammar:291:ex2:words:2:pos":"noun","grammar:291:ex2:words:3:zh":"family","grammar:291:ex2:words:3:note":"かぞく","grammar:291:ex2:words:3:pos":"noun","grammar:291:ex2:words:4:zh":"is","grammar:291:ex2:words:4:pos":"copula","grammar:291:ex2:points:0":"うち: my home, our home.","grammar:291:ex2:points:1":"四人家族: a family of four.","grammar:291:ex3:trans":"Our dog is very cute.","grammar:291:ex3:structure":"うちの〜は〜です","grammar:291:ex3:words:0:zh":"house","grammar:291:ex3:words:0:pos":"noun","grammar:291:ex3:words:1:zh":"'s","grammar:291:ex3:words:1:pos":"particle","grammar:291:ex3:words:2:zh":"dog","grammar:291:ex3:words:2:note":"いぬ","grammar:291:ex3:words:2:pos":"noun","grammar:291:ex3:words:3:zh":"(topic)","grammar:291:ex3:words:3:pos":"particle","grammar:291:ex3:words:4:zh":"extremely","grammar:291:ex3:words:4:pos":"adverb","grammar:291:ex3:words:5:zh":"cute","grammar:291:ex3:words:5:pos":"adjective","grammar:291:ex3:words:6:zh":"(polite form)","grammar:291:ex3:words:6:pos":"copula","grammar:291:ex3:points:0":"うちの犬: our dog.","grammar:291:ex3:points:1":"かわいい: cute (i-adjective).","grammar:291:ex4:trans":"Our house is in a quiet place.","grammar:291:ex4:structure":"うちは〜にあります","grammar:291:ex4:words:0:zh":"house","grammar:291:ex4:words:0:pos":"noun","grammar:291:ex4:words:1:zh":"(topic)","grammar:291:ex4:words:1:pos":"particle","grammar:291:ex4:words:2:zh":"quiet","grammar:291:ex4:words:2:note":"しずか","grammar:291:ex4:words:2:pos":"na-adjective","grammar:291:ex4:words:3:zh":"(attributive form)","grammar:291:ex4:words:3:pos":"auxiliary verb","grammar:291:ex4:words:4:zh":"place","grammar:291:ex4:words:4:pos":"noun","grammar:291:ex4:words:5:zh":"(location of existence)","grammar:291:ex4:words:5:pos":"particle","grammar:291:ex4:words:6:zh":"exist","grammar:291:ex4:words:6:pos":"verb","grammar:291:ex4:points:0":"静かなところ: a quiet place (な + noun).","grammar:291:ex4:points:1":"❓A house (a thing) → あります.","grammar:291:ex5:trans":"Flowers are blooming in our garden.","grammar:291:ex5:structure":"〜には〜が咲いています","grammar:291:ex5:words:0:zh":"house","grammar:291:ex5:words:0:pos":"noun","grammar:291:ex5:words:1:zh":"'s","grammar:291:ex5:words:1:pos":"particle","grammar:291:ex5:words:2:zh":"garden","grammar:291:ex5:words:2:note":"にわ","grammar:291:ex5:words:2:pos":"noun","grammar:291:ex5:words:3:zh":"(location of existence)","grammar:291:ex5:words:3:pos":"particle","grammar:291:ex5:words:4:zh":"(contrast)","grammar:291:ex5:words:4:pos":"particle","grammar:291:ex5:words:5:zh":"flowers","grammar:291:ex5:words:5:note":"はな","grammar:291:ex5:words:5:pos":"noun","grammar:291:ex5:words:6:zh":"(nominative)","grammar:291:ex5:words:6:pos":"particle","grammar:291:ex5:words:7:zh":"are blooming","grammar:291:ex5:words:7:note":"さいています","grammar:291:ex5:words:7:pos":"verb","grammar:291:ex5:points:0":"咲く: (for a flower) to bloom (intransitive verb; the subject takes が).","grammar:291:ex5:points:1":"〜ている: (blooming) state.","exam:291:zh":"Work is over, so I'm going back to the home where I live with my family.","exam:291:why":"The place where you live with your family and return to after work is your 「家」. 「会社」 is the place you work, which doesn't fit the living situation in the sentence."},"292":{"example:292:exzh":"She has a special sense.","example:292:exzh2":"I think feeling is important.","example:292:exzh3":"This work has a deep feeling to it.","example:292:exzh4":"Has your feeling changed?","example:292:exzh5":"I felt something from what he said."},"294":{"example:294:exzh":"That doctor is teaching science to the children.","example:294:exzh2":"I got my doctorate.","example:294:exzh3":"The doctor keeps researching new drugs.","example:294:exzh4":"I decided to go on to a doctoral program.","example:294:exzh5":"My little brother is called 「虫博士」 by his friends."},"295":{"example:295:exzh":"Please explain this problem.","example:295:exzh2":"The explanation was easy to understand.","example:295:exzh3":"He explained in detail.","example:295:exzh4":"Did you read the manual?","example:295:exzh5":"This explanation is clear.","grammar:295:ex:trans":"Please explain this problem.","grammar:295:ex:structure":"〜について説明してください","grammar:295:ex:explain":"「〜について」 means “about …” and introduces the topic being explained, so 「この問題について」 means “about this problem.” 「説明（せつめい）する」 means “to explain,” and 「説明して」 is its te-form; with 「ください」 it forms the polite request “please explain.” The whole sentence means “Please explain this problem.” The combination 「〜について」＋verb is a common and very useful way to discuss or explain a topic.","grammar:295:ex:words:0:zh":"this","grammar:295:ex:words:0:pos":"pre-noun adjectival","grammar:295:ex:words:1:zh":"problem","grammar:295:ex:words:1:note":"もんだい","grammar:295:ex:words:1:pos":"noun","grammar:295:ex:words:2:zh":"about","grammar:295:ex:words:2:pos":"set phrase","grammar:295:ex:words:3:zh":"explain","grammar:295:ex:words:3:note":"せつめいして","grammar:295:ex:words:3:pos":"verb","grammar:295:ex:words:4:zh":"please","grammar:295:ex:words:4:pos":"auxiliary verb","grammar:295:ex:points:0":"〜について: about…","grammar:295:ex:points:1":"説明する→説明して＋ください。","grammar:295:ex2:trans":"The explanation was easy to understand.","grammar:295:ex2:structure":"〜がわかりやすかったです","grammar:295:ex2:words:0:zh":"explanation","grammar:295:ex2:words:0:note":"せつめい","grammar:295:ex2:words:0:pos":"noun","grammar:295:ex2:words:1:zh":"(nominative)","grammar:295:ex2:words:1:pos":"particle","grammar:295:ex2:words:2:zh":"(past) easy to understand","grammar:295:ex2:words:2:pos":"adjective","grammar:295:ex2:words:3:zh":"(polite form)","grammar:295:ex2:words:3:pos":"copula","grammar:295:ex2:points:0":"わかりやすい: easy to understand (わかる＋やすい).","grammar:295:ex2:points:1":"わかりやすかった: was easy to understand (past form of an i-adjective).","grammar:295:ex3:trans":"He explained in detail.","grammar:295:ex3:structure":"〜に説明しました","grammar:295:ex3:words:0:zh":"he","grammar:295:ex3:words:0:note":"かれ","grammar:295:ex3:words:0:pos":"pronoun","grammar:295:ex3:words:1:zh":"(topic)","grammar:295:ex3:words:1:pos":"particle","grammar:295:ex3:words:2:zh":"in detail","grammar:295:ex3:words:2:note":"しょうさいに","grammar:295:ex3:words:2:pos":"adverb","grammar:295:ex3:words:3:zh":"explained","grammar:295:ex3:words:3:note":"せつめいしました","grammar:295:ex3:words:3:pos":"verb","grammar:295:ex3:points:0":"詳細に: in detail (a na-adjective＋に turns it into an adverb).","grammar:295:ex3:points:1":"説明する→説明しました。","grammar:295:ex4:trans":"Have you read the manual?","grammar:295:ex4:structure":"〜を読みましたか","grammar:295:ex4:words:0:zh":"manual","grammar:295:ex4:words:0:note":"せつめいしょ","grammar:295:ex4:words:0:pos":"noun","grammar:295:ex4:words:1:zh":"(object marker)","grammar:295:ex4:words:1:pos":"particle","grammar:295:ex4:words:2:zh":"read (past)","grammar:295:ex4:words:2:note":"よみました","grammar:295:ex4:words:2:pos":"verb","grammar:295:ex4:words:3:zh":"(question)","grammar:295:ex4:words:3:pos":"particle","grammar:295:ex4:points:0":"説明書: manual (説明＋書).","grammar:295:ex4:points:1":"読む→読みました。","grammar:295:ex5:trans":"This explanation is clear.","grammar:295:ex5:structure":"〜は明確です","grammar:295:ex5:words:0:zh":"this","grammar:295:ex5:words:0:pos":"pre-noun adjectival","grammar:295:ex5:words:1:zh":"explanation","grammar:295:ex5:words:1:note":"せつめい","grammar:295:ex5:words:1:pos":"noun","grammar:295:ex5:words:2:zh":"(topic)","grammar:295:ex5:words:2:pos":"particle","grammar:295:ex5:words:3:zh":"clear","grammar:295:ex5:words:3:note":"めいかく","grammar:295:ex5:words:3:pos":"na-adjective","grammar:295:ex5:words:4:zh":"(polite form)","grammar:295:ex5:words:4:pos":"copula","grammar:295:ex5:points:0":"明確: clear, precise (na-adjective).","grammar:295:ex5:points:1":"この説明: this explanation."}};